INSERT INTO public.noticias (
  id, titulo, slug, resumo, conteudo, imagem_url,
  categoria_id, autor_id, data_publicacao, views, destaque, meta_title, meta_description
) VALUES
  ('41797226-f2f7-4805-8211-32a782414d4a', 'FenSeg alerta sobre riscos ao seguro de carro com adesivos eleitorais em 2026', 'fenseg-alerta-sobre-riscos-ao-seguro-de-carro-com-adesivos-eleitorais-em-2026', 'A Federação Nacional de Seguros Gerais (FenSeg) emitiu um alerta na última segunda-feira, 10 de agosto, direcionado a motoristas que pretendem adesivar ou utilizar seus veículos em campanhas...', 'A Federação Nacional de Seguros Gerais (FenSeg) emitiu um alerta na última segunda-feira, 10 de agosto, direcionado a motoristas que pretendem adesivar ou utilizar seus veículos em campanhas para as eleições de 2026. A entidade ressalta que a ausência de comunicação prévia à seguradora sobre tais modificações pode resultar no cancelamento da cobertura e na recusa de indenizações em situações de colisão, roubo ou furto.

De acordo com a FenSeg, o emprego do automóvel para fins publicitários ou em eventos públicos é interpretado como um fator de aumento de risco, elevando a exposição do bem a atos de vandalismo e acidentes. Adicionalmente, prejuízos específicos a adesivos, plotagens ou danos causados por tumultos, geralmente não estão incluídos na cobertura dos contratos de seguro convencionais. É crucial que qualquer alteração no perfil de uso, como o transporte de materiais de campanha ou a instalação de equipamentos de som, seja devidamente registrada em contrato, sob pena de o segurado perder os direitos previstos na apólice durante o período eleitoral.', 'https://imagemlink.cleissoncardoso.com/uploads/a233985a-4b6e-4363-816a-b36a6b0c8ae0.png', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-11 09:58:06.425+00', 2, false, 'FenSeg alerta sobre riscos ao seguro de carro com adesivos eleitorais em 2026', 'A Federação Nacional de Seguros Gerais (FenSeg) emitiu um alerta na última segunda-feira, 10 de agosto, direcionado a motoristas que pretendem adesivar ou utilizar seus veículos em campanhas...'),
  ('01e30cb6-ab12-4e0a-b441-6bbc76b81277', 'Governador Jerônimo Rodrigues participa dos Festejos da Padroeira em Cícero Dantas', 'governador-jeronimo-rodrigues-participa-dos-festejos-da-padroeira-em-cicero-dantas', 'Governador Jerônimo Rodrigues participa neste sábado (15) dos Festejos da Padroeira Nossa Senhora do Bom Conselho, em Cícero Dantas.', '
O governador da Bahia, Jerônimo Rodrigues, estará em Cícero Dantas neste sábado, 15 de agosto, para participar dos Festejos da Padroeira Nossa Senhora do Bom Conselho.

A agenda está prevista para as 16h, no município localizado no Território de Identidade Semiárido Nordeste II.

A participação do governador foi comunicada pela Coordenação de Articulação Social, COAS, vinculada à Secretaria de Relações Institucionais, SERIN, do Governo da Bahia.

Os Festejos de Nossa Senhora do Bom Conselho fazem parte do calendário religioso e cultural de Cícero Dantas, reunindo moradores e visitantes em momentos de fé e celebração em homenagem à padroeira do município.

A presença de Jerônimo Rodrigues integra a agenda institucional do Governo da Bahia no interior do estado.', 'https://mkbnqyhvaozqfpmcyoyw.supabase.co/storage/v1/object/public/imagens/noticias/1786446731176_9p5vro0.webp', '1bff82e6-6033-4d75-8d04-e26d976c0a05', NULL, '2026-08-11 11:12:48.422+00', 13, true, 'Governador Jerônimo Rodrigues participa dos Festejos da Padroeira em C', 'Jerônimo Rodrigues participa dos Festejos de Nossa Senhora do Bom Conselho neste sábado (15), em Cícero Dantas, no Semiárido Nordeste II.'),
  ('b30fd1de-11d0-4060-bf96-60cedcaa36da', 'PRF apreende 59 vapes e 11 essências em ônibus que seguia para Cícero Dantas via Ribeira do Pombal', 'prf-apreende-59-vapes-e-11-essencias-em-onibus-que-seguia-para-cicero-dantas', 'A PRF apreendeu 59 cigarros eletrônicos e 11 essências em fiscalização na BR-116, em Jequié, encontrando-os em caixa enviada como encomenda no ônibus São Paulo–Ribeira do Pombal, com destino a Cícero Dantas.', 'A Polícia Rodoviária Federal (PRF) apreendeu 59 cigarros eletrônicos, popularmente conhecidos como vapes, e 11 essências durante uma fiscalização na BR-116, km 677, no trecho de Jequié, na sexta‑feira (7). Os produtos foram encontrados em uma caixa despachada como encomenda no compartimento de bagagens de um ônibus que operava na linha São Paulo–Ribeira do Pombal, com destino final em Cícero Dantas.

Conforme a Agência Nacional de Vigilância Sanitária (Anvisa), a comercialização e a importação desses dispositivos são proibidas. Por isso, a PRF encaminhou a mercadoria apreendida à Receita Federal, em Vitória da Conquista, para as providências cabíveis. A ação faz parte de um esforço de combate ao crime e reforça a fiscalização de produtos ilícitos no transporte interestadual.', 'https://uploads.psnoticias.com.br/2026/08/WhatsApp-Image-2026-08-10-at-09.46.07.png', '7d34292b-4217-4571-ba21-f7aa996aa1d3', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-11 11:25:52.491992+00', 110, true, 'PRF apreende 59 vapes e 11 essências em ônibus via Ribeira do Pombal', 'Polícia Rodoviária Federal apreende 59 vapes e 11 essências na BR-116, Jequié, encontrados em caixa transportada no ônibus São Paulo–Ribeira do Pombal, destino Cícero Dantas.'),
  ('4993c306-d171-4560-a6b8-4ab2fa5f0607', 'Rui Costa e Jaques Wagner lideram disputa pelas vagas do Senado da Bahia', 'rui-costa-e-jaques-wagner-lideram-disputa-pelas-vagas-do-senado-da-bahia', 'A pesquisa Real Time Big Data, divulgada nesta terça‑feira (11), aponta Rui Costa (PT) com 25% das intenções de voto e Jaques Wagner (PT) com 20%, liderando a corrida pelas duas vagas do Sen...', 'A pesquisa Real Time Big Data, divulgada nesta terça‑feira (11), aponta Rui Costa (PT) com 25% das intenções de voto e Jaques Wagner (PT) com 20%, liderando a corrida pelas duas vagas do Senado Federal da Bahia em 2026. O levantamento, que considera as duas escolhas feitas pelos eleitores e redistribui os percentuais para totalizar 100%, também mostra o senador Angelo Coronel (Republicanos) e o ex‑ministro João Roma (PL) empatados em 15% cada, dentro da margem de erro de dois pontos percentuais.  

Outros candidatos registram resultados modestos: a professora Delliana (PSOL) aparece com 5%, enquanto Carlos Sodré (Mobiliza), Marcelo Carvalho (Rede) e Marcelo Santtana (sem sigla) marcam 1% cada. Gregório Gould (UP) participou da pesquisa, mas ficou abaixo de 1%. Eleitores que deixaram a cédula em branco ou nula somam 9%, e 8% se declararam indecisos. A pesquisa entrevistou 1.600 eleitores da Bahia entre 6 e 10 de agosto de 2026, tem margem de erro de ±2 pontos percentuais e nível de confiança de 95%. O estudo foi contratado pelo próprio Real Time Big Data e registrado no TSE sob o protocolo BA‑00277/2026.', 'https://d1x4bjge7r9nas.cloudfront.net/wp-content/uploads/2026/07/17191420/Design-sem-nome-24.png', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-11 14:20:57.235+00', 0, false, 'Rui Costa e Jaques Wagner lideram disputa pelas vagas do Senado da Bahia', 'A pesquisa Real Time Big Data, divulgada nesta terça‑feira (11), aponta Rui Costa (PT) com 25% das intenções de voto e Jaques Wagner (PT) com 20%, liderando a corrida pelas duas vagas do Sen...'),
  ('df0e4388-ccf5-4e49-8e71-dcc016e6daaa', 'Pesquisa Real Time Big Data aponta empate técnico entre ACM Neto e Jerônimo na Bahia', 'pesquisa-real-time-big-data-aponta-empate-tecnico-entre-acm-neto-e-jeronimo-na-b', 'A corrida pelo Governo da Bahia permanece intensamente disputada, conforme evidenciado por uma nova pesquisa Real Time Big Data divulgada na terça-feira (11). No cenário estimulado, ACM Neto...', 'A corrida pelo Governo da Bahia permanece intensamente disputada, conforme evidenciado por uma nova pesquisa Real Time Big Data divulgada na terça-feira (11). No cenário estimulado, ACM Neto (União Brasil) registra 44% das intenções de voto, enquanto o governador Jerônimo Rodrigues (PT) aparece com 42%. A diferença de apenas dois pontos percentuais coloca os dois principais candidatos em um empate técnico, visto que o resultado está dentro da margem de erro do levantamento. Outros candidatos como Ronaldo Mansur (PSOL) e José Estevão (DC) pontuaram 2% e 1%, respectivamente, com Prof. Aroldo (UP) não obtendo pontuação. A pesquisa também indicou que 7% dos entrevistados pretendem votar em branco ou nulo, e 4% ainda se mostram indecisos.

Em uma simulação de segundo turno, a disputa entre ACM Neto e Jerônimo Rodrigues mantém o cenário de grande equilíbrio. Neto lidera numericamente com 45% das intenções de voto, contra 44% de Jerônimo. Nesta projeção, brancos e nulos somam 7%, e 4% dos eleitores não souberam ou não quiseram responder. O estudo da Real Time Big Data ouviu 1.600 eleitores em diversas localidades da Bahia entre os dias 6 e 10 de agosto de 2026. A pesquisa possui margem de erro de 2 pontos percentuais para mais ou para menos, com um nível de confiança de 95%, e está devidamente registrada no Tribunal Regional Eleitoral da Bahia (TRE-BA) sob o número BA-00277/2026. Este cenário reforça a continuidade de uma das principais batalhas políticas do estado, iniciada nas eleições de 2022.', 'https://d1x4bjge7r9nas.cloudfront.net/wp-content/uploads/2026/08/10083532/WhatsApp-Image-2026-08-10-at-08.34.59.jpeg', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-11 14:21:39.798+00', 0, false, 'Pesquisa Real Time Big Data aponta empate técnico entre ACM Neto e Jerônimo na Bahia', 'A corrida pelo Governo da Bahia permanece intensamente disputada, conforme evidenciado por uma nova pesquisa Real Time Big Data divulgada na terça-feira (11). No cenário estimulado, ACM Neto...'),
  ('33bd9d37-499d-4734-8623-e97b01d5eb15', 'Lula lidera com 56% contra Flávio Bolsonaro na Bahia, aponta pesquisa Real Time', 'lula-lidera-com-56-contra-flavio-bolsonaro-na-bahia-aponta-pesquisa-real-time', 'A pesquisa Real Time Big Data divulgada nesta semana indica que o presidente Luiz Inácio Lula da Silva (PT) tem 56% das intenções de voto na Bahia, enquanto o senador Flávio Bolsonaro (PL) r...', 'A pesquisa Real Time Big Data divulgada nesta semana indica que o presidente Luiz Inácio Lula da Silva (PT) tem 56% das intenções de voto na Bahia, enquanto o senador Flávio Bolsonaro (PL) registra 23%. Entre os demais candidatos, Renan Santos (Missão) aparece com 5%, Ronaldo Caiado (PSD) com 3%, e Romeu Zema (NOVO) e Augusto Cury (Avante) com 1% cada. Votos em branco ou nulos somam 5% e 4% dos entrevistados não sabem ou não responderam.

Em cenário de eventual segundo turno, a vantagem de Lula aumenta para 59% das intenções, contra 30% de Flávio, com brancos e nulos em 6% e indecisos em 5%. Na pesquisa espontânea, onde os nomes não são apresentados, Lula obtém 39% e Flávio 17%, com Renan Santos à frente em terceiro lugar (3%) e Caiado em 2%. O levantamento entrevistou 1.600 pessoas entre 6 e 10 de agosto, com margem de erro de dois pontos percentuais e nível de confiança de 95%. A pesquisa está registrada no TSE sob o número BA-00277/2026.', 'https://d1x4bjge7r9nas.cloudfront.net/wp-content/uploads/2026/08/10081634/WhatsApp-Image-2026-08-10-at-08.15.57-e1786360629673.jpeg', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-11 14:23:17.098+00', 0, false, 'Lula lidera com 56% contra Flávio Bolsonaro na Bahia, aponta pesquisa Real Time', 'A pesquisa Real Time Big Data divulgada nesta semana indica que o presidente Luiz Inácio Lula da Silva (PT) tem 56% das intenções de voto na Bahia, enquanto o senador Flávio Bolsonaro (PL) r...'),
  ('5725d403-d34e-4bee-83e1-e103a3401bd9', 'Operação Mobile fiscaliza lojas de celulares em Feira de Santana', 'operacao-mobile-fiscaliza-lojas-de-celulares-em-feira-de-santana', 'A Polícia Civil da Bahia, em parceria com a Secretaria da Fazenda do Estado (Sefaz), deu início nesta terça‑feira (11) a nova fase da Operação Mobile em Feira de Santana. O objetivo da ação ...', 'A Polícia Civil da Bahia, em parceria com a Secretaria da Fazenda do Estado (Sefaz), deu início nesta terça‑feira (11) a nova fase da Operação Mobile em Feira de Santana. O objetivo da ação é inspecionar estabelecimentos que comercializam aparelhos celulares, acessórios e que oferecem serviços de assistência técnica, verificando o cumprimento das normas de defesa do consumidor, tributárias, de telecomunicações e de propriedade industrial.

Durante as vistorias, os agentes buscam identificar irregularidades como a venda de celulares e acessórios sem homologação da Anatel, produtos falsificados ou que utilizem marcas registradas indevidamente, além de mercadorias comercializadas sem a documentação fiscal exigida. A operação também apura possíveis infrações administrativas e penais que possam surgir durante as diligências. A participação da Sefaz permite a análise detalhada da regularidade tributária dos itens encontrados, enquanto a Delegacia de Defesa do Consumidor (Decon), vinculada ao Departamento de Investigações Criminais (Deic), coordena a fiscalização. Os resultados das inspeções deverão embasar eventuais medidas administrativas ou criminais, caso sejam constatadas irregularidades nos estabelecimentos fiscalizados.', 'https://d1x4bjge7r9nas.cloudfront.net/wp-content/uploads/2026/08/11094412/WhatsApp-Image-2026-08-11-at-09.43.24-e1786452312728.jpeg', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-11 14:24:08.085+00', 1, false, 'Operação Mobile fiscaliza lojas de celulares em Feira de Santana', 'A Polícia Civil da Bahia, em parceria com a Secretaria da Fazenda do Estado (Sefaz), deu início nesta terça‑feira (11) a nova fase da Operação Mobile em Feira de Santana. O objetivo da ação ...'),
  ('d4193787-37b5-4402-a227-f8123cd4bd6e', 'Gusttavo Lima é condenado por expor número de telefone em música', 'gusttavo-lima-e-condenado-por-expor-numero-de-telefone-em-musica', 'A Justiça do Estado de Pernambuco determinou que o cantor Gusttavo Lima pague uma indenização de aproximadamente R$ 149 mil a um homem que teve seu número de telefone citado na canção “Bloqu...', 'A Justiça do Estado de Pernambuco determinou que o cantor Gusttavo Lima pague uma indenização de aproximadamente R$ 149 mil a um homem que teve seu número de telefone citado na canção “Bloqueado”. O valor corresponde aos R$ 70 mil fixados na decisão original, acrescidos de juros, correção monetária e honorários advocatícios. O processo tem como réus o próprio artista e a produtora Balada Eventos e Produções Ltda., que também responde pela divulgação da música.

Segundo a ação judicial, o proprietário do número passou a receber mensagens e ligações indesejadas a partir de 2021, quando a faixa foi lançada. Na letra, o número aparece associado a uma antiga paixão que o personagem não consegue mais contatar: “Me bateu uma saudade… 9xxx‑xxxx… Olha eu recaindo outra vez… Lembrei que ’tô bloqueado’”. A primeira decisão foi proferida em 2022; os réus recorreram à segunda instância, mas a Segunda Câmara Cível do Tribunal de Justiça de Pernambuco negou o pedido. Um novo recurso apresentado pela defesa ainda não foi julgado.', 'https://veja.abril.com.br/wp-content/uploads/2026/08/gusttavolima_ad2b8d.jpg?quality=70&strip=info&resize=1080,565&crop=1', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-11 15:46:13.228+00', 3, false, 'Gusttavo Lima é condenado por expor número de telefone em música', 'A Justiça do Estado de Pernambuco determinou que o cantor Gusttavo Lima pague uma indenização de aproximadamente R$ 149 mil a um homem que teve seu número de telefone citado na canção “Bloqu...'),
  ('c3f30de6-f88e-470a-bc97-6786df559079', 'Pesquisa indica queda nos custos da cesta básica em 26 capitais brasileiras em julho', 'pesquisa-indica-queda-nos-custos-da-cesta-basica-em-26-capitais-brasileiras-em-j', 'Uma pesquisa recente revelou que, no mês de julho, os preços da cesta básica apresentaram redução em 26 capitais do país. Entre elas, as maiores quedas foram registradas em Natal, Maceió, Be...', 'Uma pesquisa recente revelou que, no mês de julho, os preços da cesta básica apresentaram redução em 26 capitais do país. Entre elas, as maiores quedas foram registradas em Natal, Maceió, Belo Horizonte, Palmas e Rio de Janeiro, que se destacaram pelo recuo mais expressivo nos custos.

Esses resultados sugerem uma tendência de diminuição nos preços de alimentos básicos nas principais cidades analisadas, o que pode impactar positivamente o poder de compra das famílias brasileiras durante o período.', 'https://www.gov.br/conab/logo.png', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-11 21:04:31.161+00', 3, false, 'Pesquisa indica queda nos custos da cesta básica em 26 capitais brasileiras em julho', 'Uma pesquisa recente revelou que, no mês de julho, os preços da cesta básica apresentaram redução em 26 capitais do país. Entre elas, as maiores quedas foram registradas em Natal, Maceió, Be...'),
  ('bb9cc4f6-93d4-43e3-906d-b168c6ca864e', 'Mulher furta viatura da PM em Barra de São João, foge para Rio das Ostras e é presa após batida', 'mulher-furta-viatura-da-pm-em-barra-de-sao-joao-foge-para-rio-das-ostras-e-e-pre', 'Uma mulher de 29 anos foi detida no último domingo (9) após furtar uma viatura da Polícia Militar em Barra de São João, distrito de Casimiro de Abreu, na Região dos Lagos do Rio de Janeiro. ...', 'Uma mulher de 29 anos foi detida no último domingo (9) após furtar uma viatura da Polícia Militar em Barra de São João, distrito de Casimiro de Abreu, na Região dos Lagos do Rio de Janeiro. A suspeita fugiu com o veículo em direção a Rio das Ostras, onde perdeu o controle e colidiu contra uma contenção de um estabelecimento no bairro Costa Azul. Após o incidente, policiais efetuaram a prisão da mulher. A Polícia Militar informou que não houve registro de feridos na ocorrência.

A viatura, pertencente à 4ª Companhia do 32º BPM, teve seu furto comunicado à corporação, que imediatamente montou um cerco para localizar e interceptar o veículo. A suspeita, cuja identidade não foi divulgada, foi encaminhada para exame de alcoolemia e permanece presa, respondendo por furto qualificado devido ao prejuízo causado ao serviço público. A audiência de custódia está agendada para esta terça-feira (11). Dois policiais militares responsáveis pelo veículo foram presos administrativamente no batalhão e prestarão esclarecimentos sobre o caso, enquanto a corporação abriu um procedimento para apurar o acesso da mulher à viatura. O veículo recuperado passará por perícia e reparos antes de retornar ao serviço.', 'https://cdn.atarde.com.br/img/Artigo-Destaque/1390000/mulher-rouba-viatura-da-pm-foge-para-outra-cidade-0139827700202608111643.webp?xid=7169960', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-11 21:05:16.549+00', 3, false, 'Mulher furta viatura da PM em Barra de São João, foge para Rio das Ostras e é presa após batida', 'Uma mulher de 29 anos foi detida no último domingo (9) após furtar uma viatura da Polícia Militar em Barra de São João, distrito de Casimiro de Abreu, na Região dos Lagos do Rio de Janeiro. ...'),
  ('ac0aec04-f54d-4f9f-bdee-aed36cd4f10c', 'Globo planeja oferta de R$ 3 milhões para tirar Celso Portiolli do SBT', 'globo-planeja-oferta-de-r-3-milhoes-para-tirar-celso-portiolli-do-sbt', 'A TV Globo estaria planejando uma proposta para contratar o apresentador Celso Portiolli, atualmente no SBT. Na emissora desde 1993, Portiolli comanda o programa “Domingo Legal” e é conhecid...', 'A TV Globo estaria planejando uma proposta para contratar o apresentador Celso Portiolli, atualmente no SBT. Na emissora desde 1993, Portiolli comanda o programa “Domingo Legal” e é conhecido por sua grande audiência na televisão brasileira. Segundo informações do colunista Alessandro Lo-Bianco, a oferta da emissora carioca envolveria um salário de R$ 3 milhões mensais e a possibilidade de o comunicador ficar um ano fora do ar para se preparar para sua eventual estreia. A expectativa é que a proposta seja formalizada até dezembro deste ano.

O principal objetivo da TV Globo com a possível contratação seria fortalecer sua programação dominical, especialmente com a exibição de um game-show que seria transmitido após o "Fantástico". Esse formato de programa, de acordo com as informações divulgadas, teria provocado certa tensão e uma suposta rixa entre as atrações apresentadas por Luciano Huck e Eliana, que competem pelo público de domingo. A estratégia maior visa, segundo o colunista, reduzir a audiência do SBT, canal que atualmente se mantém em segundo lugar na disputa dominical, impulsionado pelos programas de Celso Portiolli e das irmãs Rebeca e Patricia Abravanel.', 'https://cdn.atarde.com.br/img/Artigo-Destaque/1390000/globo-investe-valor-milionario-em-celso-portiolli-0139826200202608111518.jpg?xid=7169871', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-11 21:05:36.326+00', 2, false, 'Globo planeja oferta de R$ 3 milhões para tirar Celso Portiolli do SBT', 'A TV Globo estaria planejando uma proposta para contratar o apresentador Celso Portiolli, atualmente no SBT. Na emissora desde 1993, Portiolli comanda o programa “Domingo Legal” e é conhecid...'),
  ('c30db234-5830-4a17-ab3e-6e1770943182', 'Multas de radares de velocidade ocultos ou sem sinalização serão anuladas', 'multas-de-radares-de-velocidade-ocultos-ou-sem-sinalizacao-serao-anuladas', 'O Projeto de Lei 2364/26, apresentado pelo deputado André Fernandes (PL‑CE), propõe alterar o Código de Trânsito Brasileiro para que radares e outros dispositivos de medição de velocidade se...', 'O Projeto de Lei 2364/26, apresentado pelo deputado André Fernandes (PL‑CE), propõe alterar o Código de Trânsito Brasileiro para que radares e outros dispositivos de medição de velocidade sejam instalados em locais visíveis aos condutores. O texto determina que infrações registradas por equipamentos escondidos, camuflados ou sem sinalização prévia sejam anuladas automaticamente, reforçando a ideia de que a fiscalização deve ter caráter educativo e preventivo.

A proposta está em análise na Câmara dos Deputados e será examinada pelas comissões de Administração e Serviço Público, de Viação e Transportes, e de Constituição, Justiça e Cidadania. Caso seja aprovada na Câmara e no Senado, seguirá para sanção presidencial. Entre os exemplos citados, destacam‑se os radares que mais multaram motoristas em Salvador no último ano, ressaltando a relevância da medida para todo o país.', 'https://midias.correio24horas.com.br/2026/08/11/projeto-vai-anular-multa-de-radar-de-velocidade-escondido-ou-sem-sinalizacao-3365885-article.webp', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-11 21:07:36.465+00', 3, false, 'Multas de radares de velocidade ocultos ou sem sinalização serão anuladas', 'O Projeto de Lei 2364/26, apresentado pelo deputado André Fernandes (PL‑CE), propõe alterar o Código de Trânsito Brasileiro para que radares e outros dispositivos de medição de velocidade se...'),
  ('c2477cb2-a794-45e2-8ca3-20fa777dc665', 'Homem é preso em Casa Nova suspeito de maus-tratos contra dois idosos de 86 anos', 'homem-e-preso-em-casa-nova-suspeito-de-maus-tratos-contra-dois-idosos-de-86-anos', 'Um homem de 28 anos, cuja identidade não foi divulgada, foi preso em flagrante nesta segunda-feira (10) em Casa Nova, no Vale do São Francisco, Bahia. Ele é suspeito de maus-tratos contra do...', 'Um homem de 28 anos, cuja identidade não foi divulgada, foi preso em flagrante nesta segunda-feira (10) em Casa Nova, no Vale do São Francisco, Bahia. Ele é suspeito de maus-tratos contra dois idosos, ambos de 86 anos. A ação da Polícia Civil ocorreu após denúncias sobre gritos de socorro e barulhos de objetos sendo quebrados em uma residência na Vila Massú. No local, foram encontrados objetos danificados, uma porta quebrada e porções de cocaína, que foram apreendidas.

De acordo com a Polícia Civil, as vítimas, que são portadoras de doenças crônicas e apresentam limitações de saúde, teriam passado períodos prolongados sem alimentação e os devidos cuidados. O suspeito foi encaminhado à unidade policial, onde passou por exames legais e permanece custodiado à disposição da Justiça. A prisão foi realizada pela Delegacia Territorial (DT/Casa Nova).', 'https://midias.correio24horas.com.br/2026/07/28/policia-civil-3352570-article.webp', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-11 21:08:10.916+00', 0, false, 'Homem é preso em Casa Nova suspeito de maus-tratos contra dois idosos de 86 anos', 'Um homem de 28 anos, cuja identidade não foi divulgada, foi preso em flagrante nesta segunda-feira (10) em Casa Nova, no Vale do São Francisco, Bahia. Ele é suspeito de maus-tratos contra do...'),
  ('890fca9c-78bf-4fb1-8417-e2df10843f6a', 'Cantor Thiago Servo pede exame de DNA de suposta filha de 13 anos', 'cantor-thiago-servo-pede-exame-de-dna-de-suposta-filha-de-13-anos', 'O cantor sertanejo Thiago Servo utilizou suas redes sociais, no Dia dos Pais, para desabafar sobre a complexa relação com sua suposta filha. Em uma publicação no Instagram, o artista solicit...', 'O cantor sertanejo Thiago Servo utilizou suas redes sociais, no Dia dos Pais, para desabafar sobre a complexa relação com sua suposta filha. Em uma publicação no Instagram, o artista solicitou a realização de um exame de DNA para comprovar a paternidade de uma garota de 13 anos, fruto de seu relacionamento anterior com Gabrielle Tacconi Huese. Servo alega estar sendo impedido de ter contato com a adolescente, expressando sua indignação: “Imagina você tirar o direito de uma filha, de uma criança conviver com o pai por orgulho, só para punir esse pai”. Ele, que já foi dupla da cantora Thaeme, busca agora oficializar sua relação paterna para poder assumir plenamente seus deveres.

A disputa judicial entre Thiago Servo e sua ex-namorada se estende por alguns anos. O cantor afirma ter pago pensão alimentícia por um longo período e, segundo relatos, teria sido preso anteriormente por uma dívida de R$ 500 mil, mesmo sem que a paternidade biológica da jovem fosse formalmente comprovada. A situação, conforme o artista, acarretou prejuízos significativos em sua carreira, culminando na perda de trabalhos. Atualmente, Thiago Servo busca a confirmação legal de sua paternidade, visando restabelecer o convívio e cumprir suas responsabilidades parentais.', 'https://cdn.atarde.com.br/img/Artigo-Destaque/1390000/cantor-sertanejo-pede-exame-de-dna-da-filha-de-13-0139814000202608101531.jpg?xid=7168762', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-11 21:08:22.77+00', 0, false, 'Cantor Thiago Servo pede exame de DNA de suposta filha de 13 anos', 'O cantor sertanejo Thiago Servo utilizou suas redes sociais, no Dia dos Pais, para desabafar sobre a complexa relação com sua suposta filha. Em uma publicação no Instagram, o artista solicit...'),
  ('e8357319-6b0d-479b-8c25-e9555b908ab7', 'Protesto em Cipó por paciente crítico bloqueia ponte; vaga para transferência é aguardada', 'protesto-em-cipo-por-paciente-critico-bloqueia-ponte-vaga-para-transferencia-e', 'Em Cipó, moradores protestaram na ponte municipal nesta terça-feira (11) pela transferência de um paciente crítico. Pneus foram incendiados e controlados. Uma vaga teria sido disponibilizada, mas aguarda confirmação oficial. A ponte foi liberada e o trânsito normalizado.', 'Moradores da cidade de Cipó, localizada no interior da Bahia, realizaram um protesto na ponte municipal nesta terça-feira (11). A manifestação teve como objetivo pressionar as autoridades pela transferência de um jovem paciente, que se encontra internado em estado crítico e aguardava por uma vaga de regulação hospitalar há vários dias. A mobilização gerou interrupção no tráfego local, com o bloqueio da via principal.

Durante o ato, pneus foram incendiados no local, mas as chamas foram prontamente controladas pelos próprios populares que participavam da mobilização. A Polícia Militar esteve presente para acompanhar a situação, garantindo a segurança dos envolvidos e a manutenção da ordem. Conforme informações preliminares obtidas no local, uma vaga para a transferência do paciente teria sido finalmente disponibilizada; contudo, a confirmação oficial da medida ainda é aguardada. Após a manifestação, a ponte foi liberada, e o fluxo de veículos na região começa a apresentar sinais de normalização, embora a intensidade e a lentidão no trânsito persistam por enquanto.', 'https://imagemlink.cleissoncardoso.com/uploads/f6058772-d419-4da7-9735-a4f97be7180a.png', '3949c67e-3936-409d-9600-28782301730d', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-11 22:07:36.42194+00', 1029, true, 'Cipó: Protesto por paciente crítico bloqueia ponte; vaga aguarda confirmação', 'Moradores de Cipó, na Bahia, realizaram protesto na ponte municipal pela transferência de um jovem em estado crítico. Pneus foram incendiados, e vaga para paciente aguarda confirmação. Trânsito normaliza.'),
  ('f9a60b86-cc55-4e40-a103-68e1ef523d42', 'Briga por poda de pé de manga resulta em tiroteio com duas mortes em São Domingos das Dores, MG', 'briga-por-poda-de-pe-de-manga-resulta-em-tiroteio-com-duas-mortes-em-sao-domingo', 'Dois moradores, Miguel Chagas da Silva, 76, e Eberto Silvestre Guimarães Barro, 41, foram mortos na noite de terça‑feira (11/8) em Córrego do Belém, zona rural de São Domingos das Dores, Min...', 'Dois moradores, Miguel Chagas da Silva, 76, e Eberto Silvestre Guimarães Barro, 41, foram mortos na noite de terça‑feira (11/8) em Córrego do Belém, zona rural de São Domingos das Dores, Minas Gerais, durante uma discussão pela poda de um pé de manga que ficava na divisa de suas propriedades.  

Segundo informações, Eberto, acompanhado de seu filho, tentou cortar a árvore. O filho acabou entrando em luta corporal com o idoso, tomou a arma de Miguel e disparou um tiro que o atingiu. O outro homem também foi alvejado. Ambos foram socorridos ao hospital, mas não resistiram. O filho permaneceu no local aguardando a chegada da polícia. Até o momento, não há informações sobre sua prisão e sua defesa não se manifestou. Os corpos foram encaminhados ao Instituto Médico Legal de Caratinga, e a Polícia Civil segue investigando o caso.', 'https://i.metroimg.com/XGLxRbMpMIFzBjWLyvar-IVg6m65mDlAzuGgOJ3Dmj8/rs:fill:1200:800:1/g:no/q:85/f:webp/plain/https://images.metroimg.com/2026/08/mortes-pe-de-manga.jpg', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-12 11:11:26.034+00', 4, false, 'Briga por poda de pé de manga resulta em tiroteio com duas mortes em São Domingos das Dores, MG', 'Dois moradores, Miguel Chagas da Silva, 76, e Eberto Silvestre Guimarães Barro, 41, foram mortos na noite de terça‑feira (11/8) em Córrego do Belém, zona rural de São Domingos das Dores, Min...'),
  ('51c2ec31-c8a7-4298-9c79-c83cf323043b', 'Luva de Pedreiro deve pagar mais de R$ 10 milhões após decisão do TJ-RJ', 'luva-de-pedreiro-deve-pagar-mais-de-r-10-milhoes-apos-decisao-do-tj-rj', 'O Tribunal de Justiça do Rio de Janeiro (21ª Câmara de Direito Privado) rejeitou, por unanimidade, o recurso apresentado por Iran Ferreira, conhecido como Luva de Pedreiro, contra a decisão ...', 'O Tribunal de Justiça do Rio de Janeiro (21ª Câmara de Direito Privado) rejeitou, por unanimidade, o recurso apresentado por Iran Ferreira, conhecido como Luva de Pedreiro, contra a decisão que reconheceu a validade do contrato de representação artística firmado com o ex‑empresário Allan Jesus. A corte restabeleceu a multa penal de R$ 5,2 milhões, manteve as indenizações por danos materiais e morais e considerou que não houve irregularidade nas alegações de analfabetismo funcional ou lesão apresentadas pelo influenciador. Os desembargadores ainda concluíram que houve ruptura unilateral e imotivada do contrato por parte de Luva de Pedreiro, bem como violação da cláusula de exclusividade, reforçando a validade do acordo. O fato de o influenciador ter passado a contar com assessoria jurídica sem impugnar os termos na época também foi considerado pelos magistrados.  

Com a decisão, o valor total da condenação ultrapassa os R$ 10 milhões, incluindo a multa, as indenizações, honorários de 10 % sobre o montante atualizado, custas processuais e encargos de atualização monetária. Foram também bloqueados depósitos judiciais superiores a R$ 4 milhões como garantia de futura execução. A sentença determinou que o autor arque integralmente com as custas processuais e honorários advocatícios. O julgamento contou com três votos favoráveis a Allan Jesus e à ASJ Consultoria, sem voto divergente. Luva de Pedreiro ainda pode recorrer às instâncias superiores, Supremo Tribunal Federal e Superior Tribunal de Justiça.', 'https://cdn.atarde.com.br/img/Artigo-Destaque/1390000/luva-de-pedreiro-tera-que-pagar-r-10-milhoes-apos-0139832500202608120721.jpg?xid=7170381', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-12 11:32:46.68+00', 5, false, 'Luva de Pedreiro deve pagar mais de R$ 10 milhões após decisão do TJ-RJ', 'O Tribunal de Justiça do Rio de Janeiro (21ª Câmara de Direito Privado) rejeitou, por unanimidade, o recurso apresentado por Iran Ferreira, conhecido como Luva de Pedreiro, contra a decisão ...'),
  ('0006d3fb-1e9b-4750-9cf0-f4595f611df1', 'INSS alerta: familiares não podem sacar pagamentos após falecimento do segurado', 'inss-alerta-familiares-nao-podem-sacar-pagamentos-apos-falecimento-do-segurado', 'O Instituto Nacional do Seguro Social (INSS) orienta que, quando o benefício continua sendo depositado na conta de um segurado falecido, os parentes não têm autorização para sacar ou movimen...', 'O Instituto Nacional do Seguro Social (INSS) orienta que, quando o benefício continua sendo depositado na conta de um segurado falecido, os parentes não têm autorização para sacar ou movimentar esses valores. A situação ocorre por atraso entre o registro do óbito, a comunicação às autoridades e a atualização dos sistemas da Previdência, o que pode fazer com que aposentadorias ou pensões sejam creditadas mesmo após a morte.

De acordo com a Lei nº 8.213/1991 e a Instrução Normativa nº 128/2022, os valores devidos até a data do falecimento devem ser destinados aos dependentes habilitados à pensão por morte ou, na ausência destes, aos herdeiros legais, obedecendo a ordem de sucessão do Código Civil. O chamado resíduo previdenciário pode ser solicitado via Meu INSS, telefone 135 ou presencialmente. Caso o pagamento seja sacado indevidamente, a prática pode ser enquadrada como estelionato, com pena de um a cinco anos de reclusão e multa, além da obrigação de devolução dos valores com atualização monetária. © DR', 'https://img-s-msn-com.akamaized.net/tenant/amp/entityid/AA1EBFLy.img?w=768&h=432&m=6', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-12 14:15:16.301+00', 2, false, 'INSS alerta: familiares não podem sacar pagamentos após falecimento do segurado', 'O Instituto Nacional do Seguro Social (INSS) orienta que, quando o benefício continua sendo depositado na conta de um segurado falecido, os parentes não têm autorização para sacar ou movimen...'),
  ('56deb46d-ce47-427d-a3fb-315ed46843ee', 'Carro colide com moto, capota e pega fogo na entrada de Cipó', 'carro-colide-com-moto-capota-e-pega-fogo-na-entrada-de-cipo', 'Carro colide com moto na entrada de Cipó, capota, incendeia e deixa duas pessoas feridas.', 'Na entrada da cidade de Cipó, um carro colidiu com uma motocicleta, desencadeando uma sequência de eventos graves.

Após a colisão, o veículo automotor capotou e incendiou‑se, ficando totalmente destruído. O acidente deixou duas pessoas feridas, que foram socorridas no local.', 'https://euclidesdiario.com/wp-content/uploads/2026/08/img_8952-1.jpg', '3949c67e-3936-409d-9600-28782301730d', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-12 20:25:08.088595+00', 109, true, 'Acidente com carro e moto incendeia na entrada de Cipó', 'Um carro colidiu com uma motocicleta na entrada de Cipó, capotou, pegou fogo e ficou destruído, deixando duas pessoas feridas.'),
  ('5900f254-5664-4b08-815d-db3425abb0a3', 'Projeto da Câmara prevê suspensão da CNH e multa para abandono de animais', 'projeto-da-camara-preve-suspensao-da-cnh-e-multa-para-abandono-de-animais', 'A Câmara dos Deputados aprovou um projeto de lei (PL 25/2024) que estabelece sanções severas para o abandono de animais nas ruas. O texto propõe a suspensão da Carteira Nacional de Habilitaç...', 'A Câmara dos Deputados aprovou um projeto de lei (PL 25/2024) que estabelece sanções severas para o abandono de animais nas ruas. O texto propõe a suspensão da Carteira Nacional de Habilitação (CNH) por 12 meses. Em casos de abandono de cães ou gatos, a suspensão da CNH pode se estender por até 18 meses.

Além da suspensão da CNH, o projeto prevê a aplicação de multa equivalente a dez vezes o valor de uma infração gravíssima, podendo chegar a R$ 3 mil. Essa multa pode dobrar se o abandono resultar na morte, atropelamento ou lesão do animal. Para motoristas que reincidirem na infração em um período de 24 meses, a penalidade será a cassação da Carteira Nacional de Habilitação. A proposta ainda será analisada pelo Senado.', 'https://imagemlink.cleissoncardoso.com/uploads/347bb45f-3512-4b23-870e-168722158c82.png', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-13 00:38:18.242+00', 4, false, 'Projeto da Câmara prevê suspensão da CNH e multa para abandono de animais', 'A Câmara dos Deputados aprovou um projeto de lei (PL 25/2024) que estabelece sanções severas para o abandono de animais nas ruas. O texto propõe a suspensão da Carteira Nacional de Habilitaç...'),
  ('c3e2b469-e715-4090-8a33-415d1817ba3d', 'Prefeito de Gongogi é alvo de operação da PF contra fraudes', 'prefeito-de-gongogi-e-alvo-de-operacao-da-pf-contra-fraudes', 'A Polícia Federal (PF) e a Controladoria‑Geral da União (CGU) iniciaram nesta quinta‑feira (13) a Operação Severus, segunda fase da Operação Pacto Infame, para aprofundar investigações sobre...', 'A Polícia Federal (PF) e a Controladoria‑Geral da União (CGU) iniciaram nesta quinta‑feira (13) a Operação Severus, segunda fase da Operação Pacto Infame, para aprofundar investigações sobre um possível esquema criminoso envolvendo contratações públicas no município de Gongogi, sul da Bahia. Foram cumpridos 33 mandados de busca e apreensão expedidos pelo Tribunal Regional Federal da 1ª Região (TRF1), também em Itabuna, Ilhéus, Dário Meira, Ipiaú, Ibicaraí, Valença e Eunápolis. A ação busca identificar a atuação de organização criminosa na administração municipal, com participação de agentes públicos e particulares, suspeita de fraudar licitações, desviar recursos, praticar corrupção e lavagem de dinheiro, inclusive com recursos federais.

Entre as irregularidades apontadas estão o suposto direcionamento de licitações, uso de documentos falsos, simulação de procedimentos administrativos e pagamentos por serviços não realizados ou parcialmente executados. Conforme a PF, os valores desviados teriam sido movimentados por meio de pessoas interpostas e empresas. A decisão judicial autorizou a apreensão de dinheiro em espécie, joias, veículos e outros bens, além de medidas cautelares que bloqueiam até R$ 2 milhões em ativos dos investigados. O material recolhido será analisado pela PF e pela CGU, que continuam as investigações para esclarecer os fatos e individualizar responsabilidades.', 'https://d1x4bjge7r9nas.cloudfront.net/wp-content/uploads/2025/07/17075740/Hugo-Motta-Alcmin-e-Alcolumbre-3.png', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-13 12:32:09.257+00', 0, false, 'Prefeito de Gongogi é alvo de operação da PF contra fraudes', 'A Polícia Federal (PF) e a Controladoria‑Geral da União (CGU) iniciaram nesta quinta‑feira (13) a Operação Severus, segunda fase da Operação Pacto Infame, para aprofundar investigações sobre...'),
  ('56c85f43-aa3e-478a-9605-1f5187c86c4f', 'Empresa de corretagem de João Roma recebe R$ 19,7 milhões do Banco Master', 'empresa-de-corretagem-de-joao-roma-recebe-r-19-7-milhoes-do-banco-master', 'A AB Serviços de Corretagem Financeira, sociedade na qual figuram o candidato ao Senado João Roma (PL) e o empresário Alfredo Pacheco Pereira Neto, firmou contratos com o Banco Master em 202...', 'A AB Serviços de Corretagem Financeira, sociedade na qual figuram o candidato ao Senado João Roma (PL) e o empresário Alfredo Pacheco Pereira Neto, firmou contratos com o Banco Master em 2021 que totalizam aproximadamente R$ 19,7 milhões. O período dos pagamentos coincidiu com a atuação de Roma como ministro da Cidadania no governo de Jair Bolsonaro. Apesar de ser sócio da corretora, Roma não informou a participação na sua declaração de bens à Justiça Eleitoral, registrando apenas a sociedade com Pacheco na produtora de bananas Prata da Chapada, com 50 % de participação e valor declarado de R$ 100 mil.

O quadro societário da AB Serviços também inclui o advogado Bruno Martinez Carneiro Ribeiro Neves, então superintendente do Ibama na Bahia, que confirmou ter sido sócio, mas se afastou em 2023. A empresa alegou que os trabalhos para o grupo ligado ao Banco Master tiveram comprovação técnica e envolveram consultoria, assessoria e relacionamento comercial, ressaltando que os contratos foram firmados no âmbito privado, com tributos devidamente recolhidos e sem uso de recursos públicos. Pacheco, sócio de Roma na empresa de bananas, afirmou que não há vínculo entre a AB Serviços, o Banco Master e a produção agropecuária, e que Roma não participou da aproximação entre as partes. Roma, por sua vez, confirmou a sociedade na produção de bananas e destacou que está há quatro anos sem cargo público, dedicando-se a atividades privadas e partidárias.', 'https://d1x4bjge7r9nas.cloudfront.net/wp-content/uploads/2025/03/17173333/joao-roma.jpg', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-13 12:32:32.528+00', 5, false, 'Empresa de corretagem de João Roma recebe R$ 19,7 milhões do Banco Master', 'A AB Serviços de Corretagem Financeira, sociedade na qual figuram o candidato ao Senado João Roma (PL) e o empresário Alfredo Pacheco Pereira Neto, firmou contratos com o Banco Master em 202...'),
  ('6b7666ea-d18d-4cfc-bb9a-8e896cd999e8', 'Coronel João Sá propõe mudança para o Território de Identidade Itaparica', 'coronel-joao-sa-propoe-mudanca-para-o-territorio-de-identidade-itaparica', 'Coronel João Sá pode mudar sua divisão territorial administrativa, saindo do Território Semiárido Nordeste II para o Território Itaparica. A proposta, que será discutida em audiência pública, busca alinhar o município a um planejamento regional focado no Vale do São Francisco e na região de Paulo Afonso.', 'Uma proposta, formalizada pelo Edital de n° 001/2026, visa alterar a divisão territorial administrativa de Coronel João Sá. Atualmente pertencente ao Território Semiárido Nordeste II, o município passaria a integrar o Território de Identidade Itaparica. A mudança é estritamente administrativa, usada pelo Estado da Bahia para organizar políticas públicas, planejamento e participação social, não implicando em alteração geográfica dos limites do município ou sua saída do estado. A discussão está agendada para o dia 19 de agosto de 2026, às 09 horas, no Auditório da Câmara de Vereadores.

Com a alteração, Coronel João Sá seria planejado e articulado em conjunto com os seis municípios do Território Itaparica (Abaré, Chorrochó, Glória, Macururé, Paulo Afonso e Rodelas), em vez dos 18 municípios do Semiárido Nordeste II. A integração ao Itaparica aproximaria o município do Vale do São Francisco e da região de Paulo Afonso/Glória, cujo principal elemento geográfico é o Rio São Francisco, contrastando com a orientação do Semiárido Nordeste II, mais ligado ao Nordeste Baiano, com cidades como Euclides da Cunha e Ribeira do Pombal.', 'https://imagemlink.cleissoncardoso.com/uploads/e1a7e3ed-40cd-4698-b241-551d2c4fa0e3.png', '3f094372-90cd-4037-b884-144090d021ff', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-13 14:36:37.084847+00', 1027, true, 'Coronel João Sá pode mudar de território administrativo para o Itaparica', 'Proposta discute a saída de Coronel João Sá do Semiárido Nordeste II para o Território Itaparica. A mudança é administrativa para otimizar políticas públicas ligadas ao Vale do São Francisco.'),
  ('989e109f-741a-4c82-aff3-e4333e475edd', 'Fátima sedia reunião de prefeitos para alinhar campanhas de Lula e Jerônimo', 'fatima-sedia-reuniao-de-prefeitos-para-alinhar-campanhas-de-lula-e-jeronimo', 'Prefeitos e representantes do Semiárido Nordeste 2 se reuniram em Fátima, a convite do prefeito Binho de Alfredo, para alinhar estratégias políticas. O encontro focou no planejamento das campanhas de Lula, Jerônimo Rodrigues e candidatos ao Senado, visando fortalecer a articulação regional para as eleições.', 'O prefeito de Fátima, Binho de Alfredo (PT), promoveu nesta quarta-feira (12), na cidade do interior da Bahia, uma reunião de alinhamento com gestores e representantes de municípios que compõem o território do Semiárido Nordeste 2. O encontro reuniu prefeitos como Patrícia Almeida (Banzaê), Vinícius do São José (Cícero Dantas), Juninho Professor (Adustina), Tista de Deda (Jeremoabo), Alan de Cassinho (Nova Soure), Teti Britto (Ribeira do Amparo), Essioneide de Rani (Antas), Talisson Santa Rosa (Paripiranga), Luiz Alberto (Olindina), Bené do Planalto (Sítio do Quinto), Eriksson Silva (Ribeira do Pombal) e Mendonça (Heliópolis), além de secretários e lideranças políticas.

Durante a reunião, foram discutidas estratégias de organização política e ações conjuntas voltadas para o próximo período eleitoral, com foco no planejamento das campanhas do presidente Luiz Inácio Lula da Silva, do governador da Bahia, Jerônimo Rodrigues, e dos candidatos ao Senado Rui Costa e Jaques Wagner. Binho de Alfredo destacou que o objetivo foi fortalecer o diálogo entre os gestores e alinhar a atuação política regional. Ele avaliou a reunião como produtiva e ressaltou o ânimo dos participantes para a campanha, visando a vitória em 4 de outubro e a manutenção do projeto de Lula e Jerônimo.', 'https://mkbnqyhvaozqfpmcyoyw.supabase.co/storage/v1/object/public/imagens/noticias/1786634022448_0ge59gf.webp', 'ebffbf51-6728-401d-9f59-3a334902bdfc', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-13 14:47:35.067224+00', 1025, true, 'Prefeitos do Semiárido se reúnem em Fátima por alinhamento eleitoral', 'Prefeitos do Semiárido Nordeste 2 discutem estratégias políticas em Fátima para as campanhas de Lula, Jerônimo, Rui Costa e Jaques Wagner.'),
  ('855a969b-8a76-4f39-8996-bc213e696c1b', 'Polícia Civil recupera iPhone roubado em Paripiranga durante Operação Mobile 360°', 'policia-civil-recupera-iphone-roubado-em-paripiranga-durante-operacao-mobile-360', 'A Polícia Civil de Paripiranga recuperou um iPhone 16 Pro Max roubado em Salvador. A ação faz parte da Operação Mobile 360°, que visa combater a receptação e restituir bens. O aparelho foi localizado na tarde de quarta-feira (12) no município.', 'A Polícia Civil da Bahia, através da Delegacia Territorial de Paripiranga, recuperou na tarde desta quarta-feira (12) um aparelho celular iPhone 16 Pro Max, da marca Apple, que possuía restrição por roubo. O dispositivo foi localizado por volta das 15h, no município de Paripiranga, localizado no nordeste da Bahia. Segundo informações da Polícia Civil, o celular era oriundo de um crime de roubo registrado anteriormente na capital baiana, Salvador, e a ocorrência foi registrada no Boletim de Ocorrência nº 596200/2026.

A ação de recuperação integra a Operação Mobile 360°, uma iniciativa da Polícia Civil que tem como objetivo principal localizar e recuperar aparelhos celulares subtraídos por roubo e furto. A operação visa ainda combater o crime de receptação e possibilitar a restituição desses bens aos seus legítimos proprietários. Esta iniciativa faz parte das estratégias desenvolvidas pela Polícia Civil da Bahia para intensificar o enfrentamento aos crimes patrimoniais envolvendo telefones móveis em todo o estado, fortalecendo a segurança pública e a responsabilização de envolvidos na criminalidade.', 'https://imagemlink.cleissoncardoso.com/uploads/fbf62264-46ca-4fa2-832e-512c012c16a3.png', '677f9a5e-4050-4ad1-94a5-76c2b779098a', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-13 14:48:48.348228+00', 1018, true, 'Polícia Civil recupera iPhone roubado em Paripiranga', 'A Polícia Civil de Paripiranga recuperou um iPhone 16 Pro Max com restrição de roubo, oriundo de Salvador. A ação faz parte da Operação Mobile 360°, focada na recuperação de celulares e combate à receptação.'),
  ('f0b970a1-79a5-4bf1-9228-d7c016d08f3d', 'Equipe e-DOT do Hospital Santa Tereza realiza nova captação de córneas em Ribeira do Pombal', 'equipe-e-dot-do-hospital-santa-tereza-realiza-nova-captacao-de-corneas-em-ribeira-do-pombal', 'A Equipe Hospitalar de Doação para Transplantes (e-DOT) do Hospital Geral Santa Tereza, em Ribeira do Pombal, realizou mais uma captação de córneas em [DATA]. O procedimento amplia o número de doações do território e reforça o trabalho da unidade na rede estadual de transplantes.', 'A Equipe Hospitalar de Doação para Transplantes (e-DOT) do Hospital Geral Santa Tereza realizou, em [DATA], mais uma captação de córneas. O procedimento foi feito após autorização da família do doador, seguindo os protocolos do Sistema Nacional de Transplantes.

A e-DOT é um grupo multiprofissional responsável por identificar potenciais doadores, conduzir a entrevista familiar e executar a retirada de órgãos e tecidos, conforme a Política Nacional de Doação e Transplantes (Portaria GM/MS nº 8.041/2025). No caso das córneas, o material é encaminhado ao Banco de Olhos vinculado à Central Estadual de Transplantes da Bahia.

Segundo dados da Secretaria de Saúde do Estado (SESAB), o número de doações de córneas cresceu nos últimos anos na Bahia, mas a fila de espera por transplantes também aumentou — o que reforça a importância de cada captação realizada nas unidades do interior, como Ribeira do Pombal.

Para a população do Semiárido Nordeste II, cada procedimento como esse representa mais uma chance de devolver a visão a pacientes na fila de espera. A atuação da e-DOT local mostra que hospitais de médio porte também têm papel ativo na cadeia estadual de transplantes.', 'https://mkbnqyhvaozqfpmcyoyw.supabase.co/storage/v1/object/public/imagens/noticias/1786633036527_31ofwdn.webp', '7d34292b-4217-4571-ba21-f7aa996aa1d3', NULL, '2026-08-13 14:57:22.532+00', 902, true, 'Hospital Santa Tereza realiza nova captação de córneas', 'Equipe e-DOT do Hospital Geral Santa Tereza, em Ribeira do Pombal, realiza mais uma captação de córneas para doação e transplante.'),
  ('62f6d47c-7654-479c-8d96-e11c74b30849', 'Denúncia leva polícia até "casa de jogo de azar" e responsável é levado à delegacia em Ribeira do Pombal', 'denuncia-leva-policia-ate-casa-de-jogo-de-azar-e-responsavel-e-levado-a-delegacia-em-ribeira-do-pombal', 'Uma denúncia anônima levou a Polícia Militar até uma "casa de jogo de azar" em Ribeira do Pombal, na última segunda-feira (10). No local, foram apreendidas 17 máquinas de caça-níqueis e outros equipamentos. O responsável, identificado pelas iniciais P.J.C.F., 52 anos, foi conduzido à Delegacia de Polícia Civil.

', 'Uma denúncia anônima levou policiais militares de Ribeira do Pombal até um imóvel na Rua Júlio Guerra de Almeida, nas proximidades da Biblioteca Municipal. A ação ocorreu por volta das 12h40 da última segunda-feira (10).

No endereço, adaptado para a prática de contravenção penal, os militares encontraram um verdadeiro cassino clandestino. Foram apreendidas 17 máquinas de caça-níqueis — a maioria ligada e em funcionamento no momento da chegada da equipe.

Além das máquinas, os policiais recolheram 6 tablets, 4 máquinas de cartão e 3 impressoras, material usado na operação do local.

Um homem identificado pelas iniciais P.J.C.F., 52 anos, confirmou ser o responsável pelo estabelecimento. Ele foi conduzido, junto com todo o material apreendido, à Delegacia de Polícia Civil de Ribeira do Pombal para a adoção das medidas cabíveis. Fonte: Portal Alerta', 'https://mkbnqyhvaozqfpmcyoyw.supabase.co/storage/v1/object/public/imagens/noticias/1786633727612_38u1pot.webp', '7d34292b-4217-4571-ba21-f7aa996aa1d3', NULL, '2026-08-13 15:10:03.761+00', 897, true, 'enúncia leva PM a "casa de jogo de azar" em Ribeira do Pombal', 'Polícia apreende 17 máquinas de caça-níqueis e prende responsável por local de jogos ilegais na Rua Júlio Guerra de Almeida.'),
  ('7d6798c3-f0ce-42cb-985a-5675930eaad1', 'Prefeitura de Ribeira do Pombal reúne operadores de poços artesianos contra o El Niño', 'prefeitura-de-ribeira-do-pombal-reune-operadores-de-pocos-artesianos-contra-o', 'Prefeitura de Ribeira do Pombal reuniu mais de 80 operadores de poços artesianos para planejar ações de conservação hídrica e enfrentar os efeitos do El Niño nas áreas rurais.', 'A Prefeitura de Ribeira do Pombal, por meio da Secretaria de Meio Ambiente e Recursos Hídricos, promoveu uma reunião com mais de 80 operadores de poços artesianos das áreas rurais sob sua administração. O encontro, realizado para discutir o fenômeno climático El Niño que já se manifesta na região, teve como objetivo principal elaborar estratégias que minimizem os impactos sobre o abastecimento de água nas comunidades rurais.  

Durante a sessão, os operadores foram orientados a manter um diálogo permanente com os moradores, reforçando a necessidade de consumo consciente. A secretaria ressaltou que a compreensão dos efeitos do El Niño é essencial, pois o fenômeno tende a intensificar a escassez hídrica no semiárido. O secretário Diego enfatizou que o sucesso das ações depende da união entre poder público e população, alertando que a falta de cooperação dificultará o enfrentamento dos desafios impostos pelo El Niño.  

Foi sugerido que os proprietários verifiquem a integridade das bombas, adotem técnicas de captação sustentável e registrem o volume extraído diariamente. A secretaria também anunciou a criação de um canal de comunicação direta entre os operadores e a gestão municipal, visando o acompanhamento contínuo das condições dos poços e a rápida adoção de medidas corretivas. Novas reuniões serão agendadas periodicamente para avaliar a eficácia das ações e ajustar o plano conforme a evolução do cenário climático.', 'http://ribeiradopombal.ba.gov.br/wp-content/uploads/2026/08/WhatsApp-Image-2026-08-13-at-12.14.32.jpeg', '7d34292b-4217-4571-ba21-f7aa996aa1d3', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-13 15:23:49.050868+00', 111, true, 'Ribeira do Pombal reúne operadores de poços artesianos contra o El Niño', 'A Prefeitura de Ribeira do Pombal, via Secretaria de Meio Ambiente, reuniu mais de 80 operadores de poços artesianos para planejar ações de conservação hídrica diante do El Niño.'),
  ('af008200-83c5-42be-bba3-81e7634c2828', 'Prefeitura de Ribeira do Pombal adia prazo para uso do Emissor Nacional da NFS‑e para 1º de novembro de 2026', 'prefeitura-de-ribeira-do-pombal-adia-prazo-para-uso-do-emissor-nacional-da-nfse', 'Prefeitura de Ribeira do Pombal cria página informativa e adia para 1 de novembro de 2026 a exigência do Emissor Nacional da NFS‑e, dando mais tempo a micro e pequenas empresas para cadastro e testes.', 'A Secretaria de Administração de Ribeira do Pombal, por meio do Fisco Municipal, criou uma seção especial no portal oficial para orientar os contribuintes sobre as alterações na Nota Fiscal de Serviço eletrônica (NFS‑e). A medida foi anunciada após o Comitê Gestor do Simples Nacional decidir prorrogar a data de início da obrigatoriedade do Emissor Nacional, proporcionando mais tempo para que microempresas (ME) e empresas de pequeno porte (EPP) optantes pelo Simples Nacional se adaptem ao novo modelo.

Com a nova data estabelecida para 1º de novembro de 2026, antes prevista para 1º de setembro de 2026, os empresários do município passam a dispor de um período adicional para efetuar o cadastro na plataforma, testar o sistema e familiarizar‑se com as funcionalidades do emissor. A iniciativa busca reduzir a pressão sobre os contribuintes, minimizar riscos de erros na emissão de notas fiscais durante a fase de transição e garantir maior segurança na adequação às exigências legais.', 'http://ribeiradopombal.ba.gov.br/wp-content/uploads/2026/08/1.png', '7d34292b-4217-4571-ba21-f7aa996aa1d3', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-13 15:30:27.513801+00', 113, true, 'Ribeira do Pombal adia prazo da NFS‑e para 1º de novembro de 2026', 'Prefeitura de Ribeira do Pombal cria página de orientação e adia para 1 de novembro de 2026 a exigência do Emissor Nacional da NFS‑e para micro e pequenas empresas.'),
  ('7249f351-17c7-474e-86fd-880cf805ca4b', 'TSE confirma filiação de Bolsonaro ao Missão feita por representante', 'tse-confirma-filiacao-de-bolsonaro-ao-missao-feita-por-representante', 'O Tribunal Superior Eleitoral (TSE) analisou documentos internos e concluiu que a filiação do senador Flávio Bolsonaro ao partido Missão foi efetuada por um representante oficial do partido....', 'O Tribunal Superior Eleitoral (TSE) analisou documentos internos e concluiu que a filiação do senador Flávio Bolsonaro ao partido Missão foi efetuada por um representante oficial do partido. A verificação dos registros foi divulgada em nota do órgão, que destacou a regularidade do procedimento interno de filiação.  

Em resposta, a campanha de Flávio Bolsonaro afirmou que pretende solicitar à Polícia Federal a abertura de inquérito para apurar eventuais irregularidades relacionadas ao processo de filiação. A medida foi anunciada como forma de garantir a transparência e a lisura das informações apresentadas pelo TSE.', 'https://s2-oglobo.glbimg.com/rgclte_nHFBn7fArksTpZCZ531A=/3798x0/filters:format(jpeg)/https://i.s3.glbimg.com/v1/AUTH_da025474c0c44edd99332dddb09cabe8/internal_photos/bs/2026/O/x/domnRxRkmnLHFRJy7r0w/114998763-files-brazilian-senator-and-pre-presidential-candidate-flavio-bolsonaro-looks-on-as-he.jpg', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-13 16:34:02.916+00', 2, false, 'TSE confirma filiação de Bolsonaro ao Missão feita por representante', 'O Tribunal Superior Eleitoral (TSE) analisou documentos internos e concluiu que a filiação do senador Flávio Bolsonaro ao partido Missão foi efetuada por um representante oficial do partido....'),
  ('35fdf6b9-a624-458a-8307-6b77951efac1', 'Acidente entre carreta e ônibus escolar deixa feridos em Serrinha', 'acidente-entre-carreta-e-onibus-escolar-deixa-feridos-em-serrinha', 'Um acidente grave foi registrado no fim da manhã desta quinta-feira (13) na BR-116, no trecho conhecido como Cabeça da Vaca, em Serrinha. A colisão envolveu uma carreta e um ônibus escolar e...', 'Um acidente grave foi registrado no fim da manhã desta quinta-feira (13) na BR-116, no trecho conhecido como Cabeça da Vaca, em Serrinha. A colisão envolveu uma carreta e um ônibus escolar e, de acordo com informações preliminares, resultou em diversas pessoas feridas. O impacto da batida foi descrito como intenso, gerando uma imediata mobilização de equipes de socorro e segurança na rodovia.

O Serviço de Atendimento Móvel de Urgência (SAMU) foi prontamente acionado para prestar socorro às vítimas no local. A Polícia Rodoviária Federal (PRF) também esteve presente para controlar o tráfego na região e auxiliar nos procedimentos da ocorrência. Até o momento, não há confirmação oficial sobre o estado de saúde exato dos feridos, nem informações sobre possíveis vítimas fatais. O incidente causou grande preocupação entre os moradores e motoristas que utilizavam a rodovia.', 'https://imagemlink.cleissoncardoso.com/uploads/1db9c781-e756-42d4-89d3-2fe0cd5e1616.png', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-13 17:34:53.918+00', 0, false, 'Acidente entre carreta e ônibus escolar deixa feridos em Serrinha', 'Um acidente grave foi registrado no fim da manhã desta quinta-feira (13) na BR-116, no trecho conhecido como Cabeça da Vaca, em Serrinha. A colisão envolveu uma carreta e um ônibus escolar e...'),
  ('61dfd581-45de-4520-ba95-db3e6201452e', 'Senar forma turma de assistência técnica para produtores de leite em Ribeira do Pombal', 'senar-forma-turma-de-assistencia-tecnica-para-produtores-de-leite-em-ribeira-do-pombal', 'Segundo o presidente Lemuel de Santana, quem compareceu aprovou a proposta e deve ajudar a atrair mais interessados nos próximos dias. O programa busca 40 produtores com perfil dentro dos critérios do Senar.', '
Produtores de leite de Ribeira do Pombal participaram nesta quinta-feira (13) do encontro que marca o início da formação de uma turma do programa ATeG (Assistência Técnica e Gerencial) do Senar. A chuva impediu a presença de alguns produtores que avisaram não ter condições de se deslocar, mas o evento foi considerado um bom começo.

Segundo o presidente Lemuel de Santana, quem compareceu aprovou a proposta e deve ajudar a atrair mais interessados nos próximos dias. O programa busca 40 produtores com perfil dentro dos critérios do Senar.

Para participar, é necessário produzir acima de 30 litros de leite por dia, ter no mínimo 7 animais no rebanho e ser maior de idade. Do total de inscritos, 30 produtores serão selecionados como efetivos e 10 ficarão como reserva.

A expectativa é que os produtores contemplados pelo ATeG sirvam de referência na região, multiplicando boas práticas de gestão entre outros pecuaristas de Ribeira do Pombal.', 'https://mkbnqyhvaozqfpmcyoyw.supabase.co/storage/v1/object/public/imagens/noticias/1786642857312_znjcrhz.webp', '7d34292b-4217-4571-ba21-f7aa996aa1d3', NULL, '2026-08-13 17:41:55.73+00', 548, true, '', ''),
  ('77460b6e-6860-463f-b74f-2f16f5331280', 'Rio Grande (RS): Pensionista é Condenada por Má-Fé ao Tentar Anular Empréstimos', 'rio-grande-rs-pensionista-e-condenada-por-ma-fe-ao-tentar-anular-emprestimos', 'Uma pensionista de Rio Grande (RS) foi condenada por litigância de má-fé pela 2ª Vara Federal, após contestar a validade de nove empréstimos consignados em seu nome. A segurada alegava desco...', 'Uma pensionista de Rio Grande (RS) foi condenada por litigância de má-fé pela 2ª Vara Federal, após contestar a validade de nove empréstimos consignados em seu nome. A segurada alegava desconhecer as operações e solicitava a anulação dos contratos, a devolução dos valores descontados e uma indenização por danos morais.

Durante o trâmite processual, as instituições financeiras e o INSS apresentaram um vasto conjunto de evidências, incluindo contratos devidamente assinados, registros fotográficos e vídeos das contratações, dados de geolocalização, comprovantes de transferências bancárias e documentos relacionados a portabilidades e refinanciamentos. A Justiça considerou que essas provas confirmaram a regularidade de todas as operações e demonstraram que os créditos foram efetivamente recebidos pela pensionista. O juiz entendeu que houve uma alteração intencional da verdade dos fatos, visando evitar o pagamento das dívidas e obter vantagem indevida. Como consequência, a pensionista foi condenada a pagar uma multa de 10% sobre o valor da causa, mas a decisão ainda está sujeita a recurso.', 'https://imagemlink.cleissoncardoso.com/uploads/b5817c9c-8f3e-4972-9b65-d6ff3525ffce.png', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-13 19:38:14.206+00', 1, false, 'Rio Grande (RS): Pensionista é Condenada por Má-Fé ao Tentar Anular Empréstimos', 'Uma pensionista de Rio Grande (RS) foi condenada por litigância de má-fé pela 2ª Vara Federal, após contestar a validade de nove empréstimos consignados em seu nome. A segurada alegava desco...'),
  ('36103b38-ecc1-4f32-9f1a-e42070192668', 'TSE nega ataque hacker e afirma que filiação de Flávio Bolsonaro ao Missão ocorreu por uso indevido de credenciais', 'tse-nega-ataque-hacker-e-afirma-que-filiacao-de-flavio-bolsonaro-ao-missao-ocorr', 'O Tribunal Superior Eleitoral (TSE) declarou, nesta quinta‑feira (13/08), que a filiação do senador Flávio Bolsonaro (PL) ao partido Missão não foi consequência de um ataque hacker ao sistem...', 'O Tribunal Superior Eleitoral (TSE) declarou, nesta quinta‑feira (13/08), que a filiação do senador Flávio Bolsonaro (PL) ao partido Missão não foi consequência de um ataque hacker ao sistema de filiação partidária. Segundo a Corte, a alteração foi realizada por meio da ferramenta de filiação por alguém que possuía credenciais da própria legenda e as utilizou de forma indevida.

Em nota, o presidente do TSE, ministro Kassio Nunes Marques, encaminhou representação à Procuradoria‑Geral Eleitoral (PGE) para que sejam adotadas as providências cabíveis. Também foi aberta uma investigação policial para apurar o caso e identificar quem usou as credenciais. Após o episódio, o Partido Liberal (PL) protocolou pedido de desfiliação de Flávio Bolsonaro do Missão, que ainda está em análise.', 'https://informebaiano.com.br/wp-content/uploads/Flavio.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-13 23:16:41.001+00', 2, false, 'TSE nega ataque hacker e afirma que filiação de Flávio Bolsonaro ao Missão ocorreu por uso indevido de credenciais', 'O Tribunal Superior Eleitoral (TSE) declarou, nesta quinta‑feira (13/08), que a filiação do senador Flávio Bolsonaro (PL) ao partido Missão não foi consequência de um ataque hacker ao sistem...'),
  ('c225e4ff-eaa1-4ccc-9534-bdd5687ac8fc', 'Homem de 21 anos é preso em Santa Brígida por suspeita de matar o próprio pai', 'homem-de-21-anos-e-preso-em-santa-brigida-por-suspeita-de-matar-o-proprio-pai', 'Homem de 21 anos foi preso em Santa Brígida por suspeita de matar o pai, José Carisvaldo Dantas; o irmão do suspeito permanece foragido.', 'Na manhã desta quinta‑feira (13), a Polícia Civil da Bahia deteve, na zona rural de Santa Brígida, um homem de 21 anos suspeito de participar do homicídio de seu pai. A vítima, José Carisvaldo Dantas, de 58 anos, foi atingida por disparos de arma de fogo em 5 de abril de 2025, na residência do Povoado Curituba, no mesmo município. Segundo as investigações, o suspeito e seu irmão teriam usado uma espingarda e um revólver para cometer o crime. As equipes localizaram o acusado na propriedade familiar, onde ocorreu o homicídio, e cumpriram o mandado de prisão preventiva.

O preso foi conduzido a uma unidade policial e permanece custodiado à disposição da justiça. O irmão, também apontado como autor, continua foragido, e as diligências da Delegacia Territorial de Santa Brígida seguem para sua localização. O caso segue sob investigação da polícia local.', 'https://informebaiano.com.br/wp-content/uploads/e5458ab4-6ab1-45c1-881b-0cc2ad7488b3.webp', '080bae89-6778-4435-9771-52d94fdecbce', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-13 23:20:40.646551+00', 126, true, 'Homem de 21 anos é preso em Santa Brígida por homicídio de pai', 'Polícia Civil prende, em Santa Brígida, homem de 21 anos suspeito de matar o pai, José Carisvaldo Dantas, com arma de fogo; irmão permanece foragido.'),
  ('1477efc5-aac4-4bb9-a923-41e095b11480', 'INSS alerta sobre golpes via SMS e ligações envolvendo corte de benefícios', 'inss-alerta-sobre-golpes-via-sms-e-ligacoes-envolvendo-corte-de-beneficios', 'O Instituto Nacional do Seguro Social (INSS) emitiu um alerta importante à população sobre mensagens de texto (SMS) e ligações telefônicas fraudulentas que circulam em nome da instituição. O...', 'O Instituto Nacional do Seguro Social (INSS) emitiu um alerta importante à população sobre mensagens de texto (SMS) e ligações telefônicas fraudulentas que circulam em nome da instituição. O órgão desaconselha veementemente que os segurados confiem em comunicações que mencionam corte de benefícios ou que solicitem senhas, dados pessoais ou pagamentos para regularização. O INSS esclarece que sua política oficial não inclui o envio de mensagens ou a realização de chamadas com ameaças de suspensão de benefícios ou exigências financeiras.

Para evitar ser vítima de golpes, a orientação é sempre buscar informações e serviços exclusivamente pelos canais oficiais do Instituto. Em caso de qualquer dúvida sobre a autenticidade de uma comunicação ou a situação de seu benefício, os segurados devem acessar o site ou o aplicativo "Meu INSS". Além disso, a Central de Atendimento 135 está disponível para prestar esclarecimentos e auxílio de forma segura e confiável, garantindo que os usuários não caiam em fraudes.', 'https://imagemlink.cleissoncardoso.com/uploads/eaa31335-795d-4dff-9712-0331acce48e4.png', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-14 01:59:44.233+00', 2, false, 'INSS alerta sobre golpes via SMS e ligações envolvendo corte de benefícios', 'O Instituto Nacional do Seguro Social (INSS) emitiu um alerta importante à população sobre mensagens de texto (SMS) e ligações telefônicas fraudulentas que circulam em nome da instituição. O...'),
  ('a78c032f-e141-4c09-b974-3f8dd7559518', 'Deputado Nilo acusa presidente do TRE-BA de perseguição e anuncia divulgação de dossiê', 'deputado-nilo-acusa-presidente-do-tre-ba-de-perseguicao-e-anuncia-divulgacao-de', 'O deputado federal Marcelo Nilo (Republicanos) afirmou que possui um dossiê elaborado a partir de informações de cinco fontes distintas, o qual, segundo ele, pode comprometer o presidente do...', 'O deputado federal Marcelo Nilo (Republicanos) afirmou que possui um dossiê elaborado a partir de informações de cinco fontes distintas, o qual, segundo ele, pode comprometer o presidente do Tribunal Regional Eleitoral da Bahia (TRE-BA), Maurício Kertzman. Nilo declarou que recebeu o material, mas não o encaminhou ao Ministério Público, acrescentando que o presidente do TRE teria iniciado suposta perseguição política contra ele.

Em entrevista ao bahia.ba, o parlamentar relatou que, durante o julgamento de um processo no TRE, Kertzman teria votado consistentemente contra suas posições, ainda que o empate normalmente favoreça a vítima. Nilo disse que entrou em contato com o presidente, enviou áudio e suspeita que a conversa tenha sido gravada e levada ao órgão eleitoral. O deputado planeja ler o conteúdo do dossiê na tribuna da Câmara dos Deputados na terça‑feira, 18, e citar a participação de Kertzman na operação Faroeste, além de questionar sua permanência à frente do TRE‑BA devido a supostos vínculos políticos.', 'https://d1x4bjge7r9nas.cloudfront.net/wp-content/uploads/2026/02/09214839/marcelo-nilo-3.png', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-14 12:45:22.497+00', 0, false, 'Deputado Nilo acusa presidente do TRE-BA de perseguição e anuncia divulgação de dossiê', 'O deputado federal Marcelo Nilo (Republicanos) afirmou que possui um dossiê elaborado a partir de informações de cinco fontes distintas, o qual, segundo ele, pode comprometer o presidente do...'),
  ('2810273f-c982-4dbd-9f3c-360b17e6e072', 'Datafolha: Ciro Gomes 52% e Elmano de Freitas 33% no Ceará', 'datafolha-ciro-gomes-52-e-elmano-de-freitas-33-no-ceara', 'O instituto Datafolha divulgou, nesta quinta‑feira (13), uma pesquisa encomendada pelo jornal O Povo que entrevistou 1 022 eleitores entre 10 e 12 de agosto de 2026. Na modalidade estimulada...', 'O instituto Datafolha divulgou, nesta quinta‑feira (13), uma pesquisa encomendada pelo jornal O Povo que entrevistou 1 022 eleitores entre 10 e 12 de agosto de 2026. Na modalidade estimulada, Ciro Gomes (PSDB) lidera com 52% das intenções de voto para o primeiro turno do governo do Ceará, seguido por Elmano de Freitas (PT) com 33%. Pedro Brito (Novo), Delegado Huggo Leonardo (Missão) e Danilo Soares (Democrata) ficaram com 1% cada, enquanto Vera Lúcia (Novo) não foi testada por ter substituído Brito após a desistência deste. Brancos/nulos somam 7% e 4% dos entrevistados ainda não sabem em quem votar.  

Na pesquisa espontânea, Ciro mantém a vantagem, obtendo 28% das respostas, contra 20% de Elmano, 2% para o senador Camilo Santana (PT) e 3% para outras opções; brancos/nulos chegam a 5% e 43% dos eleitores permanecem indecisos. A simulação de segundo turno entre Ciro e Elmano projeta 55% a favor de Ciro e 37% a favor de Elmano, com 5% de brancos/nulos e 3% de indecisos. A margem de erro da pesquisa é de três pontos percentuais, com nível de confiança de 95%, e está registrada no TSE sob os números CE‑04292/2026 e BR‑00994/2026.', 'https://diariodonordeste.verdesmares.com.br/image/contentid/policy:1.3782929:1786320950/Base%20-%20Debate%20(1).webp?f=16x9&h=720&w=1280&$p$f$h$w=30e775b', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-14 13:17:04.188+00', 2, false, 'Datafolha: Ciro Gomes 52% e Elmano de Freitas 33% no Ceará', 'O instituto Datafolha divulgou, nesta quinta‑feira (13), uma pesquisa encomendada pelo jornal O Povo que entrevistou 1 022 eleitores entre 10 e 12 de agosto de 2026. Na modalidade estimulada...'),
  ('20b1b52c-7b43-4d15-9ffc-1b86c336bd5e', 'WhatsApp testa alerta de IA para detectar golpes', 'whatsapp-testa-alerta-de-ia-para-detectar-golpes', 'O WhatsApp iniciou testes de um novo recurso de segurança que usa inteligência artificial para analisar mensagens suspeitas diretamente no dispositivo do usuário. Quando o algoritmo identifi...', 'O WhatsApp iniciou testes de um novo recurso de segurança que usa inteligência artificial para analisar mensagens suspeitas diretamente no dispositivo do usuário. Quando o algoritmo identifica indícios de fraude, um aviso aparece na própria conversa, invisível para a pessoa do outro lado. O alerta permite que o usuário bloqueie o contato, denuncie a conversa ou continue trocando mensagens normalmente.

A ferramenta também oferece a opção de marcar a conversa como segura, fazendo o aviso desaparecer permanentemente naquele chat. Caso o usuário considere que a IA interpretou a mensagem de forma equivocada, pode classificar a conversa como confiável e, se desejar, enviar as últimas cinco mensagens ao WhatsApp para melhorar a precisão do modelo. O processamento permanece local, sem envio automático de conteúdo. O recurso é opcional e pode ser desativado. Atualmente, o teste está em fase beta limitada, antes de uma possível expansão para todos os usuários.', 'https://media-manager.noticiasaominuto.com.br/960/naom_6954dc7c0f8ce.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-14 15:04:26.139+00', 2, false, 'WhatsApp testa alerta de IA para detectar golpes', 'O WhatsApp iniciou testes de um novo recurso de segurança que usa inteligência artificial para analisar mensagens suspeitas diretamente no dispositivo do usuário. Quando o algoritmo identifi...'),
  ('5832f218-08cf-4f0c-8c85-d9e6ace40bee', 'Ipac propõe declarar as Matrizes Tradicionais do Forró como Patrimônio Imaterial da Bahia', 'ipac-propoe-declarar-as-matrizes-tradicionais-do-forro-como-patrimonio-imaterial', 'Ipac iniciou um processo formal para que as Matrizes Tradicionais do Forró sejam reconhecidas como Patrimônio Cultural Imaterial da Bahia. A iniciativa busca o reconhecimento oficial da impo...', 'Ipac iniciou um processo formal para que as Matrizes Tradicionais do Forró sejam reconhecidas como Patrimônio Cultural Imaterial da Bahia. A iniciativa busca o reconhecimento oficial da importância histórica do forró na região.

Conforme informado por Euclidesdiario, o objetivo é preservar a identidade local e garantir a transmissão das tradições do forró às próximas gerações, reforçando o patrimônio cultural do estado.', 'https://euclidesdiario.com/wp-content/uploads/2026/08/forro-pode-se-tornar-patrimonio-cultural-imaterial-da-ba-1786714573136.jpg', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-14 15:06:26.594+00', 7, false, 'Ipac propõe declarar as Matrizes Tradicionais do Forró como Patrimônio Imaterial da Bahia', 'Ipac iniciou um processo formal para que as Matrizes Tradicionais do Forró sejam reconhecidas como Patrimônio Cultural Imaterial da Bahia. A iniciativa busca o reconhecimento oficial da impo...'),
  ('2d9a27f6-7dec-4ef0-83ef-41d2e33961da', 'Briga em via pública com uso de facão é registrada em Cícero Dantas', 'briga-em-via-publica-com-uso-de-facao-e-registrada-em-cicero-dantas', 'Um vídeo registrou uma briga em via pública na Avenida ACM, em Cícero Dantas, envolvendo um homem e uma mulher, com a presença de um facão. A identidade dos envolvidos e as circunstâncias não foram confirmadas oficialmente, e não há registro policial até o momento.', 'Um vídeo que circula em grupos de mensagens registrou uma confusão na Avenida Antônio Carlos Magalhães (ACM), em Cícero Dantas, Bahia. O episódio ocorreu nas proximidades do Colégio Estadual Professor Luiz Navarro de Brito, localizado no número 1478 da mesma avenida, no Centro do município. As imagens mostram uma agressão direcionada a uma mulher, seguida pela intervenção de outro homem. A gravação também indica o uso de um facão durante a altercação, que aconteceu em meio à rua e atraiu a atenção de moradores locais.

Até o momento, o portal não confirmou a identidade dos envolvidos nem as circunstâncias exatas que precederam o incidente. Não há, igualmente, informações oficiais sobre um eventual registro policial da ocorrência ou a abertura de uma investigação. Detalhes compartilhados por moradores em redes sociais, que fazem referência a um homem conhecido na cidade por um apelido, também não foram verificados oficialmente e, portanto, não são tratados como fatos. O episódio ressalta a preocupação da população com atos de violência em espaços públicos e reforça a necessidade de apuração pelas autoridades competentes. O espaço permanece aberto para manifestação dos envolvidos e esclarecimentos dos órgãos de segurança pública.', 'https://imagemlink.cleissoncardoso.com/uploads/a5479146-acfb-4b3f-b7a4-3462bfb6ae42.png', '1bff82e6-6033-4d75-8d04-e26d976c0a05', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-14 15:57:53.864804+00', 1048, true, 'Cícero Dantas: Briga com facão na Avenida ACM', 'Um vídeo mostra briga na Avenida ACM, em Cícero Dantas, com uso de facão. Envolvimento de homem e mulher em via pública sem confirmação oficial de identidades ou registro policial.'),
  ('b42c4513-f1fd-4d33-93c6-9ebadfb7dccd', 'Advogado suspeito de matar colega é preso em operação em Jeremoabo e Paulo Afonso', 'advogado-suspeito-de-matar-colega-e-preso-em-operacao-em-jeremoabo-e-paulo', 'Um advogado de 53 anos foi preso em operação em Jeremoabo e Paulo Afonso, suspeito de matar um colega de profissão. A Polícia Civil investiga a motivação do crime, que teria ligação com uma disputa de terras.', 'Um advogado de 53 anos foi preso nesta sexta-feira (14), apontado como principal suspeito do assassinato de seu colega de profissão, Diego Fraga de Castro, de 41 anos. A prisão ocorreu durante a Operação Emboscada, que abrangeu as cidades de Jeremoabo e Paulo Afonso, na Bahia.

Durante a operação, a Polícia Civil cumpriu cinco mandados de busca e apreensão. Nas propriedades ligadas ao investigado, foram encontradas duas armas de fogo e um caminhão com placa falsa e registro de roubo. Além do principal suspeito, outros dois homens foram detidos por posse irregular de arma. Diego Fraga de Castro foi morto a tiros dentro de seu carro em 4 de agosto, na zona rural de Jeremoabo. A polícia continua a investigar a participação dos suspeitos e a motivação do crime, que estaria ligada a uma disputa de terras.', 'https://imagemlink.cleissoncardoso.com/uploads/77efb772-e48b-49e7-b8a9-e6436733d33d.png', '902d44ce-469a-438d-82c4-b6e4a8357a30', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-14 16:24:57.577209+00', 1031, true, 'Advogado preso em Jeremoabo por suspeita de matar colega', 'Um advogado foi preso em Jeremoabo e Paulo Afonso durante a Operação Emboscada, sob suspeita de assassinar um colega de profissão. A polícia investiga disputa de terras como possível motivação.'),
  ('fff35b49-70e8-46c4-8b84-fc3182887127', 'Decreto de Lula abre mercado livre de energia para consumidores de baixa tensão', 'decreto-de-lula-abre-mercado-livre-de-energia-para-consumidores-de-baixa-tensao', 'O presidente Luiz Inácio Lula da Silva assinou, em cerimônia no Palácio do Planalto nesta quarta‑feira, 12, um decreto que regulamenta a abertura do mercado livre de energia elétrica para co...', 'O presidente Luiz Inácio Lula da Silva assinou, em cerimônia no Palácio do Planalto nesta quarta‑feira, 12, um decreto que regulamenta a abertura do mercado livre de energia elétrica para consumidores de baixa tensão. A medida permite que pequenos estabelecimentos comerciais e indústrias escolham a fornecedora de energia a partir de novembro de 2027, enquanto os consumidores residenciais poderão exercer esse direito a partir de 2028.  

Na prática, a iniciativa busca estimular a livre concorrência no setor elétrico, que até então obrigava esses consumidores a adquirir energia da empresa vencedora do mercado regulado. O ministro de Minas e Energia, Alexandre Silveira, comparou o futuro do mercado de energia ao da telefonia, destacando a possibilidade de troca de fornecedor em busca de condições mais vantajosas e afirmando que a medida pode reduzir a conta de luz em até 20 %. O decreto define as regras para migração ao Ambiente de Contratação Livre (ACL) e estabelece o papel do Supridor de Última Instância (SUI), que assumirá o atendimento caso o fornecedor contratado deixe de operar. Essa responsabilidade permanecerá com as distribuidoras até dezembro de 2030, podendo ser transferida a outros participantes após definição de critérios pela Aneel, que também criará normas de transparência e comparação de propostas.', 'https://veja.abril.com.br/wp-content/uploads/2018/07/istock-836376426.jpg?quality=70&strip=info&resize=1080,565&crop=1', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-14 16:42:26.48+00', 4, false, 'Decreto de Lula abre mercado livre de energia para consumidores de baixa tensão', 'O presidente Luiz Inácio Lula da Silva assinou, em cerimônia no Palácio do Planalto nesta quarta‑feira, 12, um decreto que regulamenta a abertura do mercado livre de energia elétrica para co...'),
  ('b4ce2aa1-c2c2-4d09-a36c-44ad3081963e', ' Fábrica de cubas mostra potencial industrial em Ribeira do Pombal', 'fabrica-de-cubas-mostra-potencial-industrial-em-ribeira-do-pombal', 'O prefeito Eriksson Silva visitou nesta sexta-feira (14) a fábrica de cubas de louça dos empresários Abeneg Santana e Eduarda Matos, às margens da BR-110, em Ribeira do Pombal. O empreendimento já gera 20 empregos diretos e chama atenção por atuar em um setor praticamente inexistente no município, que tem parque industrial pequeno e concentrado em poucos negócios de pequeno porte.', '
O prefeito Eriksson Silva visitou, na tarde desta sexta-feira (14), a fábrica de cubas de louça comandada pelos empresários Abeneg Santana e Eduarda Matos. O empreendimento está instalado às margens da BR-110, próximo ao bairro João Almeida, e já emprega 20 pessoas diretamente.

A iniciativa se destaca porque Ribeira do Pombal tem hoje pouquíssimas indústrias instaladas — a base econômica do município ainda é fortemente concentrada em comércio e serviços, com a indústria representando historicamente uma fração pequena da geração formal de emprego na região.

Dados do Sebrae, com base na RAIS, mostram que as micro e pequenas empresas (MPEs) respondem por 50,4% dos empregos formais no Brasil — quase 20 milhões de vagas. Um estudo da Universidade Federal do Ceará (UFC), que analisou o impacto de empresas de diferentes portes sobre o PIB per capita dos municípios brasileiros, identificou que a mão de obra alocada em micro e pequenas empresas gera efeitos consideravelmente maiores sobre a economia local do que a mesma mão de obra em empresas médias ou grandes.

Pesquisadores do Ipea que estudam a distribuição territorial da indústria no país também apontam que a desconcentração produtiva — várias empresas pequenas espalhadas pelo território, em vez de poucos grandes polos — tende a reduzir desigualdades regionais e tornar a economia local menos vulnerável a crises pontuais. Ou seja, a tese de que "é melhor várias pequenas do que uma gigante" tem respaldo acadêmico, mas os especialistas fazem uma ressalva importante: pequenas empresas isoladas crescem menos do que quando organizadas em rede, com apoio institucional, crédito e políticas públicas de fomento — como já recomenda o próprio Sebrae em guias voltados a gestores municipais.

Para Ribeira do Pombal, isso significa que a fábrica de cubas pode ser um ponto de partida, não um fim em si mesma. O desafio, segundo essa literatura, é transformar iniciativas isoladas como essa em uma política municipal contínua de atração e apoio a pequenos negócios industriais, o que ainda não está claramente estruturado na cidade.', 'https://mkbnqyhvaozqfpmcyoyw.supabase.co/storage/v1/object/public/imagens/noticias/1786746727520_6lxlrs0.webp', '7d34292b-4217-4571-ba21-f7aa996aa1d3', NULL, '2026-08-14 22:32:19.533+00', 2416, true, 'Fábrica de cubas mostra potencial industrial em Ribeira do Pombal', 'Prefeito visita fábrica que já gera 20 empregos. Dados do Sebrae e estudos acadêmicos reforçam papel de pequenas indústrias no desenvolvimento local.'),
  ('075af546-6607-4935-8c2e-d39ab9c901da', 'Joinville: mulher de 38 anos finge ser adolescente de 12 e será julgada por estelionato', 'joinville-mulher-de-38-anos-finge-ser-adolescente-de-12-e-sera-julgada-por-estel', 'Amanda Maria Souza de Oliveira, de 38 anos, foi presa em 2 de junho em Joinville, Santa Catarina, após enganar uma família e viver por 14 meses como filha adotiva, fingindo ter 12 anos. A fr...', 'Amanda Maria Souza de Oliveira, de 38 anos, foi presa em 2 de junho em Joinville, Santa Catarina, após enganar uma família e viver por 14 meses como filha adotiva, fingindo ter 12 anos. A fraude incluiu a prática de estelionato e uso de falsa identidade, com a ré admitindo ter repetido o golpe em outras cidades, como Curitiba (PR), Nova Iguaçu (RJ) e em estados como Minas Gerais, Goiás e Ceará. A polícia civil encaminhou o inquérito ao Ministério Público de Santa Catarina, que apresentou denúncia formal pelos crimes citados. O Poder Judiciário aceitou a denúncia em 9 de junho, transformando o caso em processo criminal.  

A defesa, representada pelo advogado Lúcio Sousa, apresentou sua peça escrita e recebeu réplica da acusação, culminando na marcação da audiência de instrução e julgamento para o dia 19 de junho, às 18h, na comarca de Joinville. Na sessão, serão ouvidas a acusação, a defesa e a própria ré. Após os depoimentos, haverá alegações finais antes da sentença, que não será proferida no mesmo dia. Amanda foi submetida a exames de sanidade mental em 26 de junho; os laudos, divergentes entre o exame oficial e o pericial da defesa, permanecem sob sigilo judicial.', 'https://midias.correio24horas.com.br/2026/06/05/mulher-de-37-anos-finge-ser-adolescente-de-12-e-engana-familia-por-mais-de-um-ano-3295858-article.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-15 15:05:18.218+00', 2, false, 'Joinville: mulher de 38 anos finge ser adolescente de 12 e será julgada por estelionato', 'Amanda Maria Souza de Oliveira, de 38 anos, foi presa em 2 de junho em Joinville, Santa Catarina, após enganar uma família e viver por 14 meses como filha adotiva, fingindo ter 12 anos. A fr...'),
  ('d430a546-acd3-4915-aff9-7b87ed606a8f', 'Tiago Santos Souza morre em Cícero Dantas após ser ferido em confusão', 'tiago-santos-souza-morre-em-cicero-dantas-apos-ser-ferido-em-confusao', 'Tiago Santos Souza morreu em Cícero Dantas após ser atingido por garrafa em confusão. Familiares relatam que ele interveio em uma briga. A Polícia Civil investiga o caso para identificar o responsável e as circunstâncias do incidente.', 'Tiago Santos Souza, conhecido como “Baixinho”, faleceu na madrugada deste domingo (16) em Cícero Dantas, no nordeste da Bahia, após ser ferido durante uma confusão. O incidente ocorreu na Avenida ACM, e o corpo da vítima foi encontrado nas proximidades de uma vidraçaria, em um trecho que registrava movimentação devido aos preparativos para a tradicional Alvorada do município. De acordo com relatos preliminares de familiares presentes no local, Tiago teria tentado intervir em uma briga quando foi atingido por uma garrafa de vidro na região do pescoço. A lesão resultou em intenso sangramento, e ele não resistiu aos ferimentos. As circunstâncias exatas que levaram ao ferimento fatal ainda aguardam confirmação oficial por meio da investigação policial e dos exames periciais a serem realizados.

A Polícia Militar foi acionada e prontamente isolou a área para preservar possíveis vestígios do ocorrido. Posteriormente, uma equipe do Departamento de Polícia Técnica (DPT) compareceu ao endereço para realizar a perícia necessária e o levantamento cadavérico. Após a conclusão dos procedimentos iniciais, o corpo de Tiago Santos Souza foi encaminhado ao Instituto Médico Legal (IML) de Ribeira do Pombal. Natural do povoado Pau Santo, na zona rural de Cícero Dantas, e parente do vereador Genilson de Caxias, a morte de Tiago causou grande repercussão e comoção entre os moradores da cidade. A Polícia Civil será responsável por apurar a sequência dos acontecimentos, identificar o responsável pela agressão e esclarecer a motivação da confusão. Até o momento, não há informações oficiais sobre a prisão de suspeitos envolvidos no caso.', 'https://imagemlink.cleissoncardoso.com/uploads/d69f59c5-b950-4556-866d-6be2c88095fd.png', '1bff82e6-6033-4d75-8d04-e26d976c0a05', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-16 15:20:48.923753+00', 1041, true, 'Tiago Santos Souza morre em Cícero Dantas após ser ferido em confusão', 'Tiago Santos Souza, conhecido como “Baixinho”, faleceu em Cícero Dantas (BA) após ser atingido por uma garrafa durante uma briga. A Polícia Civil investiga o caso.'),
  ('26353249-1dd0-4063-92d0-259d19859d4d', 'Pix muda em 1º de setembro: Banco Central cria nova regra dos 80 dias e brasileiros precisam ficar atentos', 'pix-muda-em-1-de-setembro-banco-central-cria-nova-regra-dos-80-dias-e-brasileiro', 'A partir de 1º de setembro, o Banco Central do Brasil implementará novas regras de segurança para o Pix, o sistema de pagamentos instantâneos. A medida visa aprimorar a proteção dos usuários...', 'A partir de 1º de setembro, o Banco Central do Brasil implementará novas regras de segurança para o Pix, o sistema de pagamentos instantâneos. A medida visa aprimorar a proteção dos usuários e reduzir fraudes.

A mudança principal consiste na criação da regra dos 80 dias, que estabelece procedimentos de identificação e recuperação de valores em transações suspeitas. Os usuários são orientados a ficar atentos às atualizações e adotar as boas práticas recomendadas.', 'https://diariodocomercio.com.br/mix/wp-content/uploads/2025/07/image-167.png', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-16 16:41:44.154+00', 2, false, 'Pix muda em 1º de setembro: Banco Central cria nova regra dos 80 dias e brasileiros precisam ficar atentos', 'A partir de 1º de setembro, o Banco Central do Brasil implementará novas regras de segurança para o Pix, o sistema de pagamentos instantâneos. A medida visa aprimorar a proteção dos usuários...'),
  ('f4ae5f8c-c0b1-441c-8fd1-b781b2c1f245', 'STF elimina idade mínima e permite aposentadoria antes dos 60 anos', 'stf-elimina-idade-minima-e-permite-aposentadoria-antes-dos-60-anos', 'O Supremo Tribunal Federal (STF) proferiu, em 3 de junho de 2026, uma decisão que altera o regime da aposentadoria especial no Brasil. A medida remove a exigência de idade mínima, que antes ...', 'O Supremo Tribunal Federal (STF) proferiu, em 3 de junho de 2026, uma decisão que altera o regime da aposentadoria especial no Brasil. A medida remove a exigência de idade mínima, que antes limitava o acesso ao benefício.

Com a nova interpretação, os trabalhadores que cumprirem os requisitos de tempo de contribuição poderão requerer a aposentadoria pelo INSS antes de completarem 60 anos, ampliando as possibilidades de aposentadoria antecipada para diversos segmentos da força de trabalho.', 'https://diariodocomercio.com.br/mix/wp-content/uploads/2025/05/aposentados-que-trabalham-podem-ganhar-beneficio.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-16 16:42:14.765+00', 3, false, 'STF elimina idade mínima e permite aposentadoria antes dos 60 anos', 'O Supremo Tribunal Federal (STF) proferiu, em 3 de junho de 2026, uma decisão que altera o regime da aposentadoria especial no Brasil. A medida remove a exigência de idade mínima, que antes ...'),
  ('88a4ed60-e630-4981-88d9-44c5e28151f6', 'BR-110 em Cícero Dantas é bloqueada após acidente entre duas carretas', 'br-110-em-cicero-dantas-e-bloqueada-apos-acidente-entre-duas-carretas', 'Um acidente entre duas carretas bloqueou a BR-110 em Cícero Dantas no sábado (15). A colisão, que teria ocorrido ao desviar de um buraco, provocou derramamento de óleo e a paralisação do tráfego. Bombeiros e PRF atuaram no local; não houve mortes.', 'Um acidente envolvendo duas carretas foi registrado no sábado (15) na BR-110, na altura do Alto da Bela Vista, em Cícero Dantas. Segundo informações colhidas no local, a colisão teria ocorrido durante uma tentativa de um dos veículos desviar de um buraco existente na pista. Com o impacto, houve derramamento de óleo sobre a rodovia, o que aumentou significativamente o risco para outros motoristas e provocou a paralisação do tráfego nos dois sentidos da via.

O Corpo de Bombeiros foi acionado e esteve no local, realizando uma ação emergencial. Para reduzir o risco de novos acidentes, os bombeiros utilizaram terra retirada do acostamento para cobrir o buraco e a parte da pista atingida pelo óleo. A Polícia Rodoviária Federal (PRF) também compareceu à ocorrência para auxiliar na segurança e organização do trânsito. Apesar da gravidade do impacto e dos transtornos causados no tráfego, não houve registro de vítimas fatais. O incidente reforça o alerta sobre as condições de segurança da BR-110, especialmente em trechos com buracos que representam perigo para os condutores.', 'https://imagemlink.cleissoncardoso.com/uploads/812245f1-f1b1-49b8-95e6-d1408621eb79.png', '1bff82e6-6033-4d75-8d04-e26d976c0a05', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-16 22:51:14.839577+00', 1037, true, 'Acidente de carretas bloqueia BR-110 em Cícero Dantas', 'Duas carretas colidiram na BR-110, em Cícero Dantas, após desviar de um buraco. O acidente causou derramamento de óleo e a paralisação do tráfego. Bombeiros e PRF atuaram no local sem registro de mortes.'),
  ('42460640-69b5-49ee-b6bc-4301da3a0716', 'Empresário Ivo Vel Kos tem prisão preventiva após agredir esposa com taco de beisebol em São Paulo', 'empresario-ivo-vel-kos-tem-prisao-preventiva-apos-agredir-esposa-com-taco-de-bei', 'O empresário Ivo Vel Kos, de 48 anos, foi preso em flagrante na madrugada de sábado (15) no bairro de Pinheiros, zona oeste de São Paulo. Segundo as autoridades, ele teria agredido a esposa,...', 'O empresário Ivo Vel Kos, de 48 anos, foi preso em flagrante na madrugada de sábado (15) no bairro de Pinheiros, zona oeste de São Paulo. Segundo as autoridades, ele teria agredido a esposa, a dentista Giulia Melo Falcão Vel Kos, de 27 anos, com socos e golpes de um taco de beisebol, além de ameaçá‑la com uma arma de choque.  

Após a captura, o homem foi apresentado à justiça para audiência de custódia. Na sessão, o juiz avaliou as circunstâncias do caso e decidiu converter a prisão em flagrante em prisão preventiva, mantendo o empresário sob custódia até que novas decisões sejam tomadas. O procedimento segue a legislação que permite a preventiva quando há risco à ordem pública ou à integridade da vítima.', 'https://www.bahianoticias.com.br/fotos/principal_noticias/320064/IMAGEM_NOTICIA_9.jpg?checksum=1786914234', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-17 00:16:41.528+00', 2, false, 'Empresário Ivo Vel Kos tem prisão preventiva após agredir esposa com taco de beisebol em São Paulo', 'O empresário Ivo Vel Kos, de 48 anos, foi preso em flagrante na madrugada de sábado (15) no bairro de Pinheiros, zona oeste de São Paulo. Segundo as autoridades, ele teria agredido a esposa,...')
ON CONFLICT (id) DO NOTHING;

