INSERT INTO public.noticias (
  id, titulo, slug, resumo, conteudo, imagem_url,
  categoria_id, autor_id, data_publicacao, views, destaque, meta_title, meta_description
) VALUES
  ('a242ea5f-e7b4-4807-9e94-93363729dade', 'Governo federal processa Discord e pede R$ 500 milhões por dano moral coletivo', 'governo-federal-processa-discord-e-pede-r-500-milhoes-por-dano-moral-coletivo', 'O Ministério da Justiça ingressou com ação judicial contra a plataforma Discord, alegando a prática de dano moral coletivo contra usuários brasileiros. Na petição, o governo federal requereu...', 'O Ministério da Justiça ingressou com ação judicial contra a plataforma Discord, alegando a prática de dano moral coletivo contra usuários brasileiros. Na petição, o governo federal requereu indenização no valor de R$ 500 milhões.

A medida foi divulgada em comunicado oficial, que destaca a responsabilidade da empresa em garantir a segurança e o respeito nas interações digitais. O caso segue em trâmite nas instâncias competentes, aguardando decisão judicial.', 'https://conteudo.imguol.com.br/c/_layout/solar/defenda-a-verdade-desktop-nao-assinante.png', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-26 21:34:19.422+00', 3, false, 'Governo federal processa Discord e pede R$ 500 milhões por dano moral coletivo', 'O Ministério da Justiça ingressou com ação judicial contra a plataforma Discord, alegando a prática de dano moral coletivo contra usuários brasileiros. Na petição, o governo federal requereu...'),
  ('c1a7fb58-ec16-4c33-96d9-48dce8a97134', 'O que muda para clientes da Oi após declaração de falência', 'o-que-muda-para-clientes-da-oi-apos-declaracao-de-falencia', 'A Anatel informou que a decretação da falência da Oi não implica interrupção imediata dos serviços de telecomunicações. Enquanto os contratos permanecerem em vigor, os consumidores não preci...', 'A Anatel informou que a decretação da falência da Oi não implica interrupção imediata dos serviços de telecomunicações. Enquanto os contratos permanecerem em vigor, os consumidores não precisam cancelar nem transferir seus planos. A agência acompanha o processo e garante a manutenção dos serviços sob responsabilidade da operadora, embora cada segmento – telefonia fixa, banda larga e internet – possa ter destinos diferentes. Caso haja alteração de prestadora, contrato, tecnologia ou canal de atendimento, o cliente deverá ser comunicado previamente e de forma clara.

Para a telefonia fixa, a transferência da outorga para a operadora Método está em análise. Os serviços de banda larga e internet terão continuidade avaliada conjuntamente pela Anatel e pelo administrador judicial. Enquanto o serviço for prestado, os usuários devem continuar pagando as faturas, conferindo eventuais cobranças indevidas. Consumidores que tenham créditos a receber ou ações em curso devem buscar a habilitação desses valores no processo falimentar, observando prazos e procedimentos estabelecidos. Em caso de problemas, a orientação é acionar primeiro os canais oficiais da Oi e, se necessário, registrar reclamação na Anatel pelos meios disponíveis.', 'https://media-manager.noticiasaominuto.com.br/960/naom_5f58b91fd6c6b.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-27 13:14:42.397+00', 4, false, 'O que muda para clientes da Oi após declaração de falência', 'A Anatel informou que a decretação da falência da Oi não implica interrupção imediata dos serviços de telecomunicações. Enquanto os contratos permanecerem em vigor, os consumidores não preci...'),
  ('a433804d-42c6-4508-9238-1332e096c78b', 'Professores aprovados são convocados para atuar na rede estadual da Bahia', 'professores-aprovados-sao-convocados-para-atuar-na-rede-estadual-da-bahia', 'A Secretaria da Educação do Estado da Bahia (SEC) publicou, no Diário Oficial desta quarta‑feira, 26, a convocação de 88 professores aprovados em processos seletivos simplificados para atuar...', 'A Secretaria da Educação do Estado da Bahia (SEC) publicou, no Diário Oficial desta quarta‑feira, 26, a convocação de 88 professores aprovados em processos seletivos simplificados para atuar na rede estadual. Dentre os convocados, 73 foram designados para a Educação Básica, sete para a Educação Profissional e oito para a função de professor orientador de Estágio em Saúde.  

Os candidatos têm até 8 de setembro para apresentar a documentação exigida. A primeira etapa consiste no envio dos documentos digitalizados para o e‑mail ingressocpm.sec@enova.educacao.ba.gov.br, que será analisado preliminarmente pela Coordenação de Provimento e Movimentação. Após a aprovação, os originais, acompanhados de cópias, devem ser entregues presencialmente. Em Salvador, o atendimento ocorre na sede da Secretaria, no Centro Administrativo da Bahia (CAB), das 8h30 às 11h e das 14h às 17h; nos municípios do interior, a entrega deve ser feita nos respectivos Núcleos Territoriais de Educação (NTEs). Entre os documentos solicitados estão diploma compatível com a função, identidade, CPF, comprovante de residência, declaração de inexistência de acúmulo de cargos públicos e certidões negativas. A convocação integra o processo de ingresso dos profissionais aprovados e garante a reposição de vagas nas escolas estaduais.', 'https://cdn.atarde.com.br/img/Artigo-Destaque/1390000/bahia-convoca-88-professores-aprovados-em-selecoes0139985900202608261558.jpg?xid=7186519', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-27 13:17:36.799+00', 0, false, 'Professores aprovados são convocados para atuar na rede estadual da Bahia', 'A Secretaria da Educação do Estado da Bahia (SEC) publicou, no Diário Oficial desta quarta‑feira, 26, a convocação de 88 professores aprovados em processos seletivos simplificados para atuar...'),
  ('caadd5b9-4ed8-4b71-9628-16cccdd6f9e1', 'Estudo prevê retirada de até R$ 141 bilhões da economia brasileira por apostas em 2025', 'estudo-preve-retirada-de-ate-r-141-bilhoes-da-economia-brasileira-por-apostas-em', 'Um estudo do Centro de Pesquisa em Macroeconomia das Desigualdades (Made), da FEA-USP, aponta que o avanço das apostas esportivas e jogos virtuais pode retirar entre R$ 120 bilhões e R$ 141 ...', 'Um estudo do Centro de Pesquisa em Macroeconomia das Desigualdades (Made), da FEA-USP, aponta que o avanço das apostas esportivas e jogos virtuais pode retirar entre R$ 120 bilhões e R$ 141 bilhões da atividade econômica brasileira em 2025. Esse impacto, que vai além do endividamento familiar, corresponde a uma redução estimada de 0,9% a 1,1% do Produto Interno Bruto (PIB) e equivale a uma parcela significativa do crescimento econômico esperado para o período. O levantamento, elaborado por Guilherme Klein com dados do Centro Celso Furtado, calculou a perda líquida das famílias em R$ 62,5 bilhões para 2025, resultante da diferença entre o total apostado e o valor dos prêmios devolvidos aos jogadores.

A pesquisa explica que o dinheiro destinado às apostas deixa de ser utilizado na compra de produtos e serviços essenciais como alimentação, vestuário e moradia, afetando principalmente famílias de menor renda devido à sua alta propensão marginal ao consumo. A consequência é uma redução da demanda que impacta diversos setores da economia. Embora o setor de apostas tenha gerado cerca de 15,5 mil empregos, segundo estimativa da LCA Consultores citada no estudo, esse número não seria suficiente para compensar os efeitos econômicos negativos. Além disso, a regulamentação das apostas, que arrecadou R$ 9 bilhões em impostos diretos em 2025, não neutralizaria a frustração de receitas tributárias que varia entre R$ 31,1 bilhões e R$ 54,8 bilhões, decorrente da retração da atividade econômica.', 'https://d1x4bjge7r9nas.cloudfront.net/wp-content/uploads/2026/08/24183635/620x400-2026-08-24T183555.512.png', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-27 13:18:03.713+00', 4, false, 'Estudo prevê retirada de até R$ 141 bilhões da economia brasileira por apostas em 2025', 'Um estudo do Centro de Pesquisa em Macroeconomia das Desigualdades (Made), da FEA-USP, aponta que o avanço das apostas esportivas e jogos virtuais pode retirar entre R$ 120 bilhões e R$ 141 ...'),
  ('92af8bb7-30ec-4fcd-b132-170e57e30a52', 'Médico alvo operação por estupro e pornografia infantil em Salvador', 'medico-alvo-operacao-por-estupro-e-pornografia-infantil-em-salvador', 'Um médico urologista foi incluído na Operação Brilho do Amanhã, que investiga suspeitos de estupro de vulnerável, produção e armazenamento de pornografia infantil na Bahia. Identificado como...', 'Um médico urologista foi incluído na Operação Brilho do Amanhã, que investiga suspeitos de estupro de vulnerável, produção e armazenamento de pornografia infantil na Bahia. Identificado como Samuel Juncal, o profissional reside no bairro da Barra, em Salvador, e possui graduação pela Universidade Federal da Bahia (UFBA) e especialização nos Estados Unidos.

Na madrugada desta quinta‑feira (27), equipes policiais cumpriram mandados de busca e apreensão na residência do médico. Não foi expedido mandado de prisão contra ele. Em nota, a defesa afirmou que o urologista é inocente, qualificando as acusações como infundadas e caluniosas, e ressaltou a colaboração plena e transparente com as autoridades e o Poder Judiciário. A defesa também alegou que a medida foi “totalmente desnecessária e desproporcional”, citando testemunhas indicadas nos dias 12, 17 e 20 de agosto que poderiam atestar a inocência do investigado.

A Operação Brilho do Amanhã mobiliza cerca de 120 policiais em Salvador e em municípios como Lauro de Freitas, Itagi, Seabra, São Félix e Conceição do Coité, com foco em crimes digitais. O ciclo operacional em curso ocorre entre 24 e 28 de agosto e conta com o apoio de diversos departamentos da Polícia Civil, da Polícia Militar e da Secretaria de Administração Penitenciária e Ressocialização.', 'https://midias.correio24horas.com.br/2026/08/27/medico-urologista-e-alvo-de-operacao-por-estupro-de-vulneravel-e-armazenamento-de-pornografia-infantil-em-salvador-3392861-article.webp', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-27 13:20:11.32+00', 4, false, 'Médico alvo operação por estupro e pornografia infantil em Salvador', 'Um médico urologista foi incluído na Operação Brilho do Amanhã, que investiga suspeitos de estupro de vulnerável, produção e armazenamento de pornografia infantil na Bahia. Identificado como...'),
  ('116e8f81-d4de-497f-8eaf-006ab0a6587a', 'Onda de calor pode alcançar 47°C no Brasil em novembro', 'onda-de-calor-pode-alcancar-47-c-no-brasil-em-novembro', 'O Brasil enfrentará, nos próximos dias, uma nova onda de calor intenso, com temperaturas acima de 40°C em grande parte do território. O alerta foi emitido pelo Climatempo a partir desta quar...', 'O Brasil enfrentará, nos próximos dias, uma nova onda de calor intenso, com temperaturas acima de 40°C em grande parte do território. O alerta foi emitido pelo Climatempo a partir desta quarta‑feira, 8 de novembro, e o meteorologista Vinicius Lucyrio classificou o fenômeno como “histórico”, possivelmente mais forte que a onda de setembro.

Para o fim de semana, as previsões apontam máximas de até 47°C em áreas do Mato Grosso do Sul. Na sexta‑feira (10) o interior de São Paulo deve registrar 40°C, igual ao esperado para o Triângulo Mineiro, sul de Goiás e sul do Tocantins. Leste de Minas Gerais e Espírito Santo também enfrentarão calor intenso. O calor continuará no sábado e domingo em regiões como sul de Mato Grosso, sul e oeste de Goiás, interior de São Paulo, Vale do Ribeira, Grande Rio, região dos Lagos, Campos e extremo norte do Paraná. Na segunda‑feira (13) o calor afetará Espírito Santo, leste de Minas, Maranhão, Tocantins, Piauí e Bahia, persistindo até quarta‑feira (15). Uma onda de calor é definida como um período anormalmente quente e prolongado em relação às condições climáticas típicas da região.', 'https://olhardigital.com.br/wp-content/uploads/2023/07/calor.jpg', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-27 13:22:51.673+00', 1, false, 'Onda de calor pode alcançar 47°C no Brasil em novembro', 'O Brasil enfrentará, nos próximos dias, uma nova onda de calor intenso, com temperaturas acima de 40°C em grande parte do território. O alerta foi emitido pelo Climatempo a partir desta quar...'),
  ('2b101adc-f5aa-4b3c-ac9d-6f87f9c68313', 'Motorista que devolveu R$ 131,8 milhões tem processo sem testemunhas', 'motorista-que-devolveu-r-131-8-milhoes-tem-processo-sem-testemunhas', 'O Tribunal de Justiça do Tocantins (TJTO) negou o agravo de instrumento interposto pela defesa de Antônio Pereira do Nascimento, que recebeu R$ 131,870,227 por erro do Bradesco em 2023. A de...', 'O Tribunal de Justiça do Tocantins (TJTO) negou o agravo de instrumento interposto pela defesa de Antônio Pereira do Nascimento, que recebeu R$ 131,870,227 por erro do Bradesco em 2023. A decisão da 6ª Vara Cível de Palmas, que dispensou a oitiva de testemunhas, foi mantida, e o processo seguirá sem produção de prova testemunhal nesta fase. Antônio devolveu integralmente o valor no mesmo dia em que identificou o depósito, mas alega ter sofrido cobrança de tarifas, encargos e pressão psicológica de um gerente do banco. Ele ajuizou ação em 2024 requerendo R$ 13,187,022 como recompensa pela devolução e R$ 150 mil por danos morais.  

A relatora, desembargadora Maria Celma Louzeiro Tiago, considerou que o recurso não se enquadra nas hipóteses legais para revisão da decisão e que não houve demonstração de urgência. Caso a sentença seja desfavorável e se mostre necessária a oitiva de testemunhas, a questão poderá ser reavaliada em eventual recurso de apelação. O Bradesco não se pronunciou sobre a decisão; a defesa de Antônio ainda não se manifestou.', 'https://iclnoticias.com.br/app/uploads/2026/08/foto-e-montagem-vertical-8-960x540-1.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-27 14:02:15.44+00', 7, false, 'Motorista que devolveu R$ 131,8 milhões tem processo sem testemunhas', 'O Tribunal de Justiça do Tocantins (TJTO) negou o agravo de instrumento interposto pela defesa de Antônio Pereira do Nascimento, que recebeu R$ 131,870,227 por erro do Bradesco em 2023. A de...'),
  ('e780fc02-af08-4a95-bf34-d78a71ca771a', 'Idoso 81 morre após queda ao colher frutas em Ribeira do Amparo', 'idoso-81-morre-apos-queda-ao-colher-frutas-em-ribeira-do-amparo', 'José Cardoso da Silva, 81, morreu ao cair de escada enquanto colhia frutas em sua casa no povoado Raspador, em Ribeira do Amparo, na manhã de 26. Polícia realizou perícia e autópsia.', 'Na manhã da última terça-feira (26), um idoso morreu após sofrer um acidente em sua residência, situada à Praça da Matriz, no povoado Raspador, em Ribeira do Amparo (BA). Segundo informações, José Cardoso da Silva, 81 anos, subiu em uma escada para colher frutos em uma árvore, desequilibrou‑se e caiu. Ao chegar ao local, familiares encontraram o homem sem sinais vitais.  

O fato foi comunicado aos policiais militares da cidade e ao Departamento de Polícia Técnica (DPT) de Ribeira do Pombal, que realizou a perícia e providenciou a remoção do corpo para autópsia.', 'https://www.portalalerta.com.br/wp-content/uploads/2018/01/assassinaton.jpg', '6b283438-a9a3-4742-8705-7cfed6acfd49', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-27 18:44:20.632002+00', 114, true, 'Idoso 81 morre após queda ao colher frutas em Ribeira do Amparo', NULL),
  ('7a6ee5f5-f7bd-4018-99d1-131ffac62de8', 'Desemprego no Brasil cai para 5,3% e ocupação atinge recorde', 'desemprego-no-brasil-cai-para-5-3-e-ocupacao-atinge-recorde', 'A taxa de desemprego no Brasil ficou em 5,3% no trimestre encerrado em julho, segundo a PNAD Contínua do IBGE, o menor índice registrado para o período de maio a julho desde o início da séri...', 'A taxa de desemprego no Brasil ficou em 5,3% no trimestre encerrado em julho, segundo a PNAD Contínua do IBGE, o menor índice registrado para o período de maio a julho desde o início da série histórica em 2012. O resultado representa queda em relação ao trimestre anterior, que tinha 5,8%, e fica abaixo dos 5,6% observados no mesmo período de 2025. Paralelamente, a população ocupada chegou a 103,3 milhões de pessoas, número recorde da pesquisa. No setor privado formal, sem contar empregados domésticos, o contingente chegou a 39,4 milhões, também recorde, enquanto os trabalhadores sem carteira assinada totalizaram 13,8 milhões, alta de 3,6% (477 mil) em relação ao trimestre anterior.

O IBGE apontou a construção civil e o setor de transporte, armazenagem e correio – que inclui entregadores de aplicativos – como principais motores do aumento de ocupação, com crescimento de 5,4% neste último segmento. O número de desempregados foi de 5,8 milhões, redução de 503 mil pessoas (8%) em comparação ao trimestre de fevereiro a abril. A taxa de informalidade ficou em 37,5% da população ocupada, ligeiramente acima de 37,2% no trimestre anterior, e o contingente de desalentados caiu 9,7%, para 2,3 milhões. O rendimento médio mensal estimado foi de R$ 3.762, 0,7% menor que em abril, mas considerado estatisticamente estável.', 'https://primeirapagina.com.br/wp-content/uploads/2024/05/Design-sem-nome-2024-05-08T220719.273.jpg', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-27 19:15:01.461+00', 6, false, 'Desemprego no Brasil cai para 5,3% e ocupação atinge recorde', 'A taxa de desemprego no Brasil ficou em 5,3% no trimestre encerrado em julho, segundo a PNAD Contínua do IBGE, o menor índice registrado para o período de maio a julho desde o início da séri...'),
  ('2dabdb81-9289-4546-a9d0-32fb93b463b0', 'Criança de 6 anos está entre os feridos em acidente com motos em Ribeira do Pombal', 'crianca-de-6-anos-esta-entre-os-feridos-em-acidente-com-motos-em-ribeira-do', 'Um acidente entre duas motocicletas em Ribeira do Pombal deixou múltiplos feridos, incluindo uma criança de 6 anos. A colisão na Avenida Pedro Rodrigues da Conceição envolveu uma cinquentinha com três ocupantes. As vítimas foram socorridas pelo SAMU e levadas ao Hospital Geral Santa Teresa.', 'Um acidente envolvendo duas motocicletas foi registrado na Avenida Pedro Rodrigues da Conceição, na zona norte de Ribeira do Pombal. O incidente resultou em múltiplos feridos, incluindo uma criança de seis anos. Segundo informações de testemunhas, uma das motocicletas, uma cinquentinha (50cc), transportava três pessoas, sendo um casal e a criança. Com o impacto da colisão, a criança sofreu escoriações, enquanto os dois adultos também ficaram feridos.

Relatos adicionais indicam que o condutor da outra motocicleta teria colidido na traseira da 50cc. A força da batida o lançou para frente, causando diversos ferimentos e uma forte pancada na cabeça ao cair no chão. A Polícia Militar foi acionada, esteve no local e realizou os primeiros levantamentos. O Serviço de Atendimento Móvel de Urgência (SAMU) enviou duas ambulâncias para atender as vítimas, que foram socorridas e encaminhadas ao Hospital Geral Santa Teresa (HGST). A recorrência de acidentes com motocicletas na cidade tem gerado preocupação e reforça a necessidade de conscientização no trânsito.', 'https://imagemlink.cleissoncardoso.com/uploads/2793c1cd-397b-4268-9c2c-2dbaa891026e.png', '7d34292b-4217-4571-ba21-f7aa996aa1d3', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-27 22:09:42.41522+00', 1032, true, 'Acidente com motos em Ribeira do Pombal fere criança e adultos', 'Colisão entre duas motocicletas na Avenida Pedro Rodrigues da Conceição, em Ribeira do Pombal, deixa uma criança de 6 anos e outros adultos feridos. Vítimas foram socorridas pelo SAMU.'),
  ('2d038693-9ff9-4b92-b13e-08f9b3c7cc5b', 'Quaest divulga avaliação do governo da Bahia', 'quaest-divulga-avaliacao-do-governo-da-bahia', 'A empresa de pesquisa Quaest publicou uma avaliação do atual governo do estado da Bahia. O documento apresenta uma análise dos resultados alcançados pela administração estadual, permitindo a...', 'A empresa de pesquisa Quaest publicou uma avaliação do atual governo do estado da Bahia. O documento apresenta uma análise dos resultados alcançados pela administração estadual, permitindo ao público acompanhar o desempenho das políticas públicas implementadas.

A divulgação da avaliação tem o objetivo de oferecer transparência e subsidiar o debate público sobre a gestão estadual. Interessados podem acessar o relatório completo por meio dos canais oficiais da Quaest, contribuindo para uma maior compreensão dos avanços e desafios enfrentados pelo governo da Bahia.', 'https://s2-g1.glbimg.com/3m3_UoglZrVhdyv97lFHAFfqBOE=/2048x0/filters:format(jpeg)/https://i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/A/n/ueumsETd6CfovYKxm5oA/amanda-erciliagovba.jpg', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-28 01:12:42.014+00', 1, false, 'Quaest divulga avaliação do governo da Bahia', 'A empresa de pesquisa Quaest publicou uma avaliação do atual governo do estado da Bahia. O documento apresenta uma análise dos resultados alcançados pela administração estadual, permitindo a...'),
  ('afb5443e-8380-4519-9b08-6a3efc2bfb9e', 'Operação Brilho do Amanhã prende 51 por crimes contra crianças, com prisões em Heliópolis', 'operacao-brilho-do-amanha-prende-51-por-crimes-contra-criancas-com-prisoes-em', 'A Polícia Civil da Bahia realizou 51 prisões em mais um ciclo da Operação Brilho do Amanhã, combatendo crimes contra crianças e adolescentes. As detenções ocorreram entre 24 e 27 de agosto em diversas cidades, incluindo Heliópolis e Ribeira do Amparo, resultando também em inquéritos e apreensões.', 'A Polícia Civil da Bahia concluiu mais um ciclo da Operação Brilho do Amanhã, resultando na prisão de 51 indivíduos entre os dias 24 e 27 de agosto. A ação teve como foco o combate a crimes contra crianças e adolescentes em diversas regiões do estado. Além das detenções, a operação gerou a instauração de 38 inquéritos policiais, a apreensão de quatro armas de fogo e 11 dispositivos eletrônicos. Entre as cidades onde as prisões foram efetuadas, destacam-se Heliópolis, Ribeira do Amparo, Salvador, Lauro de Freitas, Paulo Afonso, Vitória da Conquista e Ilhéus, demonstrando a abrangência da iniciativa policial.

Do total de prisões, nove ocorreram na capital, Salvador, e 42 no interior do estado. A natureza das prisões incluiu 27 preventivas, duas temporárias e dez decorrentes de condenações já existentes, além de 12 prisões em flagrante durante as diligências. Segundo o delegado-geral adjunto de Operações, Jorge Figueiredo, a operação representa um marco na segurança pública baiana, evidenciando a capacidade da Polícia Civil em proteger crianças e adolescentes. Ele informou ainda que a Operação Brilho do Amanhã, coordenada pelo Departamento de Proteção à Mulher, Cidadania e Pessoas Vulneráveis (DPMCV), terá novos ciclos para dar continuidade às investigações e combater esses crimes.', 'https://imagemlink.cleissoncardoso.com/uploads/a20ea101-1027-4314-af51-3e7dc69d0c02.png', '2dd68615-05d7-48f1-9467-819514c31649', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-28 12:36:17.742111+00', 1025, true, 'Operação Brilho do Amanhã prende 51 por crimes contra crianças, inclusive em Heliópolis', 'A Polícia Civil da Bahia deteve 51 pessoas na Operação Brilho do Amanhã, focada em crimes contra crianças e adolescentes. Prisões ocorreram em várias cidades, como Heliópolis, com 38 inquéritos instaurados.'),
  ('af7879eb-c636-413a-a555-426303921ae7', 'MP prorroga inquérito sobre acúmulo ilegal de cargos em Cícero Dantas', 'mp-prorroga-inquerito-sobre-acumulo-ilegal-de-cargos-em-cicero-dantas', 'O MP da Bahia prorrogou o prazo do inquérito que investiga acúmulo ilegal de cargos e possíveis obras fantasmas na administração de Cícero Dantas, podendo gerar ação civil e ressarcimento ao erário.', 'O Ministério Público da Bahia (MP‑BA) prorrogou o prazo do inquérito civil que investiga, há nove anos, possíveis atos de improbidade administrativa ligados ao acúmulo ilegal de cargos públicos na administração municipal de Cícero Dantas. A 3ª Promotoria de Justiça de Cícero Dantas divulgou a extensão em publicação no Diário Oficial da Justiça nesta quinta‑feira, 27, ressaltando que, embora a apuração tenha se iniciado em 2017, ainda são necessárias diligências essenciais antes de definir os próximos passos.

O inquérito civil nº 656.9.122073/2017 busca identificar servidores que ocupem mais de um cargo público de forma irregular, possivelmente violando normas constitucionais e princípios da administração pública, além de averiguar se tais acumulações geraram pagamentos indevidos ou prejuízos ao erário. A investigação integra um conjunto de procedimentos da 3ª Promotoria que também examinam o ex‑prefeito Helânio Calazans em outros inquéritos, como o de contas públicas (nº 656.9.106249/2017) e o de obras e superfaturamento na reforma do Colégio Municipal Monsenhor Galvão (nº 656.0.74066/2014). Caso sejam confirmadas as suspeitas, o MP poderá propor medidas judiciais ou extrajudiciais, inclusive ação civil pública e pedido de ressarcimento ao cofres públicos. A TARDE questionou o órgão sobre a previsão de conclusão dos inquéritos e aguarda resposta.', 'https://cdn.atarde.com.br/img/Artigo-Destaque/1390000/mp-prorroga-inqueritos-sobre-obras-fantasmas-e-acu0139994500202608271230.jpg?xid=7187440', '1bff82e6-6033-4d75-8d04-e26d976c0a05', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-28 16:21:52.826203+00', 116, true, 'MP prorroga inquérito sobre acúmulo ilegal de cargos em Cícero Dantas', NULL),
  ('02ea4f39-9528-47ed-925d-1f694a139d9f', 'DNIT inicia obra de acostamento de 2,5m em cada lado da BR-410, no perímetro urbano de Ribeira do Pombal, com 3 km de extensão.', 'dnit-inicia-obra-de-acostamento-de-25m-em-cada-lado-da-br-410-no-perimetro-urbano-de-ribeira-do-pombal-com-3-km-de-extensao', 'O DNIT começou intervenção na BR-410, no perímetro urbano de Ribeira do Pombal. A obra prevê acostamento de 2,5 metros em cada lado da via, num trecho de 3 km entre a PRF e o final do perímetro urbano. Segundo o superintendente do DNIT-BA, a medida busca dar mais fluidez e segurança aos usuários.', 'O Departamento Nacional de Infraestrutura de Transportes (DNIT) iniciou intervenção na BR-410, dentro do perímetro urbano de Ribeira do Pombal. A obra consiste na implantação de acostamento de 2,5 metros em cada lado da via.

O trecho contemplado tem 3 km de extensão, começando na altura da unidade da Polícia Rodoviária Federal (PRF) e seguindo até o limite final do perímetro urbano do município.

A nossa reportagem,  o superintendente regional do DNIT na Bahia, Roberto Alcântara, afirmou que a medida visa garantir mais fluidez e segurança aos usuários que trafegam pela via. Ele também teria mencionado outros projetos em andamento para execução na BR-110, informação que aguarda confirmação oficial e detalhamento por parte do órgão.

Para os moradores e motoristas que utilizam a BR-410 diariamente, a ampliação do acostamento pode significar redução de riscos de acidentes, especialmente em situações de parada de emergência ou tráfego de veículos mais lentos, como bicicletas e motos.



', 'https://mkbnqyhvaozqfpmcyoyw.supabase.co/storage/v1/object/public/imagens/noticias/1787948601956_bu9arsr.webp', '7d34292b-4217-4571-ba21-f7aa996aa1d3', NULL, '2026-08-28 20:25:14.558+00', 1976, true, '', 'DNIT inicia obra de acostamento de 2,5m em cada lado da BR-410, no perímetro urbano de Ribeira do Pombal, com 3 km de extensão.'),
  ('1b933d34-5292-4a9d-8ced-9e577181cf88', 'Sincopa define regras para comércio funcionar no feriado de 7 de Setembro', 'sincopa-define-regras-para-comercio-funcionar-no-feriado-de-7-de-setembro', 'O Sindicato dos Empregados em Estabelecimentos Comerciais e de Serviços de Paulo Afonso e Região (Sincopa) publicou aviso sobre o funcionamento do comércio no feriado de 7 de setembro. A norma vale para Ribeira do Pombal, Antas, Cícero Dantas, Tucano e Paripiranga. O documento define horários e valores de bonificação para lojistas e supermercados.', 'O Sindicato dos Empregados em Estabelecimentos Comerciais e de Serviços de Paulo Afonso e Região (Sincopa), em parceria com a Delegacia Sindical de Ribeira do Pombal, divulgou nesta sexta-feira (28) as regras de funcionamento do comércio para o feriado nacional de 7 de setembro, Dia da Independência do Brasil, que cai em uma segunda-feira. O aviso vale para os municípios de Ribeira do Pombal, Antas, Cícero Dantas, Tucano e Paripiranga.

Segundo o documento, o comércio lojista em geral poderá abrir das 8h às 13h, sem prorrogação de horário. Os trabalhadores que atuarem no feriado terão direito a folga compensatória e ao pagamento de bonificação de R$ 55,84, conforme a cláusula 16ª da Convenção Coletiva de Trabalho (CCT) 2026 da categoria lojista.

Já os supermercados têm autorização para funcionar das 8h às 18h. Nesse caso, a bonificação varia conforme a jornada: R$ 52,00 para quem trabalhar 6 horas e R$ 71,00 para jornada de 8 horas, além do direito à folga. A regra segue a cláusula 18ª da CCT 2026.

O orgão reforçou que as empresas devem seguir as normas para evitar autuações e garantir os direitos dos trabalhadores durante o feriado. O sindicato disponibilizou contato direto para dúvidas de empresários e empregados: (75) 99927-4080 e (75) 99852-0721.

Para o comércio, o entendimento evita conflitos trabalhistas e assegura previsibilidade tanto para empresários quanto para funcionários que atuarão no feriado nacional.

', 'https://mkbnqyhvaozqfpmcyoyw.supabase.co/storage/v1/object/public/imagens/noticias/1787956170870_g2ymroe.webp', '7d34292b-4217-4571-ba21-f7aa996aa1d3', NULL, '2026-08-28 22:32:17.425+00', 5975, true, 'Sindicato define horário do comércio no 7 de Setembro', 'Sincopa divulga regras de funcionamento do comércio em Ribeira do Pombal e região no feriado da Independência. Confira horários e bonificação.
'),
  ('c373bd63-09ff-4730-ac5f-3a559a6d4cc7', 'Território de Itaparica passa a se chamar Raso da Catarina e recebe três municípios do Semiárido Nordeste II', 'territorio-de-itaparica-passa-a-se-chamar-raso-da-catarina-e-recebe-tres-municipios-do-semiarido-nordeste-ii', 'Assembleia territorial aprovou nesta quarta (26) a troca de nome do Território de Identidade Itaparica para Raso da Catarina. Jeremoabo, Pedro Alexandre e Coronel João Sá deixaram o Território Semiárido Nordeste II e passaram a integrar o novo bloco, que salta de 6 para 9 municípios.', 'Uma assembleia territorial realizada na manhã desta quarta-feira (26) aprovou duas mudanças estruturais no bloco liderado por Paulo Afonso. O grupo, antes chamado Território de Identidade Itaparica, adotou oficialmente o nome Território de Identidade Raso da Catarina.

Na mesma reunião, foi aprovada a entrada de Jeremoabo, Pedro Alexandre e Coronel João Sá, que até então integravam o Território Semiárido Nordeste II. Com a adesão, o colegiado passou de 6 para 9 municípios.

O processo foi conduzido pela Secretaria do Planejamento do Estado da Bahia (Seplan) e pelo Conselho Estadual de Desenvolvimento Territorial (Cedeter), com base na Lei Estadual nº 13.214/2014, na Resolução Cedeter nº 01/2026 e na Resolução Condraf nº 40/2025. Lideranças classificaram a mudança como uma "reparação histórica", já que os três municípios mantêm laços econômicos e culturais consolidados com Paulo Afonso.

A troca de nome também reflete uma mudança simbólica: "Itaparica" remetia ao complexo hidrelétrico da região, enquanto "Raso da Catarina" faz referência ao ecossistema de caatinga que liga essas comunidades — área que abriga espécies como a arara-azul-de-lear.

Um pedido semelhante de Santa Brígida não foi aceito neste momento, e o município permanece no Território Semiárido Nordeste II. O grupo decidiu elaborar uma carta convite conjunta para reforçar esse pleito no futuro. Para o cidadão da região, a mudança pode significar reorganização de políticas públicas, investimentos e articulação institucional em saúde, educação e infraestrutura a partir de Paulo Afonso.', 'https://s2-g1.glbimg.com/XKW3gUgQCnR1CZq0rqOeINVC-WQ=/347x256:1763x1057/984x0/smart/filters:strip_icc()/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2019/n/z/TLioiNREGsyX5szVyOQQ/f99a0070-marcelo-brandt-g1.jpg', '902d44ce-469a-438d-82c4-b6e4a8357a30', NULL, '2026-08-29 14:37:44.383+00', 1532, true, 'Território de Itaparica vira Raso da Catarina e ganha 3 municípios', 'Jeremoabo, Pedro Alexandre e Coronel João Sá deixam Semiárido Nordeste II e entram no novo Território Raso da Catarina.'),
  ('0497a588-89ce-4e98-b39b-b293029fe864', 'Título da matéria: Colisão entre ônibus e carro deixa uma vítima fatal na BR-116, entre Serrinha e Santa Bárbara', 'titulo-da-materia-colisao-entre-onibus-e-carro-deixa-uma-vitima-fatal-na-br-116-entre-serrinha-e-santa-barbara', 'Um acidente grave entre um ônibus e um Chevrolet Celta deixou pelo menos uma vítima fatal na manhã deste sábado (29), na BR-116, entre Serrinha e Santa Bárbara. O carro ficou destruído com o impacto. PRF e SAMU atuam no trecho, que tem interdição parcial.', 'Uma colisão entre um ônibus e um Chevrolet Celta deixou pelo menos uma vítima fatal na manhã deste sábado (29), na BR-116, no trecho entre Serrinha e Santa Bárbara, no semiárido baiano.

O impacto foi de grande violência: o carro de passeio ficou completamente destruído, partido ao meio. Equipes da Polícia Rodoviária Federal (PRF) e do SAMU foram mobilizadas para socorrer as vítimas e organizar o tráfego no local.

Até o momento, não há confirmação oficial sobre o número total de feridos nem sobre o estado de saúde dos socorridos. As causas da colisão ainda serão apuradas pela PRF, que deve realizar perícia no trecho — histórico recente da via já registra outros acidentes graves na mesma região, entre eles um em julho deste ano com vítima fatal.

O tráfego segue com interdição parcial e lentidão no sentido do acidente. Motoristas que trafegam pela BR-116 devem redobrar a atenção e seguir orientações das equipes no local.', 'https://mkbnqyhvaozqfpmcyoyw.supabase.co/storage/v1/object/public/imagens/noticias/1788022074805_outtvaf.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', NULL, '2026-08-29 16:48:46.509+00', 531, false, 'Acidente na BR-116 entre Serrinha e Santa Bárbara deixa 1 morto', 'Colisão entre ônibus e Celta na BR-116 mata uma pessoa neste sábado (29). PRF e SAMU atuam no local; trânsito segue lento.'),
  ('0facc4e1-0ff9-4218-bc62-8d906cad5ce5', 'Vídeo flagra deputado Marcelo Nilo em discussão acalorada com eleitora na Feira Livre de Antas', 'video-flagra-deputado-marcelo-nilo-em-discussao-acalorada-com-eleitora-na-feira-livre-de-antas', 'Um vídeo que circula nas redes sociais mostra o deputado federal Marcelo Nilo em confronto verbal com uma eleitora durante ação de panfletagem na Feira Livre de Antas, sua terra natal. Nas imagens, a moradora questiona a atuação do parlamentar no município e recebe resposta em tom agressivo. O episódio ocorre em meio a um momento de desgaste político de Nilo na cidade.', '
Um vídeo que circula nas redes sociais mostra o deputado federal Marcelo Nilo (Republicanos) em confronto verbal com uma eleitora durante panfletagem na Feira Livre de Antas, município que é sua terra natal, no Nordeste baiano. Nas imagens, a moradora questiona diretamente a atuação do parlamentar na cidade, dizendo que ele "nunca fez nada" pelo município, seguido de ofensa. Nilo reage no mesmo tom, a  resposta teria sido igualmente agressiva.

O registro, gravado por populares presentes na feira, reforça um cenário já delicado para o deputado em sua base política de origem. Nas últimas semanas, Nilo vem enfrentando rupturas com aliados históricos em Antas, incluindo o próprio irmão, o ex-prefeito Sidônio Nilo, e a atual prefeita Essioneide Pimentel, ambos alinhados ao deputado federal Gabriel Nunes nas eleições de 2026.

O vídeo da discussão na feira, embora amplamente compartilhado, não foi acompanhado de nota oficial do gabinete do parlamentar até o momento. Não há confirmação sobre o contexto completo da abordagem, nem manifestação da eleitora envolvida.

O episódio se soma a uma sequência de embates públicos do deputado nos últimos meses — incluindo discussões em podcast e confrontos durante gravações de conteúdo em Salvador — alimentando o debate sobre o desgaste de imagem de Nilo às vésperas do período eleitoral.




', 'https://mkbnqyhvaozqfpmcyoyw.supabase.co/storage/v1/object/public/imagens/noticias/1788022812937_8s1fhur.webp', '2938605f-8be9-4f18-b52b-99bc1c4a72f8', NULL, '2026-08-29 17:00:18.641+00', 8586, true, ' Vídeo mostra Marcelo Nilo em bate-boca com eleitora em Antas', 'Vídeo que circula nas redes mostra deputado Marcelo Nilo em discussão acalorada com moradora durante panfletagem na Feira Livre de Antas.'),
  ('c5ec0715-37f9-40a1-bd50-268ace017fd3', 'VídeoflagradeputadoMarceloNiloemdiscussãoacaloradacomeleitorana', 'videoflagradeputadomarceloniloemdiscussaoacaloradacomeleitorana', 'Um vídeo que circula nas redes sociais mostra o deputado federal Marcelo Nilo (Republicanos) em confronto verbal com uma eleitora durante panfletagem na Feira Livre de Antas, município que é...', 'Um vídeo que circula nas redes sociais mostra o deputado federal Marcelo Nilo (Republicanos) em confronto verbal com uma eleitora durante panfletagem na Feira Livre de Antas, município que é sua terra natal, no Nordeste baiano. Nas imagens, a moradora questiona diretamente a atuação do parlamentar na cidade, dizendo que ele "nunca fez nada" pelo município, seguido de ofensa. Nilo reage no mesmo tom, a resposta teria sido igualmente agressiva. O registro, gravado por populares presentes na feira, reforça um cenário já delicado para o deputado em sua base política de origem. Nas últimas semanas, Nilo vem enfrentando rupturas com aliados históricos em Antas, incluindo o próprio irmão, o ex-prefeito Sidônio Nilo, e a atual prefeita Essioneide Pimentel, ambos alinhados ao deputado federal Gabriel Nunes nas eleições de 2026. O vídeo da discussão na feira, embora amplamente compartilhado, não foi acompanhado de nota oficial do gabinete do parlamentar até o momento. Não há confirmação sobre o contexto completo da abordagem, nem manifestação da eleitora envolvida. O episódio se soma a uma sequência de embates públicos do deputado nos últimos meses — incluindo discussões em podcast e confrontos durante gravações de conteúdo em Salvador — alimentando o debate sobre o desgaste de imagem de Nilo às vésperas do período eleitoral.', 'https://mkbnqyhvaozqfpmcyoyw.supabase.co/storage/v1/object/public/imagens/noticias/1788022812937_8s1fhur.webp', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-29 17:25:17.217415+00', 0, false, 'VídeoflagradeputadoMarceloNiloemdiscussãoacaloradacomeleitorana', 'Um vídeo que circula nas redes sociais mostra o deputado federal Marcelo Nilo (Republicanos) em confronto verbal com uma eleitora durante panfletagem na Feira Livre de Antas, município que é...'),
  ('bdb0e0f2-6274-463e-831a-5204a080d4bb', 'Duas pessoas morrem em grave acidente na BA-393 entre Poço Verde e Heliópolis', 'duas-pessoas-morrem-em-grave-acidente-na-ba-393-entre-poco-verde-e-heliopolis', 'Duas pessoas morreram em um grave acidente de trânsito ocorrido na noite de sábado (29) na BA-393, no trecho entre Poço Verde (SE) e Heliópolis (BA). As vítimas foram levadas a Heliópolis, mas não resistiram. Uma delas foi identificada.', 'Um grave acidente de trânsito foi registrado na noite deste sábado (29), por volta das 21h, na rodovia BA-393. O sinistro ocorreu na altura da localidade conhecida como Serra de Agenor, trecho que liga os municípios de Poço Verde, em Sergipe, e Heliópolis, na Bahia. O Serviço de Atendimento Móvel de Urgência (SAMU) foi acionado para socorrer as vítimas no local. Conforme informações preliminares, os envolvidos sofreram ferimentos graves, incluindo fraturas expostas, e foram prontamente encaminhados para uma unidade de saúde em Heliópolis. Infelizmente, apesar do atendimento, os feridos não resistiram aos ferimentos e vieram a óbito. O SAMU de Fátima também prestou apoio na ocorrência.

Uma das vítimas foi identificada como José Lucas do Nascimento, de 32 anos, residente do povoado João Grande, no município de Heliópolis. A segunda vítima, de 20 anos, era moradora da localidade de Sapé, também em Heliópolis, mas sua identidade ainda não havia sido oficialmente confirmada até a publicação desta matéria. As circunstâncias que levaram ao acidente ainda serão devidamente apuradas pelas autoridades competentes para determinar as causas e responsabilidades. A reportagem está em atualização e novas informações sobre o ocorrido e a identificação da segunda vítima serão divulgadas em breve.', 'https://imagemlink.cleissoncardoso.com/uploads/89bb57f3-692b-4e6a-8b84-fbdb3d7d9444.png', '2dd68615-05d7-48f1-9467-819514c31649', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-30 13:35:15.252576+00', 1036, true, 'Duas mortes em acidente na BA-393 entre Poço Verde e Heliópolis', 'Um grave acidente na BA-393, entre Poço Verde (SE) e Heliópolis (BA), resultou na morte de duas pessoas na noite de sábado (29). Vítimas foram socorridas, mas não resistiram. As causas são investigadas.'),
  ('f64aa424-b9c8-4c7e-b8cc-b08ff4fb0412', 'Homem de Ribeira do Pombal é baleado em tentativa de furto; investiga', 'homem-de-ribeira-do-pombal-e-baleado-em-tentativa-de-furto-investiga', 'Uedson Cipriano Ferreira, suspeito de furtos em Ribeira do Pombal, foi baleado na mão ao tentar roubar fazenda; a Polícia Civil investiga o caso e possível tribunal do crime.', 'Por volta das 12h da quinta‑feira (27), Uedson Cipriano Ferreira, conhecido como “Menga”, foi alvejado na mão enquanto tentava roubar uma fazenda na estrada que dá acesso ao bairro Alto de Santo Antônio, zona leste de Ribeira do Pombal‑BA. A vítima recebeu socorro e foi encaminhada ao Hospital Geral Santa Tereza, onde recebeu tratamento pelas lesões.

O disparo foi registrado por quem atirou. No vídeo, o suspeito declara que foi ao local para cometer o roubo e que o fazendeiro o “disciplinaria”. Ele junta as mãos, recebe um único tiro e finaliza dizendo “disciplina pelo certo”. O registro traz a legenda “Se nós pega na quebrada roubando, é tiro na mão”. Uedson já possui histórico de prisões por furtos e roubos na cidade, tendo sido flagrado por câmeras de monitoramento. Recentemente, sua imagem circulou nas redes sociais após ser alvo de linchamento em Ribeira do Pombal. A Polícia Civil segue investigando o incidente e verifica possível ligação com o chamado “tribunal do crime”.', 'https://www.portalalerta.com.br/wp-content/uploads/2026/08/tribunal-do-Crime-em-Ribeira-do-Pombal-2026.jpg', '7d34292b-4217-4571-ba21-f7aa996aa1d3', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-30 14:37:53.600759+00', 132, true, 'Homem de Ribeira do Pombal é baleado em tentativa de furto; investiga', NULL),
  ('63217c5f-b7e7-4462-b349-fed2683640e2', 'Servidores da rede estadual de ensino da Bahia poderão converter licença-prêmio em dinheiro', 'servidores-da-rede-estadual-de-ensino-da-bahia-poderao-converter-licenca-premio', 'Servidores da rede estadual de ensino da Bahia já podem solicitar a conversão da licença‑prêmio acumulada em indenização pecuniária, conforme medida publicada no Diário Oficial do Estado. A ...', 'Servidores da rede estadual de ensino da Bahia já podem solicitar a conversão da licença‑prêmio acumulada em indenização pecuniária, conforme medida publicada no Diário Oficial do Estado. A iniciativa abrange profissionais de carreiras civis e cargos comissionados do magistério público do ensino médio, como diretores, coordenadores pedagógicos e técnicos. Os pedidos devem ser protocolados no Sistema Eletrônico de Informações (SEI), por meio do SAC Educação ou dos Núcleos Territoriais de Educação (NTE).  

A concessão não é automática; a Secretaria da Educação (SEC) analisará cada solicitação e emitirá decisões até o último dia de cada mês. O governo justifica a medida como forma de evitar desfalques nas salas de aula e nos setores administrativos, assegurando o cumprimento do calendário escolar. Os pagamentos obedecem às regras do Conselho de Políticas de Recursos Humanos (COPE), limitados a no máximo 10 % do total de efetivos em exercício por ano, e dependem da disponibilidade orçamentária do Estado.', 'https://cdn.atarde.com.br/img/Artigo-Destaque/1400000/servidores-da-bahia-vao-poder-converter-licenca-em0140007100202608281310.webp?xid=7188645', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-30 15:01:03.01+00', 0, false, 'Servidores da rede estadual de ensino da Bahia poderão converter licença-prêmio em dinheiro', 'Servidores da rede estadual de ensino da Bahia já podem solicitar a conversão da licença‑prêmio acumulada em indenização pecuniária, conforme medida publicada no Diário Oficial do Estado. A ...'),
  ('91748915-6c86-4c2b-b025-887b721ff492', 'Lei do Silêncio não estabelece fechamento obrigatório às 22h em todo o Brasil', 'lei-do-silencio-nao-estabelece-fechamento-obrigatorio-as-22h-em-todo-o-brasil', 'Não existe uma Lei do Silêncio nacional que obrigue bares, restaurantes, casas de shows ou eventos a encerrar suas atividades ou silenciar a música quando o relógio marca 22h. As normas vari...', 'Não existe uma Lei do Silêncio nacional que obrigue bares, restaurantes, casas de shows ou eventos a encerrar suas atividades ou silenciar a música quando o relógio marca 22h. As normas variam de acordo com o município, o zoneamento, o tipo de estabelecimento, o período do dia e os limites de ruído permitidos. Assim, um bar pode permanecer aberto após as 22h e manter a música, desde que possua autorização municipal e respeite os níveis sonoros estabelecidos para a região. Da mesma forma, casas de eventos podem operar à noite quando obtêm licenças específicas, mas continuam sujeitos a limites de decibéis, controle acústico e outras exigências técnicas.  

A simples passagem do horário não determina a legalidade da emissão de ruído; a perturbação do sossego é regulada pelo artigo 42 da Lei das Contravenções Penais, que se aplica a qualquer hora do dia. Fiscalizações consideram o nível de ruído, o zoneamento, o isolamento acústico e a localização do estabelecimento, podendo impor multas, apreensão de equipamentos ou interdição caso as normas sejam violadas, independentemente do horário.', 'https://cdn.atarde.com.br/img/Artigo-Destaque/1400000/lei-do-silencio-muda-de-vez-no-brasil-e-regra-das-0140001400202608280016.webp?xid=7188111', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-30 15:01:10.489+00', 3, false, 'Lei do Silêncio não estabelece fechamento obrigatório às 22h em todo o Brasil', 'Não existe uma Lei do Silêncio nacional que obrigue bares, restaurantes, casas de shows ou eventos a encerrar suas atividades ou silenciar a música quando o relógio marca 22h. As normas vari...'),
  ('3dd1d75d-d732-4de6-ae7d-e6f834676594', 'DITEN 35 anos, uma história de Ribeira do Pombal que conquistou a região', 'diten-35-anos-uma-historia-de-ribeira-do-pombal-que-conquistou-a-regiao', 'É uma família que representa uma característica cada vez mais marcante de Ribeira do Pombal. ', '
Há 35 anos, os irmãos da família Neves começavam, em Ribeira do Pombal, uma história que se transformaria em uma das principais redes de eletrodomésticos do Nordeste da Bahia.

DITEN significa Distribuidora de Eletro Eletrônica Neves. A empresa começou com consórcios de antenas parabólicas, videocassetes e aparelhos de fax. Depois, veio a primeira loja de eletrodomésticos e a consolidação no segmento de linha branca.

A história empreendedora da família, porém, começou antes. Dona Lourinha, matriarca dos Neves, já tinha uma trajetória marcada pelos negócios e ajudou a formar uma família que seguiu pelo caminho do empreendedorismo.

Além da DITEN, outros filhos também construíram seus próprios negócios, como Ivânia Neves, da Calçados & Cia, José Carlos, o Dindinho Neves, do Supermercado Neves, e Selma Neves, da ALYS Calçados.

É uma família que representa uma característica cada vez mais marcante de Ribeira do Pombal, empresas que nascem na cidade, crescem a partir dela e conquistam espaço em toda a região.

Hoje, a DITEN possui 15 filiais espalhadas pelo Nordeste da Bahia. Uma empresa familiar, sólida, que gera empregos, valoriza seus colaboradores e conquistou a confiança de milhares de consumidores.

Também fez história na publicidade regional, chegando a ser um dos maiores anunciantes do rádio do Nordeste baiano.

DITEN, 35 anos. Uma história que nasceu em Ribeira do Pombal e ganhou a região.', 'https://mkbnqyhvaozqfpmcyoyw.supabase.co/storage/v1/object/public/imagens/noticias/1788114021733_jxco0cw.webp', '7d34292b-4217-4571-ba21-f7aa996aa1d3', NULL, '2026-08-30 18:21:40.718+00', 3282, true, '', ''),
  ('fefa0ae0-c4e4-4e5f-aa82-bdef657a0ca7', 'Universidade Federal do Portal do Sertão tem nome definido após votação', 'universidade-federal-do-portal-do-sertao-tem-nome-definido-apos-votacao', 'A nova universidade federal que terá sede em Feira de Santana, segunda maior cidade da Bahia, recebeu o nome de Universidade Federal do Portal do Sertão (UFPS). O nome foi escolhido por meio...', 'A nova universidade federal que terá sede em Feira de Santana, segunda maior cidade da Bahia, recebeu o nome de Universidade Federal do Portal do Sertão (UFPS). O nome foi escolhido por meio de uma votação nas redes sociais, realizada entre 12 e 18 de agosto, que contou com a participação de 2.647 pessoas. A opção UFPS obteve 66% dos votos, superando a Universidade Federal do Sertão da Bahia (Ufesba), que ficou em segundo lugar com 25%, e a Universidade Federal de Inovação da Bahia (Ufib), que recebeu 9% dos votos.

A escolha do nome “Portal do Sertão” foi justificada pela posição estratégica de Feira de Santana como cidade‑polo, capaz de conectar diferentes territórios baianos. Segundo a publicação oficial, a UFPS deverá atuar nas áreas de ensino, pesquisa, extensão e inovação, contribuindo para o desenvolvimento regional e alcançando regiões como a Bacia do Jacuípe e o Sisal. Até o momento, não foram divulgadas a data de inauguração nem o endereço da futura sede.', 'https://midias.correio24horas.com.br/2026/08/21/feira-de-santana-3387374-article.webp', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-30 21:18:44.316+00', 0, false, 'Universidade Federal do Portal do Sertão tem nome definido após votação', 'A nova universidade federal que terá sede em Feira de Santana, segunda maior cidade da Bahia, recebeu o nome de Universidade Federal do Portal do Sertão (UFPS). O nome foi escolhido por meio...'),
  ('bd92b6ef-0663-4858-ad82-6c3114f7a043', 'TRILHEIROS DE JUAZEIRO QUE PARTICIPAVAM DO TRILHÃO DE BANZAÊ SOFREM ACIDENTE NA BR-410', 'trilheiros-de-juazeiro-que-participavam-do-trilhao-de-banzae-sofrem-acidente-na-br-410', 'ultrapassagem em local proibido. O motorista do caminhão teria tentado desviar para evitar a colisão, mas os veículos acabaram batendo de frente. Com a força do impacto, o caminhão tombou.
', '
Um acidente envolvendo um caminhão e um veículo de passeio que transportava um reboque com motocicletas de cross foi registrado no início da noite deste domingo (30), na BR-410, na chegada de Ribeira do Pombal, nas proximidades de um motel.

Segundo informações divulgadas, o veículo de passeio teria realizado uma ultrapassagem em local proibido. O motorista do caminhão teria tentado desviar para evitar a colisão, mas os veículos acabaram batendo de frente. Com a força do impacto, o caminhão tombou.

As vítimas são trilheiros de Juazeiro, na Bahia, que participavam do Trilhão de Banzaê. Eles foram socorridos e encaminhados para o Hospital Geral Santa Tereza, em Ribeira do Pombal. Equipes de atendimento e da Polícia Rodoviária Federal estiveram no local.

Graças a Deus, todos os trilheiros estão fora de perigo. As circunstâncias do acidente deverão ser apuradas pelas autoridades.', 'https://mkbnqyhvaozqfpmcyoyw.supabase.co/storage/v1/object/public/imagens/noticias/1788132700621_kwdwt5g.webp', '7d34292b-4217-4571-ba21-f7aa996aa1d3', NULL, '2026-08-30 23:35:29.912+00', 2612, true, '', ''),
  ('d3918974-534f-448b-844e-7963c0ae0424', 'Ricardo Maia anuncia licitação para asfalto entre Ribeira do Pombal e povoado Poço para setembro', 'ricardo-maia-anuncia-licitacao-para-asfalto-entre-ribeira-do-pombal-e-povoado-poco-para-setembro', '
Um ato político convocado pelo prefeito Erickson Silva movimentou a zona rural de Ribeira do Pombal neste domingo (30). Uma carreata percorreu os povoados Barra Vermelha, Poço e ', '
Deputado federal afirmou, durante ato político realizado neste domingo, que os recursos já estão alocados e que projeto encaminhado pela Prefeitura aguarda análise da Caixa Econômica Federal

Um ato político convocado pelo prefeito Erickson Silva movimentou a zona rural de Ribeira do Pombal neste domingo (30). Uma carreata percorreu os povoados Barra Vermelha, Poço e Veríssimo, reunindo lideranças políticas e apoiadores.

Durante o ato, o deputado federal Ricardo Maia, que concorre à reeleição, anunciou uma previsão para o início de uma das obras mais aguardadas pelos moradores da região: a pavimentação asfáltica da estrada que liga a sede de Ribeira do Pombal ao povoado Poço.

Em seu discurso, Ricardo Maia afirmou que a licitação para a obra deverá ser realizada já no mês de setembro. Segundo o deputado, os recursos necessários para a intervenção já estão alocados.

Ainda de acordo com Maia, o projeto elaborado pela Prefeitura de Ribeira do Pombal já foi encaminhado à Caixa Econômica Federal e, neste momento, aguarda as etapas de análise e aprovação necessárias para que o processo licitatório seja divulgado.

Após a conclusão dessas etapas, a expectativa é de que seja realizada a licitação e, posteriormente, iniciada a execução da obra.

A pavimentação do trecho entre a sede e o povoado Poço é uma antiga reivindicação dos moradores da região e deverá melhorar as condições de deslocamento, especialmente para quem utiliza diariamente a estrada para acessar Ribeira do Pombal.

O anúncio feito pelo deputado durante a carreata coloca setembro como um mês decisivo para o avanço do projeto, caso sejam cumpridas as etapas previstas junto à Caixa Econômica Federal.', 'https://mkbnqyhvaozqfpmcyoyw.supabase.co/storage/v1/object/public/imagens/noticias/1788133182637_7rjjtzw.webp', '7d34292b-4217-4571-ba21-f7aa996aa1d3', NULL, '2026-08-30 23:40:24.083+00', 5303, true, '', ''),
  ('3045faaf-433e-40e2-8124-c29094a48951', 'Câmara aprova estado civil "convivente" e altera regras para união estável', 'camara-aprova-estado-civil-convivente-e-altera-regras-para-uniao-estavel', 'A Câmara dos Deputados aprovou uma proposta que cria o estado civil de "convivente" para pessoas que vivem em união estável registrada em cartório. A medida visa diferenciar formalmente essa...', 'A Câmara dos Deputados aprovou uma proposta que cria o estado civil de "convivente" para pessoas que vivem em união estável registrada em cartório. A medida visa diferenciar formalmente essa situação do estado civil de solteiro(a) em formulários e documentos. O Projeto de Lei 1779/2003, que agora segue para votação no Senado, busca oficializar o reconhecimento da união estável com um status civil próprio.

O texto aprovado confirma que a união estável adota o regime de comunhão parcial de bens por padrão. Contudo, a proposta estabelece que a separação total de bens será obrigatória em situações similares às já previstas para o casamento. Isso inclui casais onde um dos parceiros é divorciado ou viúvo e ainda não realizou a partilha de bens do relacionamento anterior, pessoas com 70 anos ou mais, e jovens entre 16 e 18 anos que necessitam de autorização judicial para se unir. Além disso, o projeto permite que casais de união estável estabeleçam a separação total de bens por meio de contratos escritos ou pré-nupciais, garantindo que o patrimônio adquirido durante a união não será dividido em caso de término.', 'https://imagemlink.cleissoncardoso.com/uploads/fd9cb5db-80ad-49f4-896d-832fb28de843.png', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-31 00:16:54.548+00', 3, false, 'Câmara aprova estado civil "convivente" e altera regras para união estável', 'A Câmara dos Deputados aprovou uma proposta que cria o estado civil de "convivente" para pessoas que vivem em união estável registrada em cartório. A medida visa diferenciar formalmente essa...'),
  ('86f139f5-2b50-4c5b-ae25-27dce49656f6', 'Ribeira do Pombal inaugura APAE e amplia rede de apoio a pessoas com deficiência', 'ribeira-do-pombal-inaugura-apae-e-amplia-rede-de-apoio-a-pessoas-com-deficiencia', 'A APAE de Ribeira do Pombal foi inaugurada oficialmente na manhã desta segunda-feira (31). A solenidade contou com a presença da presidente da Federação das APAEs da Bahia, Moema Meira. O município passa a contar com a 87ª unidade da entidade no estado.', '
Ribeira do Pombal ganhou nesta segunda-feira (31) sua própria unidade da APAE. A inauguração aconteceu em cerimônia marcada por emoção e celebração da inclusão social no município.

O evento contou com a presença da presidente da Federação das APAEs da Bahia, Moema Meira, que destacou a importância da nova unidade para a região. Com a implantação, Ribeira do Pombal passa a integrar a rede estadual como a 87ª APAE em atividade na Bahia.

A federação reúne unidades em diversos municípios baianos, oferecendo suporte técnico e institucional às associações locais. A chegada da entidade a Ribeira do Pombal amplia o acesso a serviços especializados que antes exigiam deslocamento a outras cidades.

Para as famílias do município, a novidade representa mais proximidade no atendimento. A expectativa é que a unidade comece a oferecer, em breve, programas de apoio, acompanhamento e assistência às pessoas com deficiência.

', 'https://mkbnqyhvaozqfpmcyoyw.supabase.co/storage/v1/object/public/imagens/noticias/1788188849993_k63w49h.webp', '7d34292b-4217-4571-ba21-f7aa996aa1d3', NULL, '2026-08-31 15:09:01.47+00', 2615, true, ' APAE é inaugurada em Ribeira do Pombal nesta segunda', 'Ribeira do Pombal inaugura a APAE nesta segunda (31), tornando-se a 87ª unidade da Federação das APAEs da Bahia.'),
  ('a8ed346d-d7cf-44cb-8225-aee13883b02f', 'Luto de 3 dias na Bahia após afogamento de 4 crianças em Paramirim', 'luto-de-3-dias-na-bahia-apos-afogamento-de-4-criancas-em-paramirim', 'No domingo, 30, uma pequena embarcação virou na lagoa da comunidade de Salina Branca, em Paramirim, Bahia, resultando na morte de quatro crianças – Diego, Jeferson, José e Lorenzo. Os corpos...', 'No domingo, 30, uma pequena embarcação virou na lagoa da comunidade de Salina Branca, em Paramirim, Bahia, resultando na morte de quatro crianças – Diego, Jeferson, José e Lorenzo. Os corpos foram localizados e recuperados durante as buscas realizadas pelo Corpo de Bombeiros Militar da Bahia.  

O resgate foi coordenado pelo Núcleo de Operações Aquáticas (NOA) do 7º Batalhão, com sede em Vitória da Conquista, que atuou durante toda a madrugada de 31. A primeira vítima foi encontrada no primeiro mergulho, duas outras no segundo e a quarta por volta de 1h30, após um terceiro mergulho, enfrentando profundidade de cerca de cinco metros, água escura e galhos submersos. Os corpos foram encaminhados ao Departamento de Polícia Técnica para os procedimentos legais. Policiais da 46ª Companhia Independente da Polícia Militar e da Delegacia Territorial de Paramirim apoiaram as operações, e a investigação segue em curso. O governador Jerônimo Rodrigues lamentou a perda nas redes sociais, solidarizou‑se com as famílias e decretou luto oficial de três dias em todo o estado, com bandeiras a meio‑mastro. As autoridades continuam coletando depoimentos para esclarecer as circunstâncias da capotagem.', 'https://cdn.atarde.com.br/img/Artigo-Destaque/1400000/jeronimo-decreta-luto-de-3-dias-na-bahia-apos-mort0140035300202608311531.jpg?xid=7191480', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-08-31 22:12:53.426+00', 1, false, 'Luto de 3 dias na Bahia após afogamento de 4 crianças em Paramirim', 'No domingo, 30, uma pequena embarcação virou na lagoa da comunidade de Salina Branca, em Paramirim, Bahia, resultando na morte de quatro crianças – Diego, Jeferson, José e Lorenzo. Os corpos...'),
  ('be51d911-069e-4854-9e4f-a3c028e704e8', 'Câmara de Ribeira do Amparo convoca vereadores para eleição da Mesa Diretora para 2027 e 2028', 'camara-de-ribeira-do-amparo-convoca-vereadores-para-eleicao-da-mesa-diretora-para-2027-e-2028', 'A Câmara Municipal de Ribeira do Amparo realiza nesta terça-feira, 1º de setembro, a eleição da Mesa Diretora que comandará o Legislativo durante o biênio 2027/2028.
', 'A Câmara Municipal de Ribeira do Amparo publicou nesta segunda-feira (31) o Edital de Convocação nº 001/2026, que estabelece as regras para a eleição da nova Mesa Diretora da Casa Legislativa para o biênio 2027/2028.

A eleição está marcada para esta terça-feira, 1º de setembro de 2026, às 17h, durante Sessão Plenária na sede da Câmara Municipal. Conforme o edital, a sessão terá como finalidade específica a escolha dos vereadores que irão integrar a Mesa Diretora no próximo período.

Os vereadores interessados em disputar os cargos deverão atender aos requisitos previstos na legislação e no Regimento Interno da Câmara. As chapas deverão ser inscritas junto à Secretaria da Casa até as 16h do próprio dia 1º de setembro, por meio de requerimento dirigido à Presidência.

Votação seguirá Regimento Interno

A escolha dos integrantes da Mesa Diretora será realizada por votação dos vereadores, seguindo os procedimentos estabelecidos pelo Regimento Interno da Câmara Municipal.

Serão considerados eleitos os candidatos que alcançarem a maioria exigida pelas normas regimentais para cada cargo.

A Mesa Diretora possui papel central no funcionamento do Legislativo municipal, sendo responsável pela condução dos trabalhos da Câmara e pela organização das atividades administrativas e parlamentares da Casa.

Mandato começa em janeiro de 2027

Os vereadores escolhidos para compor a nova Mesa Diretora tomarão posse automaticamente em 1º de janeiro de 2027. O mandato terá duração de dois anos, com encerramento previsto para 31 de dezembro de 2028.

O Edital de Convocação nº 001/2026 é assinado pelo presidente da Câmara Municipal de Ribeira do Amparo, Antônio Jorge Cerqueira, juntamente com os demais integrantes da atual Mesa Diretora.

A publicação consta no Diário Oficial da Câmara, edição nº 074, de 31 de agosto de 2026.




', 'https://mkbnqyhvaozqfpmcyoyw.supabase.co/storage/v1/object/public/imagens/noticias/1788217541391_jxk0iub.webp', '6b283438-a9a3-4742-8705-7cfed6acfd49', NULL, '2026-08-31 23:05:51.104+00', 23, true, 'Câmara de Ribeira do Amparo terá eleição da Mesa Diretora', 'Câmara de Ribeira do Amparo realiza nesta terça-feira (1º) eleição da Mesa Diretora para o biênio 2027/2028, conforme edital publicado.'),
  ('0e0ae6a1-14a0-4d63-aa58-bb6e87e7e3fd', 'Pesquisa Atlas/Bloomberg aponta Lula na liderança após debates e sabatinas', 'pesquisa-atlas-bloomberg-aponta-lula-na-lideranca-apos-debates-e-sabatinas', 'O presidente Luiz Inácio Lula da Silva (PT) mantém a liderança em todos os cenários eleitorais de primeiro e segundo turno, segundo pesquisa Atlas/Bloomberg divulgada na segunda-feira, 31. O...', 'O presidente Luiz Inácio Lula da Silva (PT) mantém a liderança em todos os cenários eleitorais de primeiro e segundo turno, segundo pesquisa Atlas/Bloomberg divulgada na segunda-feira, 31. O levantamento ouviu 5.014 brasileiros entre os dias 25 e 30 de agosto, período que incluiu o primeiro debate da Band e as primeiras sabatinas da TV Globo. A margem de erro é de um ponto percentual, com nível de confiança de 95%.

No primeiro turno, Lula lidera com quase dez pontos de vantagem sobre o segundo colocado, o senador Flávio Bolsonaro (PL-RJ). O escritor Augusto Cury (Avante) aparece em terceiro lugar, registrando crescimento de quase cinco pontos em relação à pesquisa de julho, passando de 3% para 7,8%. Enquanto Lula segue em trajetória de queda desde junho, Flávio também apresenta uma leve redução desde abril. No segundo turno, o petista lidera todas as simulações, inclusive contra o ex-presidente Jair Bolsonaro. Sobre rejeição, Flávio e Lula empatam com os maiores índices, enquanto Cury possui a menor rejeição.', 'https://veja.abril.com.br/wp-content/uploads/2025/12/Flavio-Bolsonaro-2-1.jpg?quality=70&strip=info&resize=1080,565&crop=1', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-01 00:04:49.553+00', 2, false, 'Pesquisa Atlas/Bloomberg aponta Lula na liderança após debates e sabatinas', 'O presidente Luiz Inácio Lula da Silva (PT) mantém a liderança em todos os cenários eleitorais de primeiro e segundo turno, segundo pesquisa Atlas/Bloomberg divulgada na segunda-feira, 31. O...'),
  ('25abf5af-44a5-45c4-912d-431a0ac77df1', 'Raio da Silibrina lamenta morte de Rogério Valença, nome ligado à história do forró eletrônico', 'raio-da-silibrina-lamenta-morte-de-rogerio-valenca-nome-ligado-a-historia-do-forro-eletronico', 'Músico integrou a banda aracajuana, pioneira do gênero, e é lembrado por apresentações históricas em Ribeira do Pombal
', 'A banda Raio da Silibrina, de Aracaju, lamentou nas redes sociais a morte de Rogério Valença, integrante que fez parte da trajetória do grupo durante muitos anos. A homenagem foi publicada no perfil oficial da banda, que classificou o músico como “alguém muito especial” e destacou a importância de sua presença na história do conjunto.

Pioneira do forró eletrônico, a Raio da Silibrina construiu uma trajetória de destaque no cenário musical nordestino antes mesmo da consolidação de grupos como a Calcinha Preta. O grupo aracajuano ajudou a formar o público e a linguagem de uma geração do gênero, alcançando cidades de diferentes estados e deixando sucessos marcantes por onde passou.

Em Ribeira do Pombal, no interior da Bahia, a banda protagonizou apresentações que permanecem na memória do público. Entre os momentos lembrados estão os shows no Fisgueira Clube e participações na tradicional Festa de Outubro, eventos que reuniram fãs e ajudaram a transformar as passagens do grupo pela cidade em referências da vida cultural local.

A publicação de despedida foi acompanhada da palavra “LUTO” e de uma imagem em preto e branco. Na legenda, a banda afirmou ter recebido com profunda tristeza a notícia do falecimento de Rogério e ressaltou a saudade, as lembranças dos momentos vividos e a gratidão por tudo o que ele representou.

“Rogério, sua história e sua presença jamais serão esquecidas. Descanse em paz”, diz um trecho da homenagem publicada pela Raio da Silibrina.

A morte de Rogério Valença repercute entre os músicos e admiradores que acompanharam a história da Raio da Silibrina em Aracaju e também entre o público das cidades onde a banda se apresentou ao longo da carreira.

A banda também manifestou solidariedade à família, aos amigos e a todos os que sentem a perda. “Que Deus conforte o coração de toda a família, amigos e de todos que estão sentindo essa perda”, diz a mensagem publicada no perfil oficial.

Até a publicação desta matéria, o post consultado não informava a causa da morte, a idade de Rogério nem detalhes sobre velório e sepultamento. ', 'https://mkbnqyhvaozqfpmcyoyw.supabase.co/storage/v1/object/public/imagens/noticias/1788225918800_oybnqw2.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', NULL, '2026-09-01 01:27:46.072+00', 20, false, 'Raio da Silibrina lamenta morte de Rogério Valença, nome ligado à hist', 'Músico integrou a banda aracajuana, pioneira do gênero, e é lembrado por apresentações históricas em Ribeira do Pombal
'),
  ('81150d46-1e21-4f29-ac81-0e96ad042800', 'Coaf registra novo repasse de Vorcaro para Dark Horse após Flávio Bolsonaro dizer que relação acabou', 'coaf-registra-novo-repasse-de-vorcaro-para-dark-horse-apos-flavio-bolsonaro-dize', 'Um relatório do Conselho de Controle de Atividades Financeiras (Coaf) revela que o banqueiro Daniel Vorcaro realizou um novo repasse de US$ 1,66 milhão para o projeto da cinebiografia de Jai...', 'Um relatório do Conselho de Controle de Atividades Financeiras (Coaf) revela que o banqueiro Daniel Vorcaro realizou um novo repasse de US$ 1,66 milhão para o projeto da cinebiografia de Jair Bolsonaro em setembro de 2025. A transferência ocorreu quatro meses após o senador Flávio Bolsonaro afirmar publicamente que os pagamentos haviam cessado em maio do mesmo ano, contradizendo a versão apresentada pelo parlamentar.

Com esse envio, o total identificado de recursos repassados por Vorcaro ao Havengate Development Fund, fundo controlado por Eduardo Bolsonaro, chegou a US$ 12,3 milhões. Documentos e mensagens de WhatsApp obtidos pela imprensa indicam que a relação financeira continuou ativa mesmo após o surgimento de suspeitas envolvendo o Banco Master. Além do valor confirmado pelo Coaf, há indícios de um possível oitavo pagamento mencionado em conversas de outubro, o que elevaria o montante total para cerca de US$ 14 milhões. As investigações buscam esclarecer o trajeto dos recursos, que passavam pelo doleiro Antonio Freixo Junior antes de chegar ao fundo.', 'https://revistaforum.com.br/wp-content/uploads/2026/07/flavio-bolsonaro-e-seu-irmao-daniel-vorcaro-1778727319153_v2_900x506-960x540-1.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-01 12:24:01.511+00', 5, false, 'Coaf registra novo repasse de Vorcaro para Dark Horse após Flávio Bolsonaro dizer que relação acabou', 'Um relatório do Conselho de Controle de Atividades Financeiras (Coaf) revela que o banqueiro Daniel Vorcaro realizou um novo repasse de US$ 1,66 milhão para o projeto da cinebiografia de Jai...'),
  ('da8c99f3-94dc-4fdb-90a1-4c499e1c47df', 'Governo Federal edita decreto para combater cambismo digital e exigir água gratuita em eventos', 'governo-federal-edita-decreto-para-combater-cambismo-digital-e-exigir-agua-gratu', 'O Governo Federal publicou uma série de decretos para regulamentar a venda e a transferência de ingressos de shows e eventos pela internet, com o objetivo principal de combater o cambismo di...', 'O Governo Federal publicou uma série de decretos para regulamentar a venda e a transferência de ingressos de shows e eventos pela internet, com o objetivo principal de combater o cambismo digital. As medidas atendem a uma reivindicação histórica de fãs e artistas e entram em vigor 30 dias após a publicação oficial. A regulamentação determina que as filas virtuais de compra exibam a posição do consumidor, o número estimado de pessoas à frente e o tempo de espera estimado.

Além da transparência nas filas, as novas regras exigem que valores e taxas adicionais sejam apresentados de forma clara e visível em todas as etapas da compra, sendo consideradas abusivas cobranças duplicadas que não correspondam a serviços efetivamente prestados. O consumidor também terá assegurado o direito de arrependimento, previsto no Código de Defesa do Consumidor, e poderá optar por reembolso integral, crédito ou nova data em caso de cancelamento ou alteração relevante do evento. A legislação também autoriza o público a levar garrafas de água, respeitando os critérios de segurança definidos pelos organizadores.', 'https://www.bahianoticias.com.br/fotos/holofote_noticias/85489/IMAGEM_NOTICIA_9.jpg?checksum=1788259609', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-01 12:28:10.564+00', 4, false, 'Governo Federal edita decreto para combater cambismo digital e exigir água gratuita em eventos', 'O Governo Federal publicou uma série de decretos para regulamentar a venda e a transferência de ingressos de shows e eventos pela internet, com o objetivo principal de combater o cambismo di...'),
  ('ea9f8867-df96-411f-81d0-1c53df6b7838', 'Governo Federal regulamenta venda de ingressos online e exige água gratuita em eventos', 'governo-federal-regulamenta-venda-de-ingressos-online-e-exige-agua-gratuita-em-e', 'O Governo Federal publicou uma série de medidas que regulamentam a venda e a transferência de ingressos pela internet para shows e eventos, com o objetivo de combater o cambismo digital. As ...', 'O Governo Federal publicou uma série de medidas que regulamentam a venda e a transferência de ingressos pela internet para shows e eventos, com o objetivo de combater o cambismo digital. As novas regras, apresentadas no Palácio do Planalto, determinam que as filas virtuais de compra de ingressos exibam a posição do consumidor, o número estimado de pessoas à frente e o tempo de espera previsto. As normas entram em vigor 30 dias após a publicação dos decretos e atendem a uma reivindicação antiga de fãs de artistas internacionais e nacionais.

Além da transparência nas plataformas digitais, os decretos exigem clareza na composição dos preços, obrigando a exibição clara de valores e taxas adicionais em todas as etapas da compra. Cobranças duplicadas ou que não correspondam a serviços efetivamente prestados são consideradas abusivas. O público também assegura o direito de arrependimento previsto no Código de Defesa do Consumidor. Em casos de cancelamento ou alteração relevante do evento, o consumidor pode optar por nova data, crédito para uso futuro ou reembolso integral. Outra medida importante é a permissão para que o público leve garrafas de água próprias, respeitando critérios de segurança definidos pelos organizadores.', 'https://www.bahianoticias.com.br/fotos/holofote_noticias/85489/IMAGEM_NOTICIA_9.jpg?checksum=1788259609', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-01 12:28:16.85+00', 4, false, 'Governo Federal regulamenta venda de ingressos online e exige água gratuita em eventos', 'O Governo Federal publicou uma série de medidas que regulamentam a venda e a transferência de ingressos pela internet para shows e eventos, com o objetivo de combater o cambismo digital. As ...'),
  ('7e07608e-3f51-41e0-81d9-c472bbbe64ac', 'Ministro afirma que Trump orientou busca por acordo comercial com Brasil', 'ministro-afirma-que-trump-orientou-busca-por-acordo-comercial-com-brasil', 'O chanceler Mauro Vieira, ministro das Relações Exteriores, declarou nesta terça-feira que a negociação comercial entre o Brasil e os Estados Unidos encontra-se em um novo cenário. Segundo o...', 'O chanceler Mauro Vieira, ministro das Relações Exteriores, declarou nesta terça-feira que a negociação comercial entre o Brasil e os Estados Unidos encontra-se em um novo cenário. Segundo o titular do Itamaraty, o presidente americano, Donald Trump, teria orientado a equipe de governo a buscar um acordo com o país sul-americano.

A declaração foi feita no contexto de um encontro que marcou a reabertura das tratativas bilaterais, interrompidas após a imposição de novas tarifas de importação pelos EUA em julho. Vieira participou da reunião que retomou o diálogo diplomático entre as duas nações, buscando destravar a relação econômica e evitar um aprofundamento da disputa comercial que afetou setores estratégicos da economia brasileira.

A posição americana sinaliza uma mudança de postura em relação às barreiras tarifárias, abrindo espaço para novas rodadas de conversas técnicas e diplomáticas. O governo brasileiro acompanha de perto as diretrizes emitidas por Washington e trabalha para consolidar um entendimento que beneficie as exportações nacionais e a estabilidade do mercado interno.', 'https://www.bahianoticias.com.br/fotos/folha_noticias/406981/IMAGEM_NOTICIA_9.jpg?checksum=1788254667', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-01 12:28:47.521+00', 4, false, 'Ministro afirma que Trump orientou busca por acordo comercial com Brasil', 'O chanceler Mauro Vieira, ministro das Relações Exteriores, declarou nesta terça-feira que a negociação comercial entre o Brasil e os Estados Unidos encontra-se em um novo cenário. Segundo o...'),
  ('cebf67b2-c6af-4039-8792-e01913a84838', 'Mais da metade dos usuários de IA no Brasil busca suporte emocional, mas 66% se preocupa com dados', 'mais-da-metade-dos-usuarios-de-ia-no-brasil-busca-suporte-emocional-mas-66-se-pr', 'Uma pesquisa recente revelou que mais da metade dos usuários brasileiros de Inteligência Artificial (IA) recorre a essas ferramentas como suporte emocional. Paralelamente a essa busca por ap...', 'Uma pesquisa recente revelou que mais da metade dos usuários brasileiros de Inteligência Artificial (IA) recorre a essas ferramentas como suporte emocional. Paralelamente a essa busca por apoio, um levantamento sobre a percepção dos usuários aponta para uma preocupação significativa com a segurança de dados pessoais.

De acordo com a pesquisa, a maioria, ou seja, 66% dos usuários, declara estar preocupada ou muito preocupada com a forma como suas informações são utilizadas pelas empresas desenvolvedoras de IA. Em contraste, 22% dos entrevistados expressaram pouca preocupação, enquanto uma parcela menor, de 11%, afirmou não estar preocupada com o uso de seus dados pessoais pelas ferramentas de Inteligência Artificial.', 'https://www.bahianoticias.com.br/fotos/principal_noticias/320578/IMAGEM_NOTICIA_9.jpg?checksum=1788201844', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-01 12:29:00.465+00', 1, false, 'Mais da metade dos usuários de IA no Brasil busca suporte emocional, mas 66% se preocupa com dados', 'Uma pesquisa recente revelou que mais da metade dos usuários brasileiros de Inteligência Artificial (IA) recorre a essas ferramentas como suporte emocional. Paralelamente a essa busca por ap...'),
  ('938aa774-1f8f-4208-a59d-5ccf982a894a', 'Pesquisa aponta Lula com 38% e Flávio Bolsonaro com 30% no primeiro turno', 'pesquisa-aponta-lula-com-38-e-flavio-bolsonaro-com-30-no-primeiro-turno', 'Pesquisa da Real Time Big Data, divulgada nesta terça-feira, 1º, indica que o presidente Luiz Inácio Lula da Silva (PT) lidera as intenções de voto no primeiro turno da disputa presidencial ...', 'Pesquisa da Real Time Big Data, divulgada nesta terça-feira, 1º, indica que o presidente Luiz Inácio Lula da Silva (PT) lidera as intenções de voto no primeiro turno da disputa presidencial com 38%. Flávio Bolsonaro (PL) aparece em seguida, com 30% das citações, enquanto Augusto Cury (Avante) registra 11%. Os demais candidatos somam 15%, entre brancos, nulos e indecisos. O cenário estimulado não inclui Pablo Marçal (PRTB).

Em simulação de segundo turno entre Lula e Flávio Bolsonaro, os dois candidatos estão empatados tecnicamente, ambos com 44% das intenções de voto. Em julho, a vantagem era de 3 pontos para o petista. Nos confrontos com outros presidenciáveis, Lula apresenta empate técnico com Ronaldo Caiado (PSD), que teria 45% contra 43% do presidente. Contra Romeu Zema (Novo), Lula tem 43% e o adversário, 40%. A pesquisa ouviu 2.000 eleitores em todo o país entre 27 e 31 de agosto, com margem de erro de dois pontos percentuais e nível de confiança de 95%. O levantamento está registrado no TSE sob o número BR-03490/2026.', 'https://media-manager.noticiasaominuto.com.br/960/naom_6a96b5a1ae518.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-01 12:41:41.169+00', 2, false, 'Pesquisa aponta Lula com 38% e Flávio Bolsonaro com 30% no primeiro turno', 'Pesquisa da Real Time Big Data, divulgada nesta terça-feira, 1º, indica que o presidente Luiz Inácio Lula da Silva (PT) lidera as intenções de voto no primeiro turno da disputa presidencial ...'),
  ('dd76a9c7-cf01-4cc6-8907-a84401cc540b', 'Golpe do Pix de R$ 0,01 não invade conta, alerta BC e especialistas', 'golpe-do-pix-de-r-0-01-nao-invade-conta-alerta-bc-e-especialistas', 'Mensagens alertando sobre o chamado golpe do Pix de R$ 0,01 voltaram a circular em massa nas redes sociais e aplicativos de conversa, afirmando falsamente que a microtransferência permite a ...', 'Mensagens alertando sobre o chamado golpe do Pix de R$ 0,01 voltaram a circular em massa nas redes sociais e aplicativos de conversa, afirmando falsamente que a microtransferência permite a invasão de celulares ou o roubo de dados bancários. O Banco Central (BC) e a Federação Brasileira de Bancos (Febraban) confirmam que a transação não fornece acesso a sistemas bancários. Especialistas em cibersegurança ressaltam que o perigo real reside no contato telefônico posterior, onde golpistas utilizam a movimentação como pretexto para aplicar engenharia social e solicitar dados sensíveis.

O envio de valores irrisórios serve para validar chaves ativas e criar lançamentos reais nos extratos, facilitando a credibilidade dos criminosos ao se passarem por funcionários de instituições financeiras. O risco aumenta quando essas informações são cruzadas com vazamentos de dados e redes sociais. O BC orienta os clientes a nunca aceitar pedidos de estorno por chaves alternativas enviadas em mensagens ou ligações, utilizando apenas o botão nativo de devolução no aplicativo oficial do banco. Em caso de suspeita, a recomendação é registrar boletim de ocorrência imediatamente e utilizar o Mecanismo Especial de Devolução, que permite o bloqueio cautelar de valores em contas intermediárias por até 11 dias.', 'https://tm.ibxk.com.br/2026/09/01/Chat_GPT_Image_31_de_ago_de_2026_21_54_04_6d50169a95.png?ims=1600x900/filters:format(jpg)', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-01 12:42:29.303+00', 5, false, 'Golpe do Pix de R$ 0,01 não invade conta, alerta BC e especialistas', 'Mensagens alertando sobre o chamado golpe do Pix de R$ 0,01 voltaram a circular em massa nas redes sociais e aplicativos de conversa, afirmando falsamente que a microtransferência permite a ...'),
  ('da6725dc-0ac7-4e6b-9296-dce7fa5981e1', 'Advogado questiona antecipação da eleição da Câmara de Ribeira do Amparo', 'advogado-questiona-antecipacao-da-eleicao-da-camara-de-ribeira-do-amparo', 'Em decisões recentes, o Supremo chegou a determinar a anulação ou suspensão de eleições antecipadas realizadas fora desse parâmetro.', 'O advogado Alexandre Brito Luz questionou a antecipação da eleição da Mesa Diretora da Câmara Municipal de Ribeira do Amparo para o biênio 2027/2028.

Em comentário nas redes sociais, o advogado, que também atua como procurador da Câmara Municipal de Ribeira do Pombal, afirmou que a realização do pleito antes de outubro de 2026 estaria em desacordo com o entendimento consolidado pelo Supremo Tribunal Federal (STF).

Segundo Alexandre,

<blockquote> Regimento Interno da Câmara deveria ser adequado e uma eventual eleição realizada antes desse período poderia ser questionada judicialmente.</blockquote>

A Câmara Municipal ainda poderá se manifestar sobre o questionamento e, eventualmente, esclarecer os fundamentos jurídicos utilizados para definir a data da eleição.

A eleição da Mesa Diretora para o biênio 2027/2028 é responsável por definir a composição que comandará o Legislativo municipal durante os dois anos seguintes, incluindo os cargos de presidente, vice-presidente e secretários, conforme as regras previstas na legislação e no Regimento Interno da Casa.

O caso pode ganhar novos capítulos caso o questionamento seja levado formalmente ao Poder Judiciário.
', 'https://mkbnqyhvaozqfpmcyoyw.supabase.co/storage/v1/object/public/imagens/noticias/1788270241812_p7z0qvt.webp', '6b283438-a9a3-4742-8705-7cfed6acfd49', NULL, '2026-09-01 13:47:14.283+00', 5908, true, '', ''),
  ('89af3659-ac9c-4050-a101-c01281654c5b', 'Banco Central amplia prazo para contestação de Pix e mantém limites para dispositivos não cadastrados', 'banco-central-amplia-prazo-para-contestacao-de-pix-e-mantem-limites-para-disposi', 'O sistema de pagamentos instantâneos do Brasil passa por uma atualização significativa a partir desta terça-feira, 1º de setembro. Uma nova regra estabelecida pelo Banco Central (BC) entrou ...', 'O sistema de pagamentos instantâneos do Brasil passa por uma atualização significativa a partir desta terça-feira, 1º de setembro. Uma nova regra estabelecida pelo Banco Central (BC) entrou em vigor com o objetivo de aprimorar os mecanismos de segurança e ajustar os procedimentos operacionais entre as instituições financeiras. A alteração visa sanar brechas operacionais e oferecer um ambiente mais equilibrado tanto para os consumidores quanto para os estabelecimentos comerciais. Diante do crescimento constante das movimentações financeiras, o órgão regulador tem ajustado as diretrizes do sistema para acompanhar as novas necessidades do mercado e proteger os usuários contra eventuais prejuízos.

A principal mudança trazida pela medida é a ampliação do prazo para contestação de solicitações indevidas no Mecanismo Especial de Devolução (MED), que passa de 30 para até 80 dias. O ajuste busca dar mais tempo para que comerciantes e prestadores de serviços apresentem comprovantes, como notas fiscais e registros de entrega, evitando prejuízos causados por contestações fraudulentas. É importante destacar que o acionamento do MED não resulta na devolução automática dos valores, pois cada caso continua sob análise criteriosa das instituições financeiras envolvidas. Enquanto as novas normas entram em funcionamento, a regra para movimentações em celulares ou computadores não cadastrados previamente no banco continua a mesma, com limites de R$ 200 por operação e R$ 1.000 no acumulado diário.', 'https://imagens.bandab.com.br/file/bandab/2026/09/regra-do-pix-2.jpg', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-01 21:29:31.105+00', 4, false, 'Banco Central amplia prazo para contestação de Pix e mantém limites para dispositivos não cadastrados', 'O sistema de pagamentos instantâneos do Brasil passa por uma atualização significativa a partir desta terça-feira, 1º de setembro. Uma nova regra estabelecida pelo Banco Central (BC) entrou ...'),
  ('2d08402f-d06d-4a64-b235-094495aeb518', 'Idosa de 73 anos é morta a pauladas pelo filho na zona rural de Inhambupe, na Bahia', 'idosa-de-73-anos-e-morta-a-pauladas-pelo-filho-na-zona-rural-de-inhambupe-na-bah', 'Eurides da Silva Santos, 73 anos, foi encontrada morta na zona rural de Inhambupe, no interior da Bahia, após ser agredida pelo próprio filho, de 32 anos. O crime ocorreu em uma residência s...', 'Eurides da Silva Santos, 73 anos, foi encontrada morta na zona rural de Inhambupe, no interior da Bahia, após ser agredida pelo próprio filho, de 32 anos. O crime ocorreu em uma residência situada às margens da BR-110, próximo ao entroncamento de Sátiro Dias. O suspeito foi preso em flagrante no sábado (29) e autuado pela Polícia Civil pelo crime de feminicídio.

A Polícia Militar foi acionada após denúncias de agressão contra a vítima. Ao chegar ao local, os agentes encontraram a idosa sem sinais vitais, fato confirmado por uma equipe do Serviço de Atendimento Móvel de Urgência (Samu). O filho da vítima estava dentro da casa segurando um pedaço de madeira e apresentou comportamento agressivo, tentando atacar os policiais durante a abordagem. Para contê-lo, os agentes utilizaram uma arma de choque.

Após ser imobilizado e receber atendimento médico, o suspeito foi levado à 1ª Delegacia Territorial de Alagoinhas, onde a ocorrência foi registrada. Ele permanece custodiado à disposição do Poder Judiciário. O Departamento de Polícia Técnica realizou a perícia no local e o corpo de Eurides foi encaminhado ao Instituto Médico-Legal de Alagoinhas. A investigação segue em andamento para esclarecer as circunstâncias do crime.', 'https://midias.correio24horas.com.br/2026/09/01/eurides-da-silva-santos-foi-morta-a-pauladas-na-bahia-3398672-article.webp', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-01 21:32:12.266+00', 0, false, 'Idosa de 73 anos é morta a pauladas pelo filho na zona rural de Inhambupe, na Bahia', 'Eurides da Silva Santos, 73 anos, foi encontrada morta na zona rural de Inhambupe, no interior da Bahia, após ser agredida pelo próprio filho, de 32 anos. O crime ocorreu em uma residência s...'),
  ('2b55fd9e-9f92-4fc4-9bca-d67a0dd06e33', 'Ministros do STF quase brigam após quebra de sigilo de Vorcaro', 'ministros-do-stf-quase-brigam-apos-quebra-de-sigilo-de-vorcaro', 'Os ministros do Supremo Tribunal Federal (STF), Alexandre de Moraes e André Mendonça, protagonizaram uma discussão acalorada nesta terça-feira, 1º, que quase resultou em agressões físicas. O...', 'Os ministros do Supremo Tribunal Federal (STF), Alexandre de Moraes e André Mendonça, protagonizaram uma discussão acalorada nesta terça-feira, 1º, que quase resultou em agressões físicas. O incidente ocorreu após a quebra do sigilo das conversas do ex-dono do Banco Master, Daniel Vorcaro, e de uma tentativa de Moraes de reunir-se com o colega para tratar do assunto.

De acordo com informações da coluna Andrezza Matais, do Metrópoles, a tensão aumentou quando Moraes acusou Mendonça de direcionar as investigações contra si. Mendonça, por sua vez, questionou como o colega teve acesso às informações, que deveriam estar protegidas pelo sigilo de justiça. A revelação envolvia uma ordem para que a Polícia Federal identificasse o interlocutor de Vorcaro, que seria Moraes. Nas mensagens, Vorcaro supostamente pedia proteção ao ministro diante do procurador-geral da República, Paulo Gonet, e do diretor-geral da PF, Andrei Rodrigues. Após o embate, Moraes estaria articulando medidas contra Mendonça.', 'https://cdn.atarde.com.br/img/Artigo-Destaque/1400000/moraes-e-mendonca-quase-chegam-as-vias-de-fato-apo0140049200202609011441.png?xid=7192818', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-02 00:00:17.996+00', 2, false, 'Ministros do STF quase brigam após quebra de sigilo de Vorcaro', 'Os ministros do Supremo Tribunal Federal (STF), Alexandre de Moraes e André Mendonça, protagonizaram uma discussão acalorada nesta terça-feira, 1º, que quase resultou em agressões físicas. O...'),
  ('44e350f4-23ac-4464-b95d-07155e46c661', 'MPBA abre seleção para estágio jurídico em Salvador e interior; inscrições até 29 de setembro', 'mpba-abre-selecao-para-estagio-juridico-em-salvador-e-interior-inscricoes-ate-29', 'O Ministério Público do Estado da Bahia (MPBA) publicou nesta segunda-feira (31) o edital de seleção para estágio na área jurídica. As oportunidades estão disponíveis para candidatos em Salv...', 'O Ministério Público do Estado da Bahia (MPBA) publicou nesta segunda-feira (31) o edital de seleção para estágio na área jurídica. As oportunidades estão disponíveis para candidatos em Salvador e em diversos municípios do interior do estado. O período de inscrições permanece aberto até o dia 29 de setembro, com taxa de participação fixada em R$ 55.

O processo seletivo é organizado pelo Instituto Sustente, banca responsável pela aplicação do certame. Para participar, os estudantes devem acessar o edital completo e realizar a inscrição diretamente no site da instituição organizadora. A avaliação dos candidatos será conduzida por meio de prova on-line, agendada para o dia 30 de outubro, com início às 14h.

Os estagiários aprovados terão jornada de trabalho de seis horas diárias, totalizando 30 horas semanais, distribuídas de segunda a sexta-feira. Como contrapartida, o órgão oferece uma bolsa mensal no valor de R$ 2.200,00, acrescida de auxílio-transporte, definido como duas passagens vigentes por dia. A iniciativa busca integrar estudantes de direito à prática jurídica, fortalecendo o quadro técnico do Ministério Público baiano.', 'https://adm.aratuon.com.br/assets/88b6d0f3-3e98-4653-b153-69315afbee5d?quality=80&amp;width=1200', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-02 11:35:41.703+00', 8, false, 'MPBA abre seleção para estágio jurídico em Salvador e interior; inscrições até 29 de setembro', 'O Ministério Público do Estado da Bahia (MPBA) publicou nesta segunda-feira (31) o edital de seleção para estágio na área jurídica. As oportunidades estão disponíveis para candidatos em Salv...'),
  ('9dfd5841-b2b9-45d4-ae11-d2356c31d839', 'Ônibus que transportava estudantes sofre acidente após pneu estourar em Ribeira do Pombal', 'onibus-que-transportava-estudantes-sofre-acidente-apos-pneu-estourar-em-ribeira-do-pombal', 'Ônibus escolar sofre acidente após pneu estourar em Ribeira do Pombal. Um estudante teve ferimento leve e passa bem.', '
Um ônibus que realizava o transporte de estudantes se envolveu em um acidente nesta quarta-feira (2), na BR 110 nas proximidades do Parque de Vaquejada de Renivan, em Ribeira do Pombal.

Segundo nota divulgada pela BSP Empreendimentos, responsável pelo serviço, o veículo era conduzido por um prestador terceirizado e teria perdido o controle após o estouro do pneu dianteiro.

A empresa informou que não houve vítimas graves. Um dos estudantes sofreu um corte leve na testa, recebeu atendimento médico no Hospital Santa Tereza e passa bem.

Ainda de acordo com a BSP, a empresa, em parceria com a Secretaria Municipal de Educação, providenciou o suporte necessário e o atendimento aos envolvidos.

A empresa também pediu que informações não confirmadas sobre o acidente não sejam compartilhadas, especialmente relatos sobre supostas vítimas graves.
', 'https://mkbnqyhvaozqfpmcyoyw.supabase.co/storage/v1/object/public/imagens/noticias/1788374493329_16l0n30.webp', '7d34292b-4217-4571-ba21-f7aa996aa1d3', NULL, '2026-09-02 18:42:55.501+00', 41, true, 'Ônibus escolar sofre acidente em Ribeira do Pombal', 'Ônibus que transportava estudantes sofre acidente após pneu estourar em Ribeira do Pombal. Um estudante teve ferimento leve e passa bem.'),
  ('079cd42c-bd93-4097-bbd5-98afaa421e80', 'Câmara aprova redução de tempo de serviço para inatividade de PMs e bombeiros', 'camara-aprova-reducao-de-tempo-de-servico-para-inatividade-de-pms-e-bombeiros', 'A Câmara dos Deputados aprovou, nesta terça-feira (1º), um projeto de lei que altera as regras para a inatividade remunerada de policiais militares e bombeiros militares. A principal mudança...', 'A Câmara dos Deputados aprovou, nesta terça-feira (1º), um projeto de lei que altera as regras para a inatividade remunerada de policiais militares e bombeiros militares. A principal mudança consiste na redução do tempo mínimo de exercício de atividade militar exigido para a transferência à reserva com remuneração integral, passando de 30 para 25 anos. O texto aprovado na Casa ainda será analisado pelo Senado Federal.

Além da redução do tempo militar, o projeto amplia de cinco para dez anos o período de atividade civil que poderá ser aproveitado no cálculo do tempo total de serviço. Essa atividade anterior pode ter sido exercida no serviço público ou na iniciativa privada, desde que devidamente comprovada e não tenha ocorrido simultaneamente à carreira militar. Para os homens, permanecem necessários 35 anos de serviço total para a inatividade com proventos integrais, dos quais pelo menos 25 devem ser de natureza militar. Para mulheres e integrantes do quadro de saúde, o texto estabelece 32 anos de tempo total, sendo pelo menos 22 de atividade militar. O período trabalhado fora da carreira deverá ser comprovado por certidão de tempo de contribuição. O projeto também permite considerar como atividade de natureza militar o tempo prestado nas Forças Armadas, em outras forças auxiliares ou em instituições policiais civis ou militares, desde que haja compatibilidade entre as funções e comprovação documental.', 'https://d1x4bjge7r9nas.cloudfront.net/wp-content/uploads/2026/08/14172552/WhatsApp-Image-2026-08-14-at-17.06.33-1.jpeg', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-02 18:59:56.378+00', 2, false, 'Câmara aprova redução de tempo de serviço para inatividade de PMs e bombeiros', 'A Câmara dos Deputados aprovou, nesta terça-feira (1º), um projeto de lei que altera as regras para a inatividade remunerada de policiais militares e bombeiros militares. A principal mudança...'),
  ('a1e02b06-35f9-490a-93ac-68cb96bf00a6', 'Lula sanciona lei de urgência cardiovascular e AVC no SUS', 'lula-sanciona-lei-de-urgencia-cardiovascular-e-avc-no-sus', 'O presidente Luiz Inácio Lula da Silva sancionou nesta quarta-feira (2) o projeto de lei que institui protocolos específicos para o atendimento de urgências cardiovasculares no Sistema Único...', 'O presidente Luiz Inácio Lula da Silva sancionou nesta quarta-feira (2) o projeto de lei que institui protocolos específicos para o atendimento de urgências cardiovasculares no Sistema Único de Saúde (SUS). A nova legislação abrange procedimentos para casos de infarto e acidente vascular cerebral (AVC), incluindo a autorização para o uso de medicamentos trombolíticos nas Unidades de Pronto Atendimento (UPAs). A medida visa padronizar o atendimento seguindo critérios de segurança definidos pelo Ministério da Saúde, garantindo que a medicação, utilizada para dissolver coágulos e restabelecer o fluxo sanguíneo, seja aplicada de forma adequada e segura nesses pontos de referência.

Durante a cerimônia no Palácio do Planalto, Lula destacou que a saúde pública deve ser compreendida como investimento e não como despesa. O presidente argumentou que o estado precisa considerar o custo social e econômico de não oferecer um atendimento adequado à população. “Quando a gente coloca o SAMU, a gente não tá gastando, a gente tá investindo na coisa mais sagrada do ser humano, que é salvar a vida”, declarou. Lula também enfatizou o compromisso de garantir que os pacientes em situação de vulnerabilidade tenham acesso a um tratamento de qualidade e respeito, assegurando que pessoas humildes não sejam tratadas como invisíveis no sistema de saúde.', 'https://d1x4bjge7r9nas.cloudfront.net/wp-content/uploads/2026/06/19154359/Presidente-Lula-positivo.png', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-02 18:59:59.699+00', 3, false, 'Lula sanciona lei de urgência cardiovascular e AVC no SUS', 'O presidente Luiz Inácio Lula da Silva sancionou nesta quarta-feira (2) o projeto de lei que institui protocolos específicos para o atendimento de urgências cardiovasculares no Sistema Único...'),
  ('43716c9e-85e5-4355-86fd-a08b7482212f', 'Comissão do Congresso aprova fim do imposto para compras internacionais de até US$ 50', 'comissao-do-congresso-aprova-fim-do-imposto-para-compras-internacionais-de-ate-u', 'O imposto de 20% sobre compras internacionais de até US$ 50, conhecido popularmente como "taxa das blusinhas", teve seu fim aprovado nesta quarta-feira (2) pela Comissão Mista do Congresso N...', 'O imposto de 20% sobre compras internacionais de até US$ 50, conhecido popularmente como "taxa das blusinhas", teve seu fim aprovado nesta quarta-feira (2) pela Comissão Mista do Congresso Nacional. A medida provisória (MP) que trata do tema avançou na comissão e agora segue para análise e votação nos plenários da Câmara dos Deputados e do Senado Federal. Há expectativa de que a MP 1.357 de 2026, proposta pelo Poder Executivo, seja definitivamente aprovada nas duas Casas legislativas ainda esta semana.

Além da isenção para compras de menor valor, o texto aprovado pela comissão também estabelece uma significativa redução na alíquota de importação para remessas postais vindas do exterior que totalizem até US$ 3 mil, passando de 60% para 30%. Após a potencial aprovação da medida, o Ministério da Fazenda deverá apresentar um primeiro relatório em novembro deste ano, seguido por avaliações a cada seis meses com informações de indicadores como emprego, renda, competitividade nacional e arrecadação. Setores empresariais também acompanharão de perto a avaliação periódica da política de isenção dessas importações. A MP enfrenta oposição de setores empresariais nacionais que denunciam "concorrência desleal" de empresas estrangeiras, especialmente da China. Por outro lado, o governo defende a medida, argumentando que ela beneficia o consumo popular e contribui para a formalização das operações, combatendo a informalidade e a evasão fiscal.', 'https://d1x4bjge7r9nas.cloudfront.net/wp-content/uploads/2026/09/02152340/55504235024_b14889fcbb_6k.jpg', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-02 19:00:26.736+00', 6, false, 'Comissão do Congresso aprova fim do imposto para compras internacionais de até US$ 50', 'O imposto de 20% sobre compras internacionais de até US$ 50, conhecido popularmente como "taxa das blusinhas", teve seu fim aprovado nesta quarta-feira (2) pela Comissão Mista do Congresso N...'),
  ('993a308f-2ace-4836-9528-38e553d97fae', 'Fachada de estabelecimento comercial desaba em Ribeira do Pombal', 'fachada-de-estabelecimento-comercial-desaba-em-ribeira-do-pombal', 'A fachada de uma loja desabou na movimentada Avenida Oliveira Brito, em Ribeira do Pombal. Destroços de estrutura metálica e gesso ficaram espalhados pelo passeio e parte da via pública, assustando quem passava pelo local, próximo ao Mr. Sheke.', 'A fachada de um estabelecimento comercial desabou subitamente na movimentada Avenida Oliveira Brito, em Ribeira do Pombal. O incidente, ocorrido nesta quarta-feira, assustou pedestres e motoristas que passavam pela região, gerando apreensão. A estrutura da loja cedeu sem aviso prévio, espalhando materiais pela área.

Com a queda, destroços de estrutura metálica e gesso ficaram dispersos tanto no passeio público quanto em parte da via. O desabamento aconteceu ao lado do conhecido estabelecimento Mr. Shake, um ponto de referência local. Até o momento, não foram divulgadas informações sobre possíveis feridos ou sobre as causas que levaram ao colapso da fachada.', 'https://imagemlink.cleissoncardoso.com/uploads/6e003819-025d-432a-82ba-dbff99a41108.png', '7d34292b-4217-4571-ba21-f7aa996aa1d3', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-02 21:11:51.603999+00', 1171, true, 'Fachada de loja desaba em Ribeira do Pombal | Avenida Oliveira Brito', 'A fachada de um estabelecimento comercial desabou na movimentada Avenida Oliveira Brito, em Ribeira do Pombal. Destroços ficaram espalhados pela via, causando alarme local.')
ON CONFLICT (id) DO NOTHING;

