INSERT INTO public.noticias (
  id, titulo, slug, resumo, conteudo, imagem_url,
  categoria_id, autor_id, data_publicacao, views, destaque, meta_title, meta_description
) VALUES
  ('b2d1a37a-7e8b-43c6-92b5-19fb3ca02cce', 'TJ-BA abre investigação sobre suposta fraude em registro civil de Jeremoabo', 'tj-ba-abre-investigacao-sobre-suposta-fraude-em-registro-civil-de-jeremoabo', 'O TJ-BA investiga supostas fraudes na emissão de guias e selos no cartório de Jeremoabo, após denúncia que aponta irregularidades no recolhimento de taxas e uso de sistemas oficiais.', 'A Corregedoria-Geral do Foro Extrajudicial do Tribunal de Justiça da Bahia (COGEX/TJBA) instaurou um procedimento para apurar possíveis fraudes e infrações penais na emissão de Selos Digitais de Fiscalização e guias do Documento de Arrecadação Judicial e Extrajudicial (DAJE) na comarca de Jeremoabo. A medida foi tomada após denúncia apresentada por Juliete Laura Rocha Mauricio, representante do Cartório de Registro de Imóveis da cidade, que apontou irregularidades no recolhimento de taxas e no uso dos sistemas oficiais, com foco nos atos do Registro Civil das Pessoas Naturais (RCPN).

Diante da gravidade dos fatos, o juiz assessor da COGEX, Moacir Reis Fernandes Filho, determinou medidas urgentes para verificar os fluxos de arrecadação fiscal e o uso dos sistemas. O Núcleo de Arrecadação Fiscal (NAF/COARC) e a Coordenação de Sistema de Informação (COSIS) do TJ-BA foram acionados para fornecer dados técnicos sobre a logística de geração dos selos e guias. Além disso, a Associação dos Registradores Civis da Bahia (Arpen-BA) e o oficial responsável pelo Registro Civil de Jeremoabo foram notificados, tendo este último o prazo de 10 dias para tomar ciência do caso e apresentar sua manifestação.', 'https://www.bahianoticias.com.br/fotos/justica_noticias/75288/IMAGEM_NOTICIA_9.jpg?checksum=1788431903', '902d44ce-469a-438d-82c4-b6e4a8357a30', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-03 11:53:11.576474+00', 113, true, 'TJ-BA investiga suposta fraude em cartório de Jeremoabo', NULL),
  ('7bbc7565-3708-46d0-b078-f0d58235d163', 'CSP pode votar projeto que autoriza porte de arma para mulheres com medida protetiva', 'csp-pode-votar-projeto-que-autoriza-porte-de-arma-para-mulheres-com-medida-prote', 'A Comissão de Segurança Pública do Senado Federal (CSP) deve analisar na próxima terça-feira, 1º de setembro, um projeto de lei que visa ampliar os direitos de proteção às vítimas de violênc...', 'A Comissão de Segurança Pública do Senado Federal (CSP) deve analisar na próxima terça-feira, 1º de setembro, um projeto de lei que visa ampliar os direitos de proteção às vítimas de violência doméstica. A proposta em questão autoriza o porte de arma de fogo para mulheres que possuam medida protetiva de urgência ativa. A votação é um dos seis itens incluídos na pauta da comissão para a sessão ordinária.

O texto em discussão é o PL 3.272/2024, de autoria da ex-senadora Rosana Martinelli, representando o estado de Mato Grosso. A iniciativa busca oferecer uma ferramenta adicional de defesa pessoal para mulheres que, mesmo protegidas judicialmente, ainda enfrentam riscos significativos de agressão. A inclusão do tema na pauta reflete a atenção do Legislativo federal para o fortalecimento das políticas de segurança pública voltadas à população feminina em situação de vulnerabilidade.', 'https://www12.senado.leg.br/noticias/materias/2026/08/28/csp-pode-votar-porte-de-arma-para-mulheres-com-medida-protetiva/20260714_00293sc.jpg', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-03 12:08:48.354+00', 3, false, 'CSP pode votar projeto que autoriza porte de arma para mulheres com medida protetiva', 'A Comissão de Segurança Pública do Senado Federal (CSP) deve analisar na próxima terça-feira, 1º de setembro, um projeto de lei que visa ampliar os direitos de proteção às vítimas de violênc...'),
  ('a3880cf5-0a22-4587-b4f3-71911702cab5', 'AtlasIntel: Rui Costa lidera ao Senado na Bahia com 28,2%; Jaques Wagner tem 23,7%', 'atlasintel-rui-costa-lidera-ao-senado-na-bahia-com-28-2-jaques-wagner-tem-23-7', 'Pesquisa AtlasIntel divulgada nesta quinta-feira (3/9) aponta que os candidatos petistas lideram a disputa pelas duas vagas ao Senado na Bahia. O ex-ministro Rui Costa obtém 28,2% das intenç...', 'Pesquisa AtlasIntel divulgada nesta quinta-feira (3/9) aponta que os candidatos petistas lideram a disputa pelas duas vagas ao Senado na Bahia. O ex-ministro Rui Costa obtém 28,2% das intenções de voto, enquanto o senador Jaques Wagner registra 23,7%. No recorte de primeira opção, Rui Costa alcança 39,3%, seguido por João Roma (PL), com 22,2%. Já para a segunda opção, Jaques Wagner é o mais citado, com 31,9%, à frente de Angelo Coronel (17,8%).

O levantamento foi realizado entre 28 de agosto e 2 de setembro, com 1.804 entrevistados via recrutamento digital aleatório. A margem de erro é de dois pontos percentuais, para mais ou para menos, com nível de confiança de 95%. O estudo está registrado no TSE sob o nº BA-08891/2026. Na corrida ao governo do estado, ACM Neto (União) e Jerônimo Rodrigues (PT) aparecem tecnicamente empatados em cenários de primeiro e segundo turnos. Para a Presidência, Lula (PT) lidera nas intenções de voto na Bahia, com 52,8% no primeiro turno.', 'https://i.metroimg.com/f58hIJnBudAZa4BEK20usdsHAm8QMSHT3Q0_PJQGM08/rs:fill:1200:800:1/g:no/q:85/f:webp/plain/https://images.metroimg.com/2026/06/rui-costa-e-jaques-wagner.jpg', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-03 12:10:23.745+00', 1, false, 'AtlasIntel: Rui Costa lidera ao Senado na Bahia com 28,2%; Jaques Wagner tem 23,7%', 'Pesquisa AtlasIntel divulgada nesta quinta-feira (3/9) aponta que os candidatos petistas lideram a disputa pelas duas vagas ao Senado na Bahia. O ex-ministro Rui Costa obtém 28,2% das intenç...'),
  ('d16f0f55-b4e1-4864-97ee-2aac6f88f855', 'Nikolas Ferreira pede ajuda a Vorcaro para ativo minerário em Nova Lima', 'nikolas-ferreira-pede-ajuda-a-vorcaro-para-ativo-minerario-em-nova-lima', 'O deputado federal Nikolas Ferreira (PL-MG) enviou áudios ao banqueiro Daniel Vorcaro em março de 2025 solicitando intermediação para a liberação de um ativo minerário. A negociação envolver...', 'O deputado federal Nikolas Ferreira (PL-MG) enviou áudios ao banqueiro Daniel Vorcaro em março de 2025 solicitando intermediação para a liberação de um ativo minerário. A negociação envolveria Thiago Rodrigues de Faria, ex-assessor do parlamentar, que segundo a Polícia Federal atuou como intermediário em esquema de extração ilegal de minério de ferro na Serra do Curral, em Nova Lima.

Conforme as mensagens obtidas, Ferreira tratou Vorcaro por apelidos e ofereceu o contato de Faria para tratar do negócio. O caso ganhou repercussão após a deflagração da Operação Rejeito, em setembro de 2025, que resultou na prisão preventiva de 22 pessoas investigadas por crimes ambientais e ilícitos minerários. Um contrato entre a empresa de Faria e a Gmais Ambiental previa remuneração de 25% sobre lucros estimados entre US$ 30 milhões e US$ 45 milhões caso a lavra fosse retomada. Faria alega não ter envolvimento com as irregularidades apontadas.', 'https://www.bnews.com.br/media/_versions/2026/09/em-audio-nikolas-ferreira-chama-vorcaro-de-dani-e-lindao-pede-ajuda-com-minerio-e-cita-pastor-valadao-ouca_widexl.jpg', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-03 12:11:37.601+00', 1, false, 'Nikolas Ferreira pede ajuda a Vorcaro para ativo minerário em Nova Lima', 'O deputado federal Nikolas Ferreira (PL-MG) enviou áudios ao banqueiro Daniel Vorcaro em março de 2025 solicitando intermediação para a liberação de um ativo minerário. A negociação envolver...'),
  ('1d2b2a6a-d3b2-4e8f-91c2-80d9d6387856', 'Atlas: Lula lidera com 52,8% no 1º turno na Bahia; Flávio tem 24,4%', 'atlas-lula-lidera-com-52-8-no-1-turno-na-bahia-flavio-tem-24-4', 'Pesquisa AtlasIntel divulgada nesta quinta-feira (3/9) aponta o presidente Luiz Inácio Lula da Silva (PT) como o candidato à Presidência favorito na Bahia, com 52,8% das intenções de voto em...', 'Pesquisa AtlasIntel divulgada nesta quinta-feira (3/9) aponta o presidente Luiz Inácio Lula da Silva (PT) como o candidato à Presidência favorito na Bahia, com 52,8% das intenções de voto em primeiro turno no estado. No mesmo cenário, o senador Flávio Bolsonaro (PL) soma 24,4%. Em eventual segundo turno, o petista chega a 58,1% das intenções de voto contra 29% do adversário.

O levantamento foi realizado entre os dias 28 de agosto e 2 de setembro, com uma amostragem de 1.804 pessoas entrevistadas através de recrutamento digital aleatório. A margem de erro é de dois pontos percentuais, para mais ou para menos, com nível de confiança de 95%. O estudo está inscrito no Tribunal Superior Eleitoral (TSE) sob o número BR-07739/2026. Na disputa ao governo da Bahia, ACM Neto (União) e Jerônimo Rodrigues (PT) aparecem tecnicamente empatados. Para o Senado, Rui Costa (PT) lidera como primeira opção com 39,3%, seguido por João Roma (PL) com 22,2%. Já como segunda opção, Jaques Wagner (PT) é o nome mais citado, com 31,9%.', 'https://i.metroimg.com/cFKfIa1K6NvlU92qDlfrYvBf23Q-zIXKqFPnEakGykk/rs:fill:1200:800:1/g:no/q:85/f:webp/plain/https://images.metroimg.com/2026/06/lula-flaviojpg.jpeg', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-03 12:31:36.199+00', 0, false, 'Atlas: Lula lidera com 52,8% no 1º turno na Bahia; Flávio tem 24,4%', 'Pesquisa AtlasIntel divulgada nesta quinta-feira (3/9) aponta o presidente Luiz Inácio Lula da Silva (PT) como o candidato à Presidência favorito na Bahia, com 52,8% das intenções de voto em...'),
  ('442833f8-cca1-4090-acbf-e187a0bff289', 'Anvisa interdita água mineral Vitoriosa por presença de coliformes', 'anvisa-interdita-agua-mineral-vitoriosa-por-presenca-de-coliformes', 'A Agência Nacional de Vigilância Sanitária (Anvisa) determinou, nesta quarta-feira (2/9), a interdição cautelar da Água Mineral sem Gás da marca Vitoriosa. A medida foi adotada após análises...', 'A Agência Nacional de Vigilância Sanitária (Anvisa) determinou, nesta quarta-feira (2/9), a interdição cautelar da Água Mineral sem Gás da marca Vitoriosa. A medida foi adotada após análises laboratoriais apontarem que o produto não atende aos padrões sanitários de potabilidade exigidos pela legislação. O laudo foi emitido pelo Laboratório Central de Saúde Pública Noel Nutels, do Rio de Janeiro, que identificou resultado insatisfatório no ensaio microbiológico, com detecção de coliformes totais em amostras de 250 mL.

O produto é fabricado pela GEPF Agroindústria Ltda, empresa sediada em Engenheiro Paulo de Frontin, no estado do Rio de Janeiro. De acordo com a Anvisa e o Ministério da Saúde, a legislação para águas minerais envasadas exige a ausência total de coliformes. Embora esses microrganismos possam ser provenientes do meio ambiente ou de falhas de limpeza, e não necessariamente de contaminação fecal, sua presença classifica a água como imprópria para consumo. Dessa forma, o comércio e o consumo do produto estão proibidos até que seja comprovada a sua segurança sanitária. A reportagem tentou contato com a GEPF Agroindústria Ltda para apurar a versão da empresa.', 'https://i.metroimg.com/0kRnRfZ7wuwIYsy2EZpmGgmp962tn2FSpdk3-U1fmVc/rs:fill:1200:800:1/g:no/q:85/f:webp/plain/https://images.metroimg.com/2024/10/29135848/garrafas-agua.jpg', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-03 12:31:37.005+00', 3, false, 'Anvisa interdita água mineral Vitoriosa por presença de coliformes', 'A Agência Nacional de Vigilância Sanitária (Anvisa) determinou, nesta quarta-feira (2/9), a interdição cautelar da Água Mineral sem Gás da marca Vitoriosa. A medida foi adotada após análises...'),
  ('fead57aa-c964-4cc0-8949-781b960a64de', 'Polícia Civil prende condenado por homicídio e apreende drogas em Operação Retração em Serrinha', 'policia-civil-prende-condenado-por-homicidio-e-apreende-drogas-em-operacao-retra', 'A Polícia Civil da Bahia deflagrou a Operação Retração na manhã desta quinta-feira (3) em Serrinha, na região sisaleira do estado. A ação teve como principal objetivo desarticular um grupo c...', 'A Polícia Civil da Bahia deflagrou a Operação Retração na manhã desta quinta-feira (3) em Serrinha, na região sisaleira do estado. A ação teve como principal objetivo desarticular um grupo criminoso investigado por envolvimento com tráfico de drogas e homicídios no município. Cerca de 60 policiais civis foram mobilizados para cumprir 11 mandados de busca e apreensão, além de um mandado de prisão.

Durante as diligências, um homem que possuía mandado de prisão e recaptura em aberto foi localizado e detido. De acordo com a Polícia Civil, ele havia sido condenado a 12 anos de reclusão pelo crime de homicídio. A operação resultou na apreensão de 60 pinos e dez papelotes de cocaína, 174 gramas da mesma droga, aproximadamente 70 gramas de maconha, um simulacro de arma de fogo, R$ 6.893 em dinheiro, oito aparelhos celulares e centenas de embalagens para entorpecentes. Também foram apreendidos sete relógios, quatro anéis e uma corrente de ouro. Quatro pessoas foram conduzidas à Delegacia Territorial de Serrinha: uma presa por mandado judicial, outra autuada em flagrante por tráfico, e duas com Termos Circunstanciados de Ocorrência (TCOs) lavrados. O material coletado será analisado para subsidiar as investigações.', 'https://imagemlink.cleissoncardoso.com/uploads/cf33c01b-384a-4a5f-93f3-e27a7a9c96d3.png', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-03 19:35:58.957+00', 1, false, 'Polícia Civil prende condenado por homicídio e apreende drogas em Operação Retração em Serrinha', 'A Polícia Civil da Bahia deflagrou a Operação Retração na manhã desta quinta-feira (3) em Serrinha, na região sisaleira do estado. A ação teve como principal objetivo desarticular um grupo c...'),
  ('2a73c8f1-59ec-46a2-8abb-ffae37cb39ca', 'Datafolha: Lula tem 46% no 2º turno contra 44% de Flávio Bolsonaro', 'datafolha-lula-tem-46-no-2-turno-contra-44-de-flavio-bolsonaro', 'Levantamento do instituto Datafolha, divulgado nesta quinta-feira (3), aponta que o presidente Luiz Inácio Lula da Silva (PT) lidera a disputa presidencial de 2026 em uma simulação de segund...', 'Levantamento do instituto Datafolha, divulgado nesta quinta-feira (3), aponta que o presidente Luiz Inácio Lula da Silva (PT) lidera a disputa presidencial de 2026 em uma simulação de segundo turno contra o senador Flávio Bolsonaro (PL). Na pesquisa, Lula registra 46% das intenções de voto, enquanto Flávio Bolsonaro alcança 44%, indicando um cenário de empate técnico dentro da margem de erro.

O estudo também testou cenários de confronto entre Lula e outros pré-candidatos. Contra Ronaldo Caiado (PSD), o presidente atinge 46%, ante 41% do ex-governador de Goiás. No duelo contra Romeu Zema (Novo), Lula alcança 48% das preferências, superando os 39% do ex-governador de Minas Gerais. Em confronto direto com Renan Santos (Missão), coordenador do Movimento Brasil Livre, Lula soma 47%, contra 38% do adversário.

A pesquisa ouviu 2.002 eleitores entre os dias 1º e 2 de setembro. A margem de erro é de dois pontos percentuais, para mais ou para menos, com nível de confiança de 95%. O estudo foi contratado pela Folha de S.Paulo e pelo Grupo Globo e está registrado no Tribunal Superior Eleitoral sob o número TSE-03669/2026.', 'https://www.bahianoticias.com.br/fotos/principal_noticias/320732/IMAGEM_NOTICIA_9.jpg?checksum=1788474366', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-04 12:34:31.116+00', 5, false, 'Datafolha: Lula tem 46% no 2º turno contra 44% de Flávio Bolsonaro', 'Levantamento do instituto Datafolha, divulgado nesta quinta-feira (3), aponta que o presidente Luiz Inácio Lula da Silva (PT) lidera a disputa presidencial de 2026 em uma simulação de segund...'),
  ('eda823aa-ba20-4117-a22f-7827682ad7c8', 'Homem detido por manter companheira em cárcere tem prisão mantida em Gongogi', 'homem-detido-por-manter-companheira-em-carcere-tem-prisao-mantida-em-gongogi', 'A Justiça mantve a prisão de um homem detido por manter a companheira em cárcere privado no município de Gongogi, no oeste da Bahia. O suspeito passou por audiência de custódia nesta quinta-...', 'A Justiça mantve a prisão de um homem detido por manter a companheira em cárcere privado no município de Gongogi, no oeste da Bahia. O suspeito passou por audiência de custódia nesta quinta-feira (3), onde a medida foi confirmada pelas autoridades competentes.

O crime foi denunciado após uma profissional de uma escola local ler bilhetes com pedidos de socorro e acionar a polícia. A intervenção rápida permitiu a captura do suspeito e a libertação da vítima. O caso destaca a importância da atuação de profissionais da educação na identificação de situações de violência doméstica e na proteção de vítimas vulneráveis.', 'https://s2-g1.glbimg.com/swdrY78HDa86kXk9GNDEkYbrhvk=/1700x0/filters:format(jpeg)/https://i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/a/x/HGKW7PQc2XBUdqd9Nd4A/foto-no-tamanho-home-2026-09-03t094706.730.png', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-04 12:35:12.241+00', 0, false, 'Homem detido por manter companheira em cárcere tem prisão mantida em Gongogi', 'A Justiça mantve a prisão de um homem detido por manter a companheira em cárcere privado no município de Gongogi, no oeste da Bahia. O suspeito passou por audiência de custódia nesta quinta-...'),
  ('34149875-588f-43b5-ad31-b8a98b9e15eb', 'Empresário é acusado de fraude com documento federal falso em Cipó', 'empresario-e-acusado-de-fraude-com-documento-federal-falso-em-cipo', 'Um empresário é acusado de usar um documento falso do Governo Federal em Cipó para tentar obter pagamentos antecipados por supostos recursos federais. A prefeitura desconfiou e o Ministério das Cidades confirmou a fraude. Ele possui histórico de outras acusações arquivadas.', 'O empresário Uryel Victor Lima de Santana é acusado de tentar aplicar golpes ao apresentar um suposto documento falso do Governo Federal à Prefeitura de Cipó, no Nordeste da Bahia. Ele teria solicitado pagamentos antecipados para que o município recebesse recursos da União, destinados à pavimentação asfáltica. Segundo a prefeitura, durante a negociação, Uryel pediu 20% do valor total, justificando que a quantia agilizaria a liberação de mais de R$ 7 milhões em verbas federais. A situação, ocorrida em fevereiro de 2024, levantou suspeitas, levando o município a contatar diretamente o Ministério das Cidades. O prefeito de Cipó, Marquinhos (PSD), informou que o órgão federal confirmou a falsidade do documento e a inexistência da destinação de recursos, motivando um alerta a gestores públicos baianos.

Documentos judiciais consultados pela reportagem indicam que Uryel Victor também foi investigado em outro processo, relacionado a uma denúncia de fraude financeira. Neste caso, ele é acusado de ter se aproveitado da companheira de sua avó, que era analfabeta e possuía sequelas neurológicas. Ele teria induzido a mulher a assinar uma procuração e entregar documentos pessoais, resultando em empréstimos e gastos com cartões de crédito que somaram aproximadamente R$ 819 mil. Embora uma audiência de conciliação tenha ocorrido em setembro de 2025, Uryel não compareceu. Em ambos os casos, os inquéritos acabaram arquivados após as vítimas desistirem das acusações. A reportagem ressalta que as acusações e investigações não representam condenação criminal, e Uryel Victor Lima de Santana tem direito à ampla defesa e presunção de inocência, não tendo se manifestado sobre o conteúdo da matéria.', 'https://www.bahianoticias.com.br/fotos/principal_noticias/320655/IMAGEM_NOTICIA_9.jpg?checksum=1788358031', '3949c67e-3936-409d-9600-28782301730d', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-04 12:35:59.224666+00', 114, true, 'Empresário acusado de fraude com documento federal falso em Cipó', NULL),
  ('ea195b88-c6ab-4dd0-a164-74c1a8eb5157', 'Homem é preso em Alagoas suspeito de espancar e matar filha de dois meses', 'homem-e-preso-em-alagoas-suspeito-de-espancar-e-matar-filha-de-dois-meses', 'Um homem identificado como Daniel Nunes da Silva, de 19 anos, foi detido na segunda-feira (31) em Senador Rui Palmeira, no interior de Alagoas. Ele é investigado sob a suspeita de agredir e ...', 'Um homem identificado como Daniel Nunes da Silva, de 19 anos, foi detido na segunda-feira (31) em Senador Rui Palmeira, no interior de Alagoas. Ele é investigado sob a suspeita de agredir e causar a morte de sua filha, uma bebê de apenas dois meses. A criança, identificada como Anne Emanuely, apresentava múltiplos hematomas e uma possível fratura em uma das pernas, conforme os primeiros relatos da Polícia Militar.

Os responsáveis pela bebê a levaram a uma unidade de saúde, alegando que a criança havia sofrido uma queda da cama. Inicialmente, a ocorrência foi registrada como morte a esclarecer, aguardando investigação. Contudo, após uma perícia inicial e com base nos elementos indicados no laudo preliminar, as autoridades iniciaram diligências que levaram à localização e prisão do pai. O corpo de Anne Emanuely foi encaminhado ao Instituto Médico Legal (IML) de Arapiraca, no Agreste alagoano, onde será submetido a exames para determinar as causas exatas do óbito.', 'https://www.bnews.com.br/media/_versions/2026/09/crime-alagoas_widexl.jpg', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-04 12:42:28.957+00', 5, false, 'Homem é preso em Alagoas suspeito de espancar e matar filha de dois meses', 'Um homem identificado como Daniel Nunes da Silva, de 19 anos, foi detido na segunda-feira (31) em Senador Rui Palmeira, no interior de Alagoas. Ele é investigado sob a suspeita de agredir e ...'),
  ('535eaec1-5d5c-4c44-b5ca-8b76f77155d2', 'Vorcaro afirma em delação que doações a Tarcísio e Bolsonaro eram propina por ajuste com Kassab', 'vorcaro-afirma-em-delacao-que-doacoes-a-tarcisio-e-bolsonaro-eram-propina-por-aj', 'O ex-banqueiro Daniel Vorcaro, detido no escândalo do Banco Master, declarou em proposta de delação premiada que as doações de R$ 5 milhões às campanhas de Tarcísio de Freitas e Jair Bolsona...', 'O ex-banqueiro Daniel Vorcaro, detido no escândalo do Banco Master, declarou em proposta de delação premiada que as doações de R$ 5 milhões às campanhas de Tarcísio de Freitas e Jair Bolsonaro em 2022 constituíram pagamento de propina. Segundo o relato, os valores, sendo R$ 2 milhões para o governador paulista e R$ 3 milhões para o ex-presidente, representariam contrapartidas financeiras por um ajuste indevido com Gilberto Kassab para a manutenção do cartão Credcesta no governo estadual.

As informações, divulgadas pelo Uol, constam em delações negadas pela Polícia Federal e pela PGR. Vorcaro afirmou que a negociação ocorreu para assegurar a continuidade do Credcesta no governo de São Paulo, com pagamentos inicialmente em espécie até a exigência de doações oficiais por partidos aliados. Tarcísio e Kassab negaram qualquer vínculo com Vorcaro, classificando os relatos como fantasiosos e afirmando que a campanha seguiu a legislação eleitoral e que o credenciamento do cartão ocorreu em gestão anterior. A defesa de Augusto Lima classificou as acusações como absurdas e optou por não comentar.', 'https://i.metroimg.com/fs2-mrJm3PR0IW3qXQ98bGfRm3Nny7oS46lkBH7WZ_o/rs:fill:1200:800:1/g:no/q:85/f:webp/plain/https://images.metroimg.com/2026/09/vorcaro-tarcisio-e-bolsonaro.jpg', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-04 12:43:33.48+00', 3, false, 'Vorcaro afirma em delação que doações a Tarcísio e Bolsonaro eram propina por ajuste com Kassab', 'O ex-banqueiro Daniel Vorcaro, detido no escândalo do Banco Master, declarou em proposta de delação premiada que as doações de R$ 5 milhões às campanhas de Tarcísio de Freitas e Jair Bolsona...'),
  ('a14f8686-829f-4c35-a161-3dbfbdde6a4a', 'Professor é condenado a 7 anos por injúria racial contra aluno em Maceió', 'professor-e-condenado-a-7-anos-por-injuria-racial-contra-aluno-em-maceio', 'Um professor de uma escola particular em Maceió foi condenado a sete anos de prisão por crimes de injúria racial e corrupção de menores. A decisão judicial determinou que o docente compare a...', 'Um professor de uma escola particular em Maceió foi condenado a sete anos de prisão por crimes de injúria racial e corrupção de menores. A decisão judicial determinou que o docente compare a uma indenização de R$ 15 mil à vítima, um adolescente de 13 anos, após ter feito comparações ofensivas entre o aluno e um chimpanzé.

O caso ganhou destaque após a repercussão das declarações proferidas pelo educador em ambiente escolar, que foram consideradas graves e violatórias dos direitos humanos da vítima. A condenação abrange tanto a penalidade restritiva de liberdade quanto a reparação civil pelos danos morais sofridos pelo menor. A sentença destaca a gravidade da conduta e o impacto negativo das atitudes discriminatórias no desenvolvimento e na dignidade dos estudantes.', 'https://s2-g1.glbimg.com/94TDfCqsZYCFpILSzmpXUnIqspI=/1919x0/filters:format(jpeg)/https://i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2026/O/F/SZvLFQTv2xX7IM6S6HnQ/captura-de-tela-2026-09-02-151810.png', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-04 12:45:52.938+00', 0, false, 'Professor é condenado a 7 anos por injúria racial contra aluno em Maceió', 'Um professor de uma escola particular em Maceió foi condenado a sete anos de prisão por crimes de injúria racial e corrupção de menores. A decisão judicial determinou que o docente compare a...'),
  ('a00f8fd7-cc3b-4d94-8057-4b402d351ae2', 'Banzaê registra segunda morte de ciclista por atropelamento em 2026', 'banzae-registra-segunda-morte-de-ciclista-por-atropelamento-em-2026', 'Banzaê registrou a segunda morte de ciclista por atropelamento em 2026, ocorrida na noite de quarta-feira (2) próximo ao Portal da cidade. O caso levanta preocupações sobre a segurança no trânsito local.', 'Banzaê registrou, na noite desta quarta-feira (2), mais uma morte envolvendo um ciclista vítima de atropelamento. O acidente fatal ocorreu por volta das 18h, nas proximidades do Portal de entrada da cidade. Este novo caso eleva para dois o número de mortes de ciclistas por atropelamento no município em 2026. O primeiro incidente deste tipo, também envolvendo um ciclista, foi registrado em 9 de junho deste ano, destacando uma preocupante recorrência de acidentes fatais.

A repetição desses acidentes em um curto intervalo de meses intensifica a preocupação da população local e alerta para a necessidade de maior atenção à segurança no trânsito, tanto por parte de motoristas quanto de ciclistas. O cenário atual reforça a urgência do respeito às regras de trânsito, especialmente em áreas de alta circulação de bicicletas e nos acessos à cidade. As circunstâncias detalhadas do acidente ocorrido nesta quarta-feira serão objeto de investigação pelas autoridades competentes, que buscarão esclarecer os fatos e possíveis causas.', 'https://imagemlink.cleissoncardoso.com/uploads/20e61ed7-d9ce-4c57-926e-86f0eda7df4a.png', '1fd8f094-c10e-4a49-a50a-01fdc88cda45', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-04 20:27:49.469893+00', 1018, true, 'Banzaê: Ciclista morre em 2º atropelamento fatal na cidade em 2026', 'Um ciclista morreu em Banzaê na noite de quarta-feira (2), marcando a segunda morte por atropelamento na cidade em 2026 e acendendo alerta para segurança viária.'),
  ('d7c27a40-b23a-4766-a1d3-da7f397417d7', 'Ciclista morre atropelado em Banzaê na quarta (2); é a segunda morte em 2026', 'ciclista-morre-atropelado-em-banzae-na-quarta-2-e-a-segunda-morte-em-2026', 'Banzaê registrou a segunda morte de ciclista por atropelamento em 2026, após um acidente na noite de quarta-feira (2) próximo ao Portal da cidade. O caso levanta preocupações sobre a segurança no trânsito e a necessidade de atenção redobrada.', 'Banzaê registrou, na noite da última quarta-feira (2), mais uma morte envolvendo um ciclista vítima de atropelamento. O acidente ocorreu por volta das 18h, nas proximidades do Portal de entrada da cidade. Este novo caso eleva para dois o número de ciclistas que perderam a vida em atropelamentos no município apenas neste ano de 2026, acendendo um alerta sobre a segurança no trânsito local e a urgência de maior atenção mútua entre motoristas e ciclistas nas vias.

A primeira fatalidade envolvendo um ciclista em 2026 havia sido registrada em 9 de junho. A recorrência de acidentes fatais em um intervalo de poucos meses gera preocupação entre a população de Banzaê e direciona a atenção para as condições de segurança nas vias que são diariamente utilizadas por ciclistas, motociclistas e motoristas. Além da necessidade de atenção redobrada por parte de todos os condutores, o cenário sublinha a importância do respeito rigoroso às regras de trânsito, em especial em áreas de intensa circulação de bicicletas e nos acessos ao município. As circunstâncias exatas do acidente ocorrido na quarta-feira estão sob investigação das autoridades competentes, que buscarão esclarecer os fatos.', 'https://imagemlink.cleissoncardoso.com/uploads/25c7d933-0f29-40b0-ae37-ef548b61b3d2.png', '1fd8f094-c10e-4a49-a50a-01fdc88cda45', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-04 20:31:12.358879+00', 1018, true, 'Banzaê: Ciclista morre atropelado; 2ª fatalidade no ano', 'Um ciclista morreu atropelado em Banzaê na quarta-feira (2), marcando a segunda fatalidade do tipo em 2026. O caso eleva o alerta para a segurança no trânsito local.'),
  ('30c56846-0d8c-464f-bf90-b66f204efdbd', 'Ciclista morre atropelado em Banzaê  ', 'ciclista-morre-atropelado-em-banzae-pela-segunda-vez-em-2026', 'Banzaê registrou a segunda morte de ciclista por atropelamento em 2026 na noite de quarta-feira (2). O acidente próximo ao Portal da cidade reforça a preocupação com a segurança no trânsito local e a necessidade de atenção redobrada.', 'Banzaê registrou, na noite desta quarta-feira (2), mais uma morte envolvendo um ciclista vítima de atropelamento. O acidente aconteceu por volta das 18h, nas proximidades do Portal de entrada da cidade. Este novo caso eleva para dois o número de ciclistas que perderam a vida por atropelamento no município em 2026, gerando um alerta sobre a segurança no trânsito e a necessidade de maior atenção entre motoristas e ciclistas.

O primeiro incidente fatal envolvendo um ciclista neste ano ocorreu no dia 9 de junho. A recorrência de acidentes fatais em um curto período preocupa a população e destaca a urgência de melhorias nas condições de segurança das vias, utilizadas diariamente por diversos condutores. Além da atenção redobrada dos condutores, o cenário ressalta a importância do respeito às regras de trânsito, especialmente em áreas de circulação de ciclistas e nos acessos à cidade. As circunstâncias do acidente desta quarta-feira deverão ser apuradas pelas autoridades responsáveis pela investigação.', 'https://imagemlink.cleissoncardoso.com/uploads/2d0574ce-ae01-4d53-9358-7357f58ebad2.png', '1fd8f094-c10e-4a49-a50a-01fdc88cda45', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-04 20:33:22.421401+00', 1028, true, 'Morte de ciclista em Banzaê: Segundo caso de atropelamento em 2026', 'Banzaê registra a segunda morte de ciclista atropelado em 2026. O acidente na noite de quarta (2), próximo ao Portal, reforça alerta para segurança no trânsito local.'),
  ('8b29bde6-32a1-4289-b097-dc736a455708', 'Borracheiro de 69 anos morre esmagado por caminhão em Lagarto, Sergipe', 'borracheiro-de-69-anos-morre-esmagado-por-caminhao-em-lagarto-sergipe', 'Um borracheiro de 69 anos faleceu na manhã desta quinta-feira (3) após ser esmagado por um caminhão no município de Lagarto, localizado na região Centro-Sul de Sergipe. O acidente ocorreu en...', 'Um borracheiro de 69 anos faleceu na manhã desta quinta-feira (3) após ser esmagado por um caminhão no município de Lagarto, localizado na região Centro-Sul de Sergipe. O acidente ocorreu enquanto o profissional realizava um serviço no veículo pesado. As informações foram confirmadas pela Polícia Militar, que recebeu relatos de uma testemunha presente no local.

De acordo com o depoimento da testemunha à Polícia Militar, o homem estava trabalhando embaixo do caminhão. No momento em que iniciou o procedimento para remover o macaco hidráulico que sustentava o veículo, o caminhão teria perdido a estabilidade após sair do calço. O veículo então desceu, atingindo a vítima na região abdominal e provocando lesões fatais. O Serviço de Atendimento Móvel de Urgência (Samu) foi rapidamente acionado, mas os socorristas, ao chegarem ao local do ocorrido, apenas puderam constatar o óbito do borracheiro. O Instituto Médico Legal (IML) foi acionado na sequência para realizar a remoção do corpo.', 'https://imagemlink.cleissoncardoso.com/uploads/bbb36104-6a42-4d8d-b6cb-e61f3f4e785f.png', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-04 20:36:01.185+00', 5, false, 'Borracheiro de 69 anos morre esmagado por caminhão em Lagarto, Sergipe', 'Um borracheiro de 69 anos faleceu na manhã desta quinta-feira (3) após ser esmagado por um caminhão no município de Lagarto, localizado na região Centro-Sul de Sergipe. O acidente ocorreu en...'),
  ('664b1ef7-b1b2-429f-bfb0-e40acbe9a7f1', 'Justiça determina prazo de 72h para Prefeitura de Cícero Dantas pagar salários', 'justica-determina-prazo-de-72h-para-prefeitura-de-cicero-dantas-pagar-salarios', 'A Justiça determinou que a Prefeitura de Cícero Dantas pague os salários de agosto, com foco nos servidores da Saúde, em até 72 horas. A decisão atende a pedido do sindicato, sob pena de multa diária de R$ 3 mil.', 'A Justiça determinou que a Prefeitura de Cícero Dantas, na Bahia, comprove, no prazo máximo de 72 horas, o pagamento integral dos salários referentes ao mês de agosto. A decisão enfatiza a prioridade aos servidores lotados na Secretaria Municipal de Saúde, que, segundo informações, têm sido os mais afetados por atrasos.

A medida judicial foi tomada em resposta a um pedido formal apresentado pelo sindicato dos servidores do município. O sindicato relatou não apenas o atraso na folha de pagamento de agosto, mas também um histórico de irregularidades nos pagamentos aos profissionais da área da Saúde. Caso a gestão municipal não cumpra a determinação judicial dentro do período estipulado, será aplicada uma multa diária de R$ 3 mil. O valor total da penalidade poderá atingir o limite de R$ 60 mil. Para comprovar a regularização, a Prefeitura deverá apresentar documentos como a folha salarial e os respectivos comprovantes de pagamento. Até o momento, a administração municipal não emitiu qualquer posicionamento oficial a respeito da decisão judicial.', 'https://imagemlink.cleissoncardoso.com/uploads/a7c98c09-778a-4da2-820f-58c1d4e0f9ab.png', '1bff82e6-6033-4d75-8d04-e26d976c0a05', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-04 21:12:30.238848+00', 1041, true, 'Justiça exige que Prefeitura de Cícero Dantas pague salários em 72h', 'Prefeitura de Cícero Dantas tem 72 horas para comprovar pagamento integral dos salários de agosto, atendendo a decisão judicial. Prazo visa servidores da Saúde e evita multa.'),
  ('b1f31991-c8ba-4593-9ebc-66acda8c1bf5', 'Homem fica ferido em acidente de moto com suspeita de embriaguez em Ribeira do Pombal', 'homem-fica-ferido-em-acidente-de-moto-com-suspeita-de-embriaguez-em-ribeira-do', 'Um homem ficou ferido após um acidente de motocicleta na Avenida Mirandela, em Ribeira do Pombal. Ele colidiu contra o canteiro central e apresentava sinais de embriaguez, segundo informações preliminares. O motociclista foi socorrido e encaminhado ao HGST, enquanto as autoridades apuram o caso.', 'Um homem ficou ferido na Avenida Mirandela, em Ribeira do Pombal, após perder o controle de sua motocicleta e colidir contra o canteiro central. O acidente ocorreu em frente ao Clube Visgueira. Segundo informações preliminares levantadas no local, o motociclista apresentava sinais visíveis de embriaguez no momento do ocorrido. Populares que testemunharam a colisão prestaram os primeiros socorros ao indivíduo enquanto aguardavam a chegada das equipes especializadas.

A Guarda Civil Municipal (GCM) foi acionada e compareceu ao local para prestar apoio à ocorrência. Em seguida, equipes do Serviço de Atendimento Móvel de Urgência (SAMU) realizaram o atendimento médico ao ferido, que foi posteriormente encaminhado para a emergência do Hospital Geral Santa Tereza (HGST). As circunstâncias exatas que levaram ao acidente serão devidamente apuradas pelas autoridades competentes.', 'https://imagemlink.cleissoncardoso.com/uploads/4abb3c42-59ef-4cb5-b266-4b3d1a4a1476.png', '7d34292b-4217-4571-ba21-f7aa996aa1d3', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-05 16:23:20.94804+00', 1034, true, 'Acidente de moto em Ribeira do Pombal deixa homem ferido; embriaguez é suspeita', 'Um motociclista ficou ferido em Ribeira do Pombal após colidir com canteiro na Av. Mirandela. Ele apresentava sinais de embriaguez e foi socorrido. O caso será apurado.'),
  ('cfb091e8-3976-45fe-a562-5d33d55e38ee', 'Jovem capota carro na BR-410 e é socorrida em Ribeira do Pombal', 'jovem-capota-carro-na-br-410-e-e-socorrida-em-ribeira-do-pombal', 'Uma jovem de 24 anos capotou seu Fiat Mobi no km 15 da BR-410. Consciente e com escoriações, foi socorrida pelo SAMU e encaminhada ao HGST em Ribeira do Pombal. As causas ainda serão apuradas.', 'Um acidente de trânsito resultou no capotamento de um veículo Fiat Mobi na tarde deste sábado (5), no quilômetro 15 da BR-410. O automóvel era conduzido por uma jovem de 24 anos, natural de Quijingue, que estava em deslocamento de Cipó com destino a Euclides da Cunha. De acordo com as informações apuradas no local, a motorista fazia uso do cinto de segurança no momento do ocorrido. Ela sofreu escoriações e queixava-se de dores, mas estava consciente durante o atendimento inicial.

A Polícia Rodoviária Federal (PRF) foi prontamente acionada e compareceu ao local do acidente para as providências cabíveis. A equipe da PRF solicitou o apoio do Serviço de Atendimento Móvel de Urgência (SAMU), que prestou os primeiros socorros à vítima. A jovem foi então encaminhada, em estado consciente, ao Hospital Geral Santa Tereza (HGST), localizado em Ribeira do Pombal, para avaliação médica mais detalhada. Moradores das proximidades, impressionados com a cena, descreveram o acidente como algo cinematográfico. As causas que levaram à saída de pista do veículo ainda serão investigadas pelas autoridades competentes.', 'https://imagemlink.cleissoncardoso.com/uploads/38ac438b-980e-403b-a9e0-3beaa8710320.png', '7d34292b-4217-4571-ba21-f7aa996aa1d3', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-06 00:50:34.015863+00', 1050, true, 'Acidente na BR-410: Jovem capota carro e é levada a hospital em Ribeira do Pombal', 'Uma jovem capotou seu Fiat Mobi na BR-410, entre Cipó e Euclides da Cunha. Consciente e com escoriações, foi socorrida em Ribeira do Pombal.'),
  ('e8dee667-d57c-4fbc-937c-3f4b1431d04d', 'Acidente entre caminhão e carreta mobiliza equipes na BR em Ribeira do Pombal', 'acidente-entre-caminhao-e-carreta-mobiliza-equipes-na-br-em-ribeira-do-pombal', 'Um acidente entre um caminhão e uma carreta foi registrado na BR que liga Ribeira do Pombal a Tucano. O sinistro ocorreu na saída da sede pombalense, e as autoridades apuram as circunstâncias e o estado dos condutores, com PRF e equipes de resgate no local.', 'Um acidente de trânsito envolvendo um caminhão e uma carreta foi registrado em um trecho da BR que conecta os municípios de Ribeira do Pombal e Tucano. O sinistro ocorreu especificamente na saída da sede de Ribeira do Pombal, atraindo a atenção de motoristas que trafegavam pela rodovia.

As circunstâncias exatas da colisão e o estado de saúde dos condutores envolvidos ainda estão sendo apurados pelas autoridades competentes. Equipes de resgate e a Polícia Rodoviária Federal (PRF) foram acionadas e compareceram ao local para prestar o atendimento necessário, orientar o tráfego e garantir a segurança viária na região.', 'https://imagemlink.cleissoncardoso.com/uploads/52b92c94-4ace-4a1b-8044-59e53fcac5d8.png', '7d34292b-4217-4571-ba21-f7aa996aa1d3', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-06 18:06:45.119915+00', 1075, true, 'Acidente entre caminhão e carreta na BR em Ribeira do Pombal', 'Um acidente envolvendo um caminhão e uma carreta foi registrado na BR que liga Ribeira do Pombal a Tucano. Equipes de resgate e a PRF foram acionadas para apurar as causas e o estado dos condutores.'),
  ('c667ec51-3ecf-47cf-bb89-4271b5370902', 'Médica é encontrada morta em apartamento em Maringá; marido é suspeito e bebê estava ao lado', 'medica-e-encontrada-morta-em-apartamento-em-maringa-marido-e-suspeito-e-bebe-est', 'Uma médica de 37 anos, identificada como Gassi Mazia, foi encontrada morta neste domingo, 6 de agosto, em seu apartamento na cidade de Maringá, no Norte do Paraná. Ela residia no local com a...', 'Uma médica de 37 anos, identificada como Gassi Mazia, foi encontrada morta neste domingo, 6 de agosto, em seu apartamento na cidade de Maringá, no Norte do Paraná. Ela residia no local com a família. João Vitor Domingues Romeiro, de 25 anos, marido da vítima, é considerado o principal suspeito do crime. Um bebê de oito meses, filho do casal, estava ao lado do corpo da mãe, sem ferimentos, e foi acolhido por familiares. O choro da criança alertou os vizinhos, que acionaram as autoridades, levando à descoberta da vítima já sem vida.

João Romeiro foi preso em flagrante em Mandaguari, após ser encontrado na casa da mãe com ferimentos no pescoço. De acordo com informações da polícia, ele teria esfaqueado Gassi Mazia durante uma discussão na noite de sábado, 5 de agosto, e, em seguida, abandonou o apartamento. Após sua localização, o suspeito precisou de atendimento médico. A Polícia Militar informou que o homem confessou o assassinato a testemunhas. João responderá pelo crime de feminicídio e está internado em um hospital sob escolta policial, enquanto a Polícia Civil investiga o caso.', 'https://cdn.atarde.com.br/img/Artigo-Destaque/1400000/medica-e-encontrada-morta-em-apartamento-com-bebe-0140114000202609061707.jpg?xid=7206904', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-07 13:01:02.738+00', 2, false, 'Médica é encontrada morta em apartamento em Maringá; marido é suspeito e bebê estava ao lado', 'Uma médica de 37 anos, identificada como Gassi Mazia, foi encontrada morta neste domingo, 6 de agosto, em seu apartamento na cidade de Maringá, no Norte do Paraná. Ela residia no local com a...'),
  ('5b0563f4-7559-467a-8f04-37bb3e2a6a70', 'PM identifica suspeitos de matar jovem em tentativa de assalto no Imbuí', 'pm-identifica-suspeitos-de-matar-jovem-em-tentativa-de-assalto-no-imbui', 'Na manhã desta segunda-feira (7), o comandante-geral da Polícia Militar, Coronel Magalhães, informou a identificação dos suspeitos pelo assassinato de Brenda Nicole Alves. A jovem foi morta ...', 'Na manhã desta segunda-feira (7), o comandante-geral da Polícia Militar, Coronel Magalhães, informou a identificação dos suspeitos pelo assassinato de Brenda Nicole Alves. A jovem foi morta durante uma tentativa de assalto na madrugada do último domingo (6), no bairro do Imbuí, em Salvador. Brenda foi atingida com um tiro no rosto enquanto estava na garupa de uma motocicleta na Avenida Jorge Amado, próximo ao motel Fantasy. As informações preliminares indicam que ela teria se recusado a entregar o celular ao ser abordada pelo assaltante, que também estava em uma motocicleta.

O caso repercutiu e o governador Jerônimo Rodrigues (PT) cobrou publicamente rigor nas investigações por meio de suas redes sociais. "Determinei à SSP e à Polícia Civil que não descansem até esse assassino estar preso. É por essas famílias que eu trabalho, e é por elas que a Bahia não vai se curvar à violência", publicou o governador. A vítima, Brenda Nicole Alves Brandão, era filha dos sargentos da Polícia Militar da Bahia (PM-BA), RR Brandão e Rose Tatiane, esta última lotada no Batalhão de Policiamento Tático de BTS/Rondesp Atlântico. A Polícia Militar segue com as apurações para a prisão dos envolvidos.', 'https://www.bnews.com.br/media/_versions/2026/09/design-sem-nome-21_widexl.png', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-07 13:15:19.697+00', 2, false, 'PM identifica suspeitos de matar jovem em tentativa de assalto no Imbuí', 'Na manhã desta segunda-feira (7), o comandante-geral da Polícia Militar, Coronel Magalhães, informou a identificação dos suspeitos pelo assassinato de Brenda Nicole Alves. A jovem foi morta ...'),
  ('64adf6a1-c224-4014-b159-a6010c5b9a7b', 'Filha é presa suspeita de matar o próprio pai em Rio Verde (GO)', 'filha-e-presa-suspeita-de-matar-o-proprio-pai-em-rio-verde-go', 'Uma mulher foi presa em flagrante no domingo (6/9) suspeita de homicídio doloso contra o próprio pai. O crime ocorreu na residência da família, localizada no Setor Dona Gercina, em Rio Verde...', 'Uma mulher foi presa em flagrante no domingo (6/9) suspeita de homicídio doloso contra o próprio pai. O crime ocorreu na residência da família, localizada no Setor Dona Gercina, em Rio Verde, no interior de Goiás. De acordo com a Polícia Militar do estado, a detida confessou a autoria do ato e alegou ter agido em legítima defesa, versão que será analisada durante as investigações.

Ao chegarem ao local, os policiais encontraram a vítima caída dentro da casa, apresentando lesões por arma de fogo no tórax e no abdômen. O corpo foi recolhido para os procedimentos de praxe e a suspeita foi conduzida à 8ª Delegacia Regional de Polícia, onde permaneceu à disposição do Poder Judiciário.

O caso está sob investigação da Polícia Civil de Goiás, que apura as circunstâncias exatas da morte e a veracidade da alegação de legítima defesa apresentada pela suspeita. Até o momento, não há informações sobre inquérito policial específico ou indícios adicionais que possam esclarecer a motivação do conflito familiar. As autoridades recomendam cautela na divulgação de detalhes, aguardando a conclusão das diligências periciais e investigativas para determinar a responsabilidade penal da envolvida.', 'https://i.metroimg.com/8FG0Pm6GIzDAtXg6E_UEU4b49bMxsn861VUEho4ewMo/rs:fill:1200:800:1/g:no/q:85/f:webp/plain/https://images.metroimg.com/709b04a1-whatsapp-image-2025-12-26-at-12.03.40.jpeg', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-07 13:15:27.548+00', 5, false, 'Filha é presa suspeita de matar o próprio pai em Rio Verde (GO)', 'Uma mulher foi presa em flagrante no domingo (6/9) suspeita de homicídio doloso contra o próprio pai. O crime ocorreu na residência da família, localizada no Setor Dona Gercina, em Rio Verde...'),
  ('ffa562ed-a78a-4c10-a364-5bfc84594223', 'Vereador de Salvador desmaia em desfile de 7 de Setembro', 'vereador-de-salvador-desmaia-em-desfile-de-7-de-setembro', 'O vereador de Salvador Sandro Bahiense, filiado ao partido Progressistas, desmaiou na manhã desta segunda-feira (07) durante o desfile cívico de 7 de Setembro. O incidente ocorreu especifica...', 'O vereador de Salvador Sandro Bahiense, filiado ao partido Progressistas, desmaiou na manhã desta segunda-feira (07) durante o desfile cívico de 7 de Setembro. O incidente ocorreu especificamente na área do Campo Grande, um dos principais pontos da celebração em Salvador, e rapidamente atraiu a atenção. O momento exato em que o político passou mal foi registrado em vídeo, com as imagens obtidas e divulgadas com exclusividade pelo portal BNews.

As filmagens, capturadas pelo repórter de política Anderson Ramos, detalham a cena em que o vereador Bahiense marchava junto a um pelotão do Corpo de Bombeiros. Ele é visto aparentando tontura e, na sequência, ao tentar buscar apoio em pessoas que estavam próximas, desequilibrou-se e caiu no chão. O socorro foi imediato: os próprios Bombeiros presentes no local agiram rapidamente para prestar os primeiros atendimentos. Bahiense, que atualmente ocupa uma cadeira na Câmara Municipal e também é candidato a deputado federal nas eleições deste ano, foi então encaminhado para um hospital particular da cidade. Sua esposa, que acompanhava o evento, esteve ao seu lado durante todo o processo. Até o momento, não foram divulgadas informações adicionais sobre o quadro de saúde do político.', 'https://www.bnews.com.br/media/_versions/2026/09/bahiense_69093801881_widexl.jpg', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-07 13:15:39.115+00', 0, false, 'Vereador de Salvador desmaia em desfile de 7 de Setembro', 'O vereador de Salvador Sandro Bahiense, filiado ao partido Progressistas, desmaiou na manhã desta segunda-feira (07) durante o desfile cívico de 7 de Setembro. O incidente ocorreu especifica...'),
  ('bde1ddc0-8687-4e98-8fe2-7e4a5a3fb7b2', 'Banco Central proíbe anúncios em comprovantes de Pix para combater golpes a partir de 2027', 'banco-central-proibe-anuncios-em-comprovantes-de-pix-para-combater-golpes-a-part', 'O Banco Central (BC) anunciou a proibição de anúncios e links nos comprovantes de Pix, com a medida entrando em vigor a partir de março de 2027. A decisão tem como principal objetivo combate...', 'O Banco Central (BC) anunciou a proibição de anúncios e links nos comprovantes de Pix, com a medida entrando em vigor a partir de março de 2027. A decisão tem como principal objetivo combater a crescente onda de golpes virtuais, nos quais criminosos utilizam comprovantes falsos que imitam as propagandas bancárias para roubar dados e senhas de vítimas. Antes da mudança, era comum que bancos aproveitassem o momento final da transação para oferecer outros serviços, como parcelamento do próprio Pix, seguros contra roubo de celular ou programas de indicação de amigos para cashbacks.

Essas ofertas, que apareciam na tela ou no arquivo do comprovante, foram replicadas por golpistas que criavam links enganosos, semelhantes aos oficiais, para direcionar usuários a páginas fraudulentas. Com a nova regra, todos os bancos e aplicativos serão impedidos de incluir qualquer tipo de publicidade nos documentos do Pix, tornando mais fácil identificar um comprovante fraudulento. O recibo passará a exibir apenas informações essenciais como quem pagou, quem recebeu, o valor e a data da transação. Além disso, o BC determinou melhorias no Mecanismo Especial de Devolução (MED), ferramenta para recuperação de valores em casos de fraude, que terá processos mais simples e linguagem acessível. Outra novidade é o aviso obrigatório na tela do aplicativo sempre que houver mudança nos dados de um contato Pix salvo, como conta ou nome, aumentando a segurança dos usuários.', 'https://midias.correio24horas.com.br/2026/02/07/pix-3131350-article.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-07 13:43:41.946+00', 3, false, 'Banco Central proíbe anúncios em comprovantes de Pix para combater golpes a partir de 2027', 'O Banco Central (BC) anunciou a proibição de anúncios e links nos comprovantes de Pix, com a medida entrando em vigor a partir de março de 2027. A decisão tem como principal objetivo combate...'),
  ('65565d89-cb49-4310-9e95-c90066f4f51a', 'André Mendonça determina afastamento do diretor-geral da Polícia Federal', 'andre-mendonca-determina-afastamento-do-diretor-geral-da-policia-federal', 'O ministro do Supremo Tribunal Federal (STF), André Mendonça, determinou nesta terça-feira, 8, o afastamento preventivo de Andrei Rodrigues do cargo de diretor-geral da Polícia Federal (PF)....', 'O ministro do Supremo Tribunal Federal (STF), André Mendonça, determinou nesta terça-feira, 8, o afastamento preventivo de Andrei Rodrigues do cargo de diretor-geral da Polícia Federal (PF). A decisão judicial também incluiu o afastamento do delegado Leandro Almada, diretor de inteligência policial da PF, e a suspensão da produção e compartilhamento de relatórios de inteligência que analisem atos jurisdicionais, de advocacia pública ou de polícia judiciária. Mendonça justificou a medida afirmando que visa permitir que integrantes da Corte, o advogado-geral da União, Jorge Messias, e servidores da PF “exerçam suas atribuições sem constrangimentos ilegais”, apontando um "risco efetivo" de utilização indevida de prerrogativas funcionais.

A determinação de Mendonça ocorre em um cenário de escalada da crise no STF, envolvendo o próprio ministro e Alexandre de Moraes. A decisão foi tomada após Moraes, conforme o texto, ter usado relatórios apócrifos da Polícia Federal para acusar Mendonça de abuso de autoridade, crime de responsabilidade e improbidade administrativa em casos relacionados ao Banco Master e ao INSS. Andrei Rodrigues, com mais de duas décadas na PF, assumiu a direção-geral em 2023, indicado por Flávio Dino e aprovado pelo presidente Luiz Inácio Lula da Silva, após ter chefiado a segurança de campanhas presidenciais.', 'https://cdn.atarde.com.br/img/Artigo-Destaque/1400000/andre-mendonca-manda-afastar-chefe-da-policia-fede0140128100202609080915.jpg?xid=7209807', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-08 13:07:24.572+00', 3, false, 'André Mendonça determina afastamento do diretor-geral da Polícia Federal', 'O ministro do Supremo Tribunal Federal (STF), André Mendonça, determinou nesta terça-feira, 8, o afastamento preventivo de Andrei Rodrigues do cargo de diretor-geral da Polícia Federal (PF)....'),
  ('659dcd1b-833c-4845-95c0-65b294868a1a', 'Detran-BA abre inscrições para 20 mil CNHs gratuitas em outubro de 2026', 'detran-ba-abre-inscricoes-para-20-mil-cnhs-gratuitas-em-outubro-de-2026', 'O Departamento Estadual de Trânsito da Bahia (Detran-BA) vai abrir uma nova seleção para o programa "CNH da Gente", oferecendo 20 mil vagas gratuitas para quem deseja obter a primeira Cartei...', 'O Departamento Estadual de Trânsito da Bahia (Detran-BA) vai abrir uma nova seleção para o programa "CNH da Gente", oferecendo 20 mil vagas gratuitas para quem deseja obter a primeira Carteira Nacional de Habilitação (CNH) no estado. A iniciativa contempla moradores de todos os municípios baianos, permitindo a habilitação nas categorias A (motocicletas) ou B (automóveis), e cobre as principais despesas do processo, como taxas de habilitação, exames de aptidão física e mental, avaliação psicológica, curso e prova teórica, aulas práticas e o exame de direção. As inscrições serão realizadas exclusivamente pela internet, entre 1º e 15 de outubro de 2026, sem custo de cadastro.

Para concorrer a uma das vagas, o candidato deve atender a critérios como ter mais de 18 anos, saber ler e escrever, residir na Bahia, possuir CPF e documento de identidade, e estar inscrito no Cadastro Único (CadÚnico) com atualização até 8 de maio de 2026. É fundamental que o interessado não tenha impedimento judicial para obter a CNH, nem possua habilitação anterior ou processo em andamento. Após a divulgação das inscrições aceitas em 26 de outubro de 2026, a lista final dos candidatos selecionados e classificados será publicada em 16 de novembro de 2026. Os aprovados terão de 25 de novembro a 14 de dezembro de 2026 para comparecer a uma unidade do Detran e iniciar formalmente o processo, que deverá ser concluído em até 12 meses. Há previsão de convocações complementares para preencher eventuais vagas abertas.', 'https://cdn.atarde.com.br/img/Artigo-Destaque/1390000/saiba-quais-os-10-carros-mais-roubados-no-brasil-e0139009600202605261704.jpg?xid=7208499', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-08 13:07:58.822+00', 0, false, 'Detran-BA abre inscrições para 20 mil CNHs gratuitas em outubro de 2026', 'O Departamento Estadual de Trânsito da Bahia (Detran-BA) vai abrir uma nova seleção para o programa "CNH da Gente", oferecendo 20 mil vagas gratuitas para quem deseja obter a primeira Cartei...'),
  ('63caa77b-799b-452e-8441-657597852f95', 'Padre é preso em Praia Grande por suspeita de estuprar coroinha de 19 anos', 'padre-e-preso-em-praia-grande-por-suspeita-de-estuprar-coroinha-de-19-anos', 'Um padre de 58 anos foi preso na última sexta-feira, 4, em Praia Grande, no litoral de São Paulo, sob suspeita de estuprar uma coroinha de 19 anos. Jucelino de Oliveira, o religioso detido, ...', 'Um padre de 58 anos foi preso na última sexta-feira, 4, em Praia Grande, no litoral de São Paulo, sob suspeita de estuprar uma coroinha de 19 anos. Jucelino de Oliveira, o religioso detido, é acusado de ter oferecido bebida alcoólica à vítima e ao seu namorado, que também era coroinha, antes do alegado crime. Segundo relatos, os jovens frequentavam a igreja onde Jucelino atuava há cerca de três meses, acompanhavam-no em cerimônias e frequentavam sua residência. A vítima relatou em depoimento que o padre tinha o hábito de insistir para que consumissem álcool, mesmo após ela mencionar ter problemas com a bebida.

Em uma ocasião sem data definida, o casal teria dormido na casa do padre. Neste dia, durante um abraço, Jucelino teria encostado sua genitália na perna da jovem e, aproveitando-se da sonolência do namorado, apalpado os seios dela por dentro da blusa. A vítima também mencionou que o religioso já havia oferecido presentes, ajuda financeira e até sugerido que o casal morasse em sua casa. Além da prisão, foram impostas medidas cautelares, exigindo que o padre mantenha uma distância mínima de 300 metros da mulher e evite locais por ela frequentados. O advogado de Jucelino de Oliveira, João Paulo Silva Rocha, afirmou ao G1 que a prisão é de "natureza temporária e exclusivamente cautelar" e "não representa condenação". A Diocese de Santos, em nota, informou ter conhecimento do mandado e reiterou confiança na Justiça para o esclarecimento dos fatos, garantindo que "serão tomadas as providências cabíveis".', 'https://cdn.atarde.com.br/img/Artigo-Destaque/1400000/padre-e-preso-suspeito-de-estuprar-coroinha-apos-d0140118300202609070943.png?xid=7208073', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-08 13:08:46.734+00', 2, false, 'Padre é preso em Praia Grande por suspeita de estuprar coroinha de 19 anos', 'Um padre de 58 anos foi preso na última sexta-feira, 4, em Praia Grande, no litoral de São Paulo, sob suspeita de estuprar uma coroinha de 19 anos. Jucelino de Oliveira, o religioso detido, ...'),
  ('30c87d84-ac6d-4c86-a47e-58f520261748', 'Pandeirista morre em acidente de trânsito na Zona Sul de Porto Alegre', 'pandeirista-morre-em-acidente-de-transito-na-zona-sul-de-porto-alegre', 'O músico Diego Sanches, de 42 anos, conhecido pelo apelido Branco, faleceu após um acidente de trânsito ocorrido na última semana no bairro Tristeza, na Zona Sul de Porto Alegre. O pandeiris...', 'O músico Diego Sanches, de 42 anos, conhecido pelo apelido Branco, faleceu após um acidente de trânsito ocorrido na última semana no bairro Tristeza, na Zona Sul de Porto Alegre. O pandeirista estava a caminho de um bar onde realizaria uma apresentação quando o veículo em que viajava foi atingido em uma colisão.

Segundo a Polícia Civil, Diego ocupava o banco do passageiro de um Peugeot 208 quando o carro sofreu uma batida lateral na esquina da Avenida Wenceslau Escobar com a Rua Doutor Barcelos. Ele foi socorrido, mas não resistiu aos ferimentos e morreu dentro da ambulância. Os outros dois motoristas envolvidos também ficaram feridos e receberam atendimento médico. O condutor do Peugeot 208 recusou-se a realizar o teste do bafômetro. A dinâmica do acidente ainda está sendo investigada, com análise de câmeras de segurança para determinar as causas.

Diego iniciou sua carreira musical na adolescência e integrou diversos grupos de samba e pagode, como Nova Versão, Nossa Casa, Samba & Amizade e Pagode do Zico. Desde 2017, fazia parte do grupo D’Kara Nova, atuando como pandeirista e cantor.', 'https://media-manager.noticiasaominuto.com.br/960/naom_6aa037862dc7f.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-08 19:24:32.201+00', 3, false, 'Pandeirista morre em acidente de trânsito na Zona Sul de Porto Alegre', 'O músico Diego Sanches, de 42 anos, conhecido pelo apelido Branco, faleceu após um acidente de trânsito ocorrido na última semana no bairro Tristeza, na Zona Sul de Porto Alegre. O pandeiris...'),
  ('f706acb5-37b2-4ce8-bb1b-a602fce31937', 'Golpe da Prova de Vida do INSS tenta limpar contas de aposentados', 'golpe-da-prova-de-vida-do-inss-tenta-limpar-contas-de-aposentados', 'A Prova de Vida do INSS voltou a ser utilizada como isca por criminosos para aplicar golpes contra aposentados e pensionistas. As abordagens simulam contatos oficiais e tentam obter dados pe...', 'A Prova de Vida do INSS voltou a ser utilizada como isca por criminosos para aplicar golpes contra aposentados e pensionistas. As abordagens simulam contatos oficiais e tentam obter dados pessoais, bancários e senhas das vítimas, sob a alegação de que o benefício poderá ser suspenso caso a comprovação não seja feita imediatamente. O INSS reforçou esse alerta em agosto e novamente em 31 de agosto de 2026.

Uma das estratégias envolve mensagens sobre supostas pendências no benefício, utilizando SMS, WhatsApp ou ligações telefônicas. Criminosos se apresentam como funcionários do instituto, alegando falsa necessidade de atualização cadastral, e enviam links para páginas fraudulentas que imitam serviços governamentais. O INSS esclarece que não solicita senhas, dados sensíveis ou transações bancárias por mensagens ou ligações, nem envia comunicações de interrupção de benefícios por falta de Prova de Vida. A comprovação ocorre principalmente de maneira automática, e a situação pode ser consultada pelo aplicativo Meu INSS ou pela Central 135. Vítimas de fraude devem guardar evidências e registrar boletim de ocorrência.', 'https://media-manager.noticiasaominuto.com.br/960/naom_5f68639d5626f.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-08 19:24:46.419+00', 3, false, 'Golpe da Prova de Vida do INSS tenta limpar contas de aposentados', 'A Prova de Vida do INSS voltou a ser utilizada como isca por criminosos para aplicar golpes contra aposentados e pensionistas. As abordagens simulam contatos oficiais e tentam obter dados pe...'),
  ('31554493-da20-442f-ba22-9bfd85f2688f', 'Banco Central: R$ 5,6 bilhões em valores esquecidos estão disponíveis para 23,6 milhões de pessoas', 'banco-central-r-5-6-bilhoes-em-valores-esquecidos-estao-disponiveis-para-23-6-mi', 'O Banco Central (BC) atualizou os dados nesta terça-feira (8), informando que R$ 5,64 bilhões em "recursos esquecidos" por clientes ainda estão disponíveis em instituições financeiras. Este ...', 'O Banco Central (BC) atualizou os dados nesta terça-feira (8), informando que R$ 5,64 bilhões em "recursos esquecidos" por clientes ainda estão disponíveis em instituições financeiras. Este montante, contabilizado até julho deste ano, pode ser resgatado por 23,6 milhões de pessoas físicas, incluindo falecidas, e empresas. O sistema do BC permite a consulta desses valores, e o único site oficial para verificar e solicitar a devolução é o https://valoresareceber.bcb.gov.br.

Em maio, o governo havia anunciado a intenção de usar entre R$ 5 bilhões e R$ 8 bilhões desses recursos para viabilizar descontos no programa Desenrola 2.0. No final do mesmo mês, cerca de R$ 5,7 bilhões foram transferidos para o Fundo de Garantia de Operações (FGO), com o objetivo de oferecer garantias às instituições financeiras e cobrir eventuais inadimplências. O governo garantiu que 10% do saldo transferido ficaria disponível para cobrir pedidos de resgate pelos correntistas. Em junho, o Tribunal de Contas da União (TCU) iniciou uma apuração sobre o uso desses recursos fora do orçamento público, levantando questionamentos sobre a conformidade com os limites de gastos anuais da União.', 'https://www.bahianoticias.com.br/fotos/principal_noticias/320875/IMAGEM_NOTICIA_9.jpg?checksum=1788881885', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-09 11:18:55.112+00', 3, false, 'Banco Central: R$ 5,6 bilhões em valores esquecidos estão disponíveis para 23,6 milhões de pessoas', 'O Banco Central (BC) atualizou os dados nesta terça-feira (8), informando que R$ 5,64 bilhões em "recursos esquecidos" por clientes ainda estão disponíveis em instituições financeiras. Este ...'),
  ('94b186ec-2349-45cc-b80c-4d3bbc609f4e', 'Flávio Dino reconduz Andrei Rodrigues à PF e anula decisão de Mendonça', 'flavio-dino-reconduz-andrei-rodrigues-a-pf-e-anula-decisao-de-mendonca', 'O ministro Flávio Dino, do Supremo Tribunal Federal (STF), determinou nesta quarta-feira (9) a recondução de Andrei Rodrigues ao cargo de diretor-geral da Polícia Federal (PF) e de Leandro A...', 'O ministro Flávio Dino, do Supremo Tribunal Federal (STF), determinou nesta quarta-feira (9) a recondução de Andrei Rodrigues ao cargo de diretor-geral da Polícia Federal (PF) e de Leandro Almada da Costa à diretoria de Inteligência Policial. A decisão derruba liminares concedidas anteriormente pelo ministro André Mendonça e proíbe a imposição de novas medidas cautelares pessoais contra os agentes, desde que fundamentadas no cumprimento regular de suas atribuições ou de ordens judiciais.

Na fundamentação, Dino apontou vício formal insanável na decisão anterior, alegando que o pedido de afastamento partiu do Partido Novo, entidade que não possui legitimidade para requerer medidas cautelares em investigações penais, conforme o Código de Processo Penal. O ministro ressaltou que Rodrigues limitou-se a cumprir ordens expedidas por Alexandre de Moraes e que a suspensão de suas funções colocava em risco a apuração de crimes graves. Dino também destacou a falta de competência monocrática de Mendonça para paralisar investigações em causa afetada à Presidência do STF, instaurada pelo ministro Edson Fachin.', 'https://cdn.atarde.com.br/img/Artigo-Destaque/1400000/flavio-dino-desafia-andre-mendonca-e-reconduz-andr0140142800202609091031.jpg?xid=7212174', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-09 15:08:37.956+00', 3, false, 'Flávio Dino reconduz Andrei Rodrigues à PF e anula decisão de Mendonça', 'O ministro Flávio Dino, do Supremo Tribunal Federal (STF), determinou nesta quarta-feira (9) a recondução de Andrei Rodrigues ao cargo de diretor-geral da Polícia Federal (PF) e de Leandro A...'),
  ('91c6ab3f-e969-4135-aa3b-19ede7eff11f', 'Lula cobra explicações do STF sobre crise institucional e Caso Master', 'lula-cobra-explicacoes-do-stf-sobre-crise-institucional-e-caso-master', 'O presidente Luiz Inácio Lula da Silva (PT) cobrou publicamente explicações do Supremo Tribunal Federal (STF) nesta quarta-feira, 9 de setembro, em meio à crise institucional que tem afetado...', 'O presidente Luiz Inácio Lula da Silva (PT) cobrou publicamente explicações do Supremo Tribunal Federal (STF) nesta quarta-feira, 9 de setembro, em meio à crise institucional que tem afetado a Corte. As demandas do presidente surgem após os desdobramentos do chamado Caso Master, que envolveu o ministro Alexandre de Moraes. Em uma publicação na rede social X (antigo Twitter), Lula declarou que o povo brasileiro "precisa de explicações e medidas imediatas para enfrentar a crise institucional que tomou conta do Poder Judiciário".

O presidente também exigiu mais transparência e o combate aos vazamentos seletivos que, segundo ele, impactam campanhas eleitorais, relembrando a Operação Spoofing, citada pelo ex-ministro Ricardo Lewandowski. Lula foi enfático ao pedir a "quebra completa do sigilo das investigações de todos os envolvidos no caso Master, seja quem for, doa a quem doer. O Brasil precisa saber a verdade". Paralelamente a essas declarações, a sessão do plenário do STF agendada para o mesmo dia foi suspensa pelo ministro presidente Edson Fachin, horas depois de Flávio Dino determinar a recondução de Andrei Rodrigues e Leandro Almada à cúpula da Polícia Federal, em um momento de acentuada crise e divisão interna na Corte.', 'https://cdn.atarde.com.br/img/Artigo-Destaque/1400000/lula-convoca-ministros-para-discutir-afastamento-d0140131500202609081223.jpg?xid=7212521', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-09 15:09:14.037+00', 3, false, 'Lula cobra explicações do STF sobre crise institucional e Caso Master', 'O presidente Luiz Inácio Lula da Silva (PT) cobrou publicamente explicações do Supremo Tribunal Federal (STF) nesta quarta-feira, 9 de setembro, em meio à crise institucional que tem afetado...'),
  ('d9fc034f-4850-45c5-b38f-5728d741ee03', 'Concurso da Polícia Civil da Bahia prorroga inscrições para 750 vagas', 'concurso-da-policia-civil-da-bahia-prorroga-inscricoes-para-750-vagas', 'As inscrições para o concurso público da Polícia Civil da Bahia foram prorrogadas até domingo, 13. O certame, organizado pelo Instituto AOCP, oferece 750 vagas distribuídas entre os cargos d...', 'As inscrições para o concurso público da Polícia Civil da Bahia foram prorrogadas até domingo, 13. O certame, organizado pelo Instituto AOCP, oferece 750 vagas distribuídas entre os cargos de delegado (100), escrivão (150) e investigador (500). Os candidatos terão até a próxima segunda-feira, 14, para efetuar o pagamento da taxa de inscrição, que é de R$ 220 para o cargo de delegado e R$ 190 para investigador e escrivão.

Todos os postos exigem formação de nível superior, sendo o bacharelado em Direito obrigatório apenas para delegados. A remuneração varia até R$ 16,4 mil para delegados e R$ 6,4 mil para investigadores e escrivães, com jornada de 40 horas semanais. A seleção ocorrerá em três etapas: provas objetivas, prova discursiva e avaliação de títulos. As avaliações estão previstas para o dia 6 de dezembro, em Salvador, e o edital reserva 5% das vagas para pessoas com deficiência e 30% para candidatos negros.', 'https://cdn.atarde.com.br/img/Artigo-Destaque/1400000/inscricoes-para-concurso-da-policia-civil-da-bahia0140128500202609080945.jpg?xid=7210711', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-09 15:09:24.684+00', 0, false, 'Concurso da Polícia Civil da Bahia prorroga inscrições para 750 vagas', 'As inscrições para o concurso público da Polícia Civil da Bahia foram prorrogadas até domingo, 13. O certame, organizado pelo Instituto AOCP, oferece 750 vagas distribuídas entre os cargos d...'),
  ('c7b1eacc-6560-4e1b-9962-fc6780e800c8', 'PIB da Bahia cresce 2,3% no 2º trimestre e acumula alta de 1,3% no semestre', 'pib-da-bahia-cresce-2-3-no-2-trimestre-e-acumula-alta-de-1-3-no-semestre', 'O Produto Interno Bruto (PIB) da Bahia registrou crescimento de 2,3% no segundo trimestre de 2026, em comparação com o mesmo período do ano anterior. Com esse desempenho, a economia estadual...', 'O Produto Interno Bruto (PIB) da Bahia registrou crescimento de 2,3% no segundo trimestre de 2026, em comparação com o mesmo período do ano anterior. Com esse desempenho, a economia estadual acumulou alta de 1,3% no primeiro semestre. Os dados foram divulgados pela Superintendência de Estudos Econômicos e Sociais da Bahia (SEI), que apontou também avanço de 1% na comparação com o trimestre anterior e alta de 1,8% no acumulado dos últimos 12 meses.

No primeiro semestre, o PIB baiano somou R$ 297 bilhões, sendo R$ 263,3 bilhões em Valor Adicionado e R$ 33,7 bilhões em impostos. Os setores de serviços, indústria e agropecuária responderam por R$ 172,6 bilhões, R$ 58,3 bilhões e R$ 32,3 bilhões, respectivamente. No período, a agropecuária liderou os crescimentos com 5,7%, seguida pelos serviços, com 2,7%, enquanto a indústria recuou 4,1%. Entre os destaques setoriais, o comércio avançou 3,6%, os transportes 2,3% e as atividades imobiliárias 2,4%.', 'https://www.bahianoticias.com.br/fotos/municipios_noticias/52451/IMAGEM_NOTICIA_9.jpg?checksum=1788964887', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-09 15:12:17.31+00', 0, false, 'PIB da Bahia cresce 2,3% no 2º trimestre e acumula alta de 1,3% no semestre', 'O Produto Interno Bruto (PIB) da Bahia registrou crescimento de 2,3% no segundo trimestre de 2026, em comparação com o mesmo período do ano anterior. Com esse desempenho, a economia estadual...'),
  ('93a628a8-1a58-41a7-a063-d6303fa83f11', 'Rui Costa lidera corrida ao Senado na Bahia; Wagner e Roma empatados', 'rui-costa-lidera-corrida-ao-senado-na-bahia-wagner-e-roma-empatados', 'O ex-ministro da Casa Civil Rui Costa (PT) consolidou a liderança nas intenções de voto para o Senado Federal na Bahia. De acordo com pesquisa da Real Time Big Data, divulgada nesta quarta-f...', 'O ex-ministro da Casa Civil Rui Costa (PT) consolidou a liderança nas intenções de voto para o Senado Federal na Bahia. De acordo com pesquisa da Real Time Big Data, divulgada nesta quarta-feira (9), o petista obteve 26% das preferências no cenário consolidado. Nesse mesmo contexto, Jaques Wagner (PT) registrou 19% e João Roma (PL) alcançou 17%. Como a margem de erro é de dois pontos percentuais, os dois nomes estão em empate técnico. Angelo Coronel (Republicanos) aparece com 15% e está no limite da margem de erro em relação a Roma.

No cenário específico de segundo voto, Jaques Wagner lidera com 20% das intenções. Angelo Coronel figura em segundo lugar com 16%, enquanto Rui Costa e João Roma somam 14% cada. Professora Delliana (Psol) obteve 7% e Carlos Sodrê (Mobiliza), 1%. A pesquisa ouviu 1.600 eleitores na Bahia entre 4 e 8 de setembro, via telefone e internet. O levantamento possui nível de confiança de 95% e margem de erro de dois pontos percentuais para mais ou para menos, com registro no TSE sob o número BA-01568/2026.', 'https://www.bahianoticias.com.br/fotos/principal_noticias/320912/IMAGEM_NOTICIA_9.jpg?checksum=1788955205', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-09 15:12:27.388+00', 1, false, 'Rui Costa lidera corrida ao Senado na Bahia; Wagner e Roma empatados', 'O ex-ministro da Casa Civil Rui Costa (PT) consolidou a liderança nas intenções de voto para o Senado Federal na Bahia. De acordo com pesquisa da Real Time Big Data, divulgada nesta quarta-f...'),
  ('85ad5188-9706-4985-a189-3888446211fa', 'Pesquisa na Bahia indica empate técnico entre Jerônimo e ACM Neto para o governo', 'pesquisa-na-bahia-indica-empate-tecnico-entre-jeronimo-e-acm-neto-para-o-governo', 'Uma pesquisa recente da Real Time Big Data revelou um empate técnico na disputa pelo governo da Bahia entre os candidatos Jerônimo e ACM Neto. O levantamento entrevistou 1.600 eleitores baia...', 'Uma pesquisa recente da Real Time Big Data revelou um empate técnico na disputa pelo governo da Bahia entre os candidatos Jerônimo e ACM Neto. O levantamento entrevistou 1.600 eleitores baianos entre os dias 4 e 8 de setembro, utilizando métodos de contato por telefone e internet para a coleta de dados.

A pesquisa possui um nível de confiança de 95% e apresenta uma margem de erro de 2 pontos percentuais para mais ou para menos, indicando a precisão dos resultados. O estudo está devidamente registrado no Tribunal Superior Eleitoral (TSE) sob o número BA-01568/2026. Os candidatos Ariel Cipriano (DC), Aroldo Félix (UP) e Maria Bona (PC) juntos alcançaram a marca de 1% das intenções de voto.', 'https://www.bahianoticias.com.br/fotos/principal_noticias/320911/IMAGEM_NOTICIA_9.jpg?checksum=1788953141', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-09 15:12:44.666+00', 3, false, 'Pesquisa na Bahia indica empate técnico entre Jerônimo e ACM Neto para o governo', 'Uma pesquisa recente da Real Time Big Data revelou um empate técnico na disputa pelo governo da Bahia entre os candidatos Jerônimo e ACM Neto. O levantamento entrevistou 1.600 eleitores baia...'),
  ('3fdfc43a-97eb-4e71-b63f-eb466bbafe56', 'Brasil pode atender até 40% da nova demanda dos EUA por carne; preço do boi gordo pode atingir recorde', 'brasil-pode-atender-ate-40-da-nova-demanda-dos-eua-por-carne-preco-do-boi-gordo', 'O Brasil pode suprir entre 30% e 40% da nova demanda de 300 mil toneladas adicionais de carne bovina dos Estados Unidos, o equivalente a um volume de 90 mil a 120 mil toneladas. Essa estimat...', 'O Brasil pode suprir entre 30% e 40% da nova demanda de 300 mil toneladas adicionais de carne bovina dos Estados Unidos, o equivalente a um volume de 90 mil a 120 mil toneladas. Essa estimativa é de Fernando Iglesias, analista da Safras & Mercado. Segundo ele, as regras de elegibilidade americanas colocam o Brasil em posição privilegiada para atender à demanda por carne magra e trimmings, insumos para hambúrgueres. Tradicionais fornecedores como Argentina, Austrália, Uruguai e Nova Zelândia não competiriam por este volume adicional devido às suas cotas próprias. Países como Paraguai e nações da América Central possuem capacidade exportadora inferior, consolidando o Brasil como principal beneficiado. A indústria nacional, porém, precisa avaliar a viabilidade das operações, considerando os cortes específicos e os preços internos firmes do boi gordo.

A abertura de mercado nos Estados Unidos acontece em um período de menor demanda chinesa por carne bovina brasileira. Iglesias ressalta que o mercado norte-americano pode ajudar a absorver parte da oferta, mas não substitui integralmente a China. Em agosto, os EUA chegaram a superar a China nas compras de carne bovina do Brasil. Apesar da crescente demanda americana, o fator principal para a sustentação da arroba do boi gordo é a mudança do ciclo pecuário nacional, que prevê menor disponibilidade de animais para abate no segundo semestre. Para os últimos dois meses do ano, o analista projeta um cenário favorável, com oferta restrita, aumento do consumo doméstico, forte demanda dos EUA e a expectativa de retomada das exportações para a China, podendo levar a preços recordes para a arroba do boi gordo.', 'https://imagens-cdn.canalrural.com.br/2025/07/hildeberto-96x96.jpg', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-09 17:37:52.975+00', 4, false, 'Brasil pode atender até 40% da nova demanda dos EUA por carne; preço do boi gordo pode atingir recorde', 'O Brasil pode suprir entre 30% e 40% da nova demanda de 300 mil toneladas adicionais de carne bovina dos Estados Unidos, o equivalente a um volume de 90 mil a 120 mil toneladas. Essa estimat...'),
  ('6df919ac-3c13-4fd4-a890-08d575994a23', 'Motociclista morre em acidente com caminhão na BR-235, em Coronel João Sá', 'motociclista-morre-em-acidente-com-caminhao-na-br-235-em-coronel-joao-sa', 'Um motociclista identificado como Igor morreu em um acidente na BR-235, em Coronel João Sá, na noite de sexta-feira (4/9/2026). A colisão envolveu sua moto e um caminhão de leite, que capotou. As autoridades investigam as causas.', 'Um motociclista identificado como Igor faleceu em um acidente registrado na noite da última sexta-feira, 4 de setembro de 2026, na BR-235. A colisão ocorreu na altura do povoado Boa Sorte, no município de Coronel João Sá, Bahia, e envolveu a motocicleta conduzida pela vítima e um caminhão que realizava coleta de leite. Após o impacto, o veículo de carga capotou, resultando na dispersão de parte do material transportado sobre a pista.

Igor, que era morador da zona rural de Coronel João Sá, não resistiu aos ferimentos e morreu ainda no local do acidente, antes mesmo de receber atendimento médico. O Serviço de Atendimento Móvel de Urgência (SAMU) foi acionado para a ocorrência, mas as equipes encontraram o motociclista já sem vida ao chegarem. A Polícia Militar e outros órgãos competentes compareceram à rodovia para controlar o tráfego e dar início aos procedimentos legais. As circunstâncias exatas da colisão ainda serão apuradas pelas autoridades responsáveis. As fontes consultadas não informaram a idade da vítima nem detalhes sobre as causas do acidente, e não há comunicado oficial de órgãos públicos sobre o ocorrido.', 'https://imagemlink.cleissoncardoso.com/uploads/57495cf9-f2c7-41ab-b315-14cfb8b32c04.png', '3f094372-90cd-4037-b884-144090d021ff', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-09 19:02:51.893691+00', 1024, true, 'Motociclista morre em acidente na BR-235, Coronel João Sá', 'Igor, morador de Coronel João Sá, faleceu após colisão com caminhão de leite na BR-235, em Boa Sorte. Autoridades investigam o acidente.'),
  ('de08df00-b2e5-4fa4-9939-a5b211637dda', 'Mãe e filha morrem em colisão frontal entre carro e caminhão na BR-116, na Bahia', 'mae-e-filha-morrem-em-colisao-frontal-entre-carro-e-caminhao-na-br-116-na-bahia', 'Uma viagem que tinha como destino um atendimento de saúde terminou de forma trágica na manhã desta terça-feira (8), na BR-116, no sudoeste da Bahia. Juliana Marinho, de 32 anos, e a mãe dela...', 'Uma viagem que tinha como destino um atendimento de saúde terminou de forma trágica na manhã desta terça-feira (8), na BR-116, no sudoeste da Bahia. Juliana Marinho, de 32 anos, e a mãe dela, Marli Silva Marinho, de 58, morreram após o carro em que estavam se envolver em uma colisão frontal com um caminhão.

As vítimas ocupavam o veículo de passeio que capotou após o impacto. Segundo informações preliminares, as duas faleceram no local da batida. O motorista do caminhão não sofreu ferimentos graves. A Polícia Rodoviária Federal (PRF) foi acionada para controlar o trânsito e realizar os levantamentos necessários para apurar as causas do acidente. O trecho da rodovia ficou parcialmente interditado durante as operações de remoção dos veículos e a área foi isolada para a perícia.', 'https://euclidesdiario.com/wp-content/uploads/2026/09/img_9335.jpg', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-09 19:24:55.206+00', 9, false, 'Mãe e filha morrem em colisão frontal entre carro e caminhão na BR-116, na Bahia', 'Uma viagem que tinha como destino um atendimento de saúde terminou de forma trágica na manhã desta terça-feira (8), na BR-116, no sudoeste da Bahia. Juliana Marinho, de 32 anos, e a mãe dela...'),
  ('4165c63f-771c-4565-8dfd-0cd5199de313', 'Homem morre e mulher fica ferida a tiros durante evento em Antas, Bahia', 'homem-morre-e-mulher-fica-ferida-a-tiros-durante-evento-em-antas-bahia', 'Um homem de 25 anos morreu e uma mulher de 30 anos ficou ferida a tiros durante um evento na madrugada de domingo (13) em Antas, Bahia. Rafael de Lima Santos não resistiu aos ferimentos. A mulher foi atingida na perna e relatou ter sido baleada por um vigilante. A Polícia Civil investiga a motivação e autoria do crime.', 'Um homem de 25 anos, identificado como Rafael de Lima Santos, foi morto a tiros na madrugada deste domingo (13) na Travessa Martins Matos, em Antas, no nordeste da Bahia. O crime ocorreu por volta das 00h30 durante o evento "Inferninho Fest". A Polícia Militar, acionada por denúncia de disparos, encontrou Rafael ferido no local. Ele foi socorrido pelo Serviço de Atendimento Móvel de Urgência (SAMU), mas não resistiu aos ferimentos e faleceu após dar entrada no hospital local.

Uma mulher, identificada pelas iniciais S.M.M., de 30 anos, também foi atingida por um disparo na perna. Segundo a ocorrência policial, ela relatou que teria sido atingida por um vigilante que trabalhava no evento. A motivação e a autoria dos disparos ainda são desconhecidas e estão sob investigação da Polícia Civil da Bahia, por meio do Plantão Central de Cícero Dantas e da 25ª COORPIN, que realiza diligências para esclarecer os fatos. O Departamento de Polícia Técnica (DPT) foi acionado para a perícia e o corpo de Rafael foi encaminhado para necropsia. O caso foi registrado como homicídio consumado e homicídio tentado.', 'https://imagemlink.cleissoncardoso.com/uploads/619b2677-054e-4298-a140-eb7c8007990e.png', '2938605f-8be9-4f18-b52b-99bc1c4a72f8', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-13 21:31:17.888132+00', 1034, true, 'Homem morre e mulher é ferida a tiros em evento em Antas, Bahia', 'Um homem de 25 anos foi morto e uma mulher de 30 anos ficou ferida por disparos de arma de fogo durante o evento "Inferninho Fest" em Antas, BA. A Polícia Civil investiga o caso.'),
  ('6da6120c-d89d-4b58-9d13-5add1c28ac16', 'Carro invade calçada, mata criança de 2 anos e motorista é morto em Maceió', 'carro-invade-calcada-mata-crianca-de-2-anos-e-motorista-e-morto-em-maceio', 'Carro invade calçada em Maceió, mata criança de 2 anos e fere irmã. Motorista de 53 anos é agredido até a morte por moradores.', 'Um menino de 2 anos morreu e sua irmã, de 4, ficou ferida após um carro invadir a calçada na noite de ontem em Maceió, Alagoas. O motorista, identificado como José Hilton Daltron, de 53 anos, foi agredido por moradores até a morte no local do acidente.

Segundo a Polícia Civil, o veículo teria perdido o controle antes de atingir parte de uma residência no bairro Vergel do Lago. A vítima fatal, Marcos Antônio Silvestre, foi encontrada sob os escombros da casa, que ficou parcialmente destruída. A irmã da criança foi socorrida e transferida ao Hospital Geral do Estado (HGE), onde recebeu atendimento médico e alta.

Após o atropelamento, a população retirou o motorista do carro e o agrediu até a morte. Até o momento, nenhum dos envolvidos na agressão foi identificado ou preso. Moradores do trecho da avenida Senador Rui Palmeira reclamaram da falta de sinalização e pediram a liberação de uma pista nova para reduzir o fluxo de veículos. O Departamento Municipal de Transportes e Trânsitos (DMTT) e a Prefeitura de Maceió não se pronunciaram até o fechamento desta edição. A Polícia Civil instaurou inquérito para apurar a dinâmica dos fatos por meio de câmeras de segurança e depoimentos.', 'https://minio.proradiobr.com/imagens-publicas/marcos-antonio-silvestre-foi-morto-apos-ser-atropelado-em-maceio-al-1789399484242_v2_900x506.png.png', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-14 20:36:05.076886+00', 1005, true, 'Carro atropela crianças em Maceió e motorista é morto por moradores', 'Veículo invade calçada em Maceió, mata menino de 2 anos e fere irmã. Motorista de 53 anos é agredido até a morte por populares no local.'),
  ('fb02e755-653e-4802-b51e-d0c08a5b6f12', 'Investigação da PF aponta pedido de apoio do PCC para Daniel Vorcaro na prisão', 'investigacao-da-pf-aponta-pedido-de-apoio-do-pcc-para-daniel-vorcaro-na-prisao', 'Investigação da Polícia Federal revela que a "Turma", grupo ligado ao caso Banco Master, teria solicitado apoio do PCC para Daniel Vorcaro na prisão. Mensagens entre membros da "Turma" indicam a articulação para auxiliar o ex-banqueiro detido em Guarulhos.', 'Análise de mensagens pela Polícia Federal (PF) revelou que integrantes da "Turma", grupo investigado por apoio a ações clandestinas no caso Banco Master, solicitaram suporte do Primeiro Comando da Capital (PCC) para o ex-banqueiro Daniel Vorcaro enquanto ele estava preso. Em novembro de 2025, Vorcaro estava detido no CDP de Guarulhos quando a "Turma" buscou auxiliá-lo. Mensagens trocadas entre Luiz Phillipi Mourão, conhecido como Sicário, e Manoel Mendes Rodrigues, o Manolo Dom, bicheiro do Rio de Janeiro e membro da "Turma" que recebia dinheiro de Vorcaro, detalham essa articulação. Mourão afirmou em uma das mensagens que Vorcaro era "amigo nosso e apoia nossa quadrilha e a nossa regional (da facção) em diversos sentidos". Manolo expressou preocupação com a adaptação de Vorcaro à prisão, sugerindo contatar um líder do crime organizado em São Paulo para "dar uma assistência".

Mourão redigiu uma mensagem, com cabeçalho "No envio sintonia Tiradentes" — referência a uma divisão do PCC —, solicitando apoio para Vorcaro, afirmando que ele era "companheiro" e "amigo nosso". Esta missiva foi encaminhada por Manolo a um advogado, que posteriormente recebeu R$ 10 mil de Manolo. Pouco depois, Vorcaro obteve habeas corpus do Tribunal Regional Federal da 1ª Região (TRF-1) e foi solto. O relatório da PF, obtido pelo UOL, sugere que os diálogos podem indicar um apoio efetivo do PCC ao ex-banqueiro durante seu encarceramento. Manolo Rodrigues está preso, investigado por organizar ações violentas a mando de Vorcaro, enquanto Luiz Phillipi Mourão cometeu suicídio após ser preso preventivamente pela Polícia Federal.', 'https://minio.proradiobr.com/imagens-publicas/natalia-portinari---autor-2024-1723719083942_v2_80x80.png.png', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-14 20:36:47.925738+00', 1004, true, 'PF: ''Turma'' pediu apoio do PCC para ex-banqueiro Vorcaro na prisão em SP', 'Análise da Polícia Federal de mensagens mostra que a ''Turma'' solicitou apoio do PCC para Daniel Vorcaro detido em Guarulhos. Diálogos revelam articulação para auxiliar o ex-banqueiro.'),
  ('361f4425-3951-424d-a43f-1ef89076c13e', 'Pertences do filho de integrante do Olodum são furtados em Salvador', 'pertences-do-filho-de-integrante-do-olodum-sao-furtados-em-salvador', 'Celular e corrente de Inaie Araújo dos Santos, filho de cantor do Olodum, foram furtados após colisão com rolo compactador em Salvador.', 'O celular e a corrente de Inaie Araújo dos Santos, de 39 anos, foram furtados após um acidente de trânsito ocorrido na segunda-feira (14), em Salvador. A vítima, que é filho de um cantor do grupo Olodum, estava em uma motocicleta quando foi atingida por um rolo compactador.

Segundo as informações preliminares, após a colisão, os pertences da vítima foram levados por terceiros. O caso foi registrado para apuração das circunstâncias do furto e das responsabilidades envolvidas no acidente. A identificação completa dos autores do furto e a análise detalhada da dinâmica do acidente estão em andamento pelas autoridades competentes.', 'https://minio.proradiobr.com/imagens-publicas/foto-no-tamanho-home-2026-09-14t112841.404.jpg.jpg', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-14 20:38:30.492374+00', 1002, true, 'Pertences de filho de cantor do Olodum são furtados em Salvador', 'Celular e corrente de Inaie Araújo dos Santos foram furtados após acidente com rolo compactador em Salvador, na segunda-feira (14).'),
  ('d4c64255-9eec-49eb-b421-fe9142aa9c66', 'Acidente entre carretas na zona rural de Jeremoabo mata uma pessoa e deixa outra ferida', 'acidente-entre-carretas-na-zona-rural-de-jeremoabo-mata-uma-pessoa-e-deixa', 'Um grave acidente entre duas carretas na zona rural de Jeremoabo resultou na morte de Jucelino, de 36 anos. O outro motorista, Jorge Dias de Abreu, ficou ferido e estável. Investigações apuram possível falha nos freios de um dos veículos.', 'A colisão envolvendo duas carretas resultou na morte de uma pessoa e deixou outra ferida na manhã desta segunda-feira, 14 de setembro. O grave acidente ocorreu nas proximidades do povoado Tarrachil, na zona rural de Jeremoabo, e foi caracterizado pela sua grande violência. Uma das carretas estava transportando gado, e vários animais também não resistiram ao impacto. A dimensão da colisão foi severa, com a cabine de um dos veículos completamente destruída e a outra carreta tombada sobre a pista.

A vítima fatal foi identificada como Jucelino, conhecido como “Del”, de 36 anos, natural de Castro Alves, que faleceu no próprio local do acidente. O motorista da outra carreta, Jorge Dias de Abreu, natural de Paripiranga, foi prontamente socorrido e encaminhado a uma unidade hospitalar. Conforme as informações mais recentes, Jorge chegou consciente ao hospital, foi estabilizado e seu estado de saúde permanece estável. Informações preliminares sugerem que a carreta de cor vermelha teria apresentado uma possível falha nos freios, invadindo a pista onde seguia a carreta azul. Um segundo motorista, que presenciou o ocorrido, teria relatado uma tentativa de desligar o veículo, mas sem sucesso em evitar a colisão. As circunstâncias exatas do acidente serão devidamente apuradas pelas autoridades competentes.', 'https://imagemlink.cleissoncardoso.com/uploads/cb7eb571-a62e-4b23-9ebd-f893282d333b.png', '902d44ce-469a-438d-82c4-b6e4a8357a30', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-15 09:11:00.378948+00', 1022, true, 'Acidente em Jeremoabo: Uma pessoa morre e outra fica ferida em colisão de carretas', 'Grave acidente entre duas carretas na zona rural de Jeremoabo na segunda-feira resultou na morte de Jucelino, 36. O motorista Jorge Dias de Abreu ficou ferido. Autoridades investigam possível falha nos freios.'),
  ('cefefcd4-1f82-4292-8398-f920c3f93033', 'Consignado do INSS: Margem legal sobe para 45%, mas cartões seguem suspensos pelo TCU', 'consignado-do-inss-margem-legal-sobe-para-45-mas-cartoes-seguem-suspensos-pelo', 'A margem legal do crédito consignado do INSS voltou a 45% para aposentados e pensionistas com o fim de uma Medida Provisória. Contudo, o uso prático dessa margem expandida é limitado pela suspensão das operações de cartões consignados pelo TCU.', 'Aposentados e pensionistas do INSS podem, por lei, comprometer até 45% do benefício com o crédito consignado. A margem consignável retornou ao patamar anterior após a perda de validade da medida provisória 1.355/2026, do Desenrola Brasil 2.0, que havia limitado o percentual a 40%. No entanto, na prática, o comprometimento maior da renda não se efetivará completamente, pois o Tribunal de Contas da União (TCU) barrou as operações do cartão de crédito consignado e do cartão consignado de benefício. Por lei, 35% da renda podem ser utilizados para empréstimo pessoal consignado e os 10% restantes para os dois cartões, sendo 5% para cada um. O INSS confirmou que as novas operações de cartão de crédito e benefício consignado permanecem suspensas devido a uma medida cautelar do acórdão nº 1094/2026.

A redução da margem havia sido implementada em maio, em meio a debates sobre o risco de endividamento e fraudes. As associações bancárias Febraban e ABBC confirmam o retorno da margem legal para 45%, mas asseguram que as instituições financeiras estão cumprindo as determinações do TCU relativas à suspensão dos cartões, enquanto discutem a retomada das operações. Contratos de consignado firmados durante a vigência da medida provisória não serão alterados. Há uma proposta governamental para reduzir gradualmente a margem para 30% até 2031, mas essa mudança não está em vigor. O consignado é um empréstimo com parcelas descontadas diretamente do benefício, com taxas máximas definidas pelo Conselho Nacional de Previdência Social (CNPS) e validadas pelo Supremo Tribunal Federal (STF).', 'https://minio.proradiobr.com/imagens-publicas/arquivo-20260915-105328.jpg', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-15 10:53:29.223619+00', 1003, true, 'Consignado INSS: Margem sobe para 45%, mas cartões seguem suspensos', 'Aposentados e pensionistas do INSS têm margem legal do consignado de volta a 45%, mas o TCU mantém a suspensão das operações de cartões de crédito e benefício.'),
  ('27a590d9-3f92-48ee-9bd8-a2614cb899e8', 'Greve dos Correios sem previsão de fim e TST determina manutenção de 80% do efetivo', 'greve-dos-correios-sem-previsao-de-fim-e-tst-determina-manutencao-de-80-do', 'Greve dos Correios segue sem previsão de fim após rejeição de proposta. TST determina manutenção de 80% do efetivo para garantir serviços essenciais.', 'Iniciada na última sexta-feira (11), a greve dos trabalhadores dos Correios não possui previsão de encerramento, segundo a Federação dos Trabalhadores e Trabalhadoras dos Correios (FINDECT). A paralisação pode causar atrasos e interrupções na entrega de correspondências e distribuição de encomendas em todo o território nacional. Entre as principais reivindicações da categoria está a garantia do plano de saúde, considerado um direito essencial para empregados, aposentados e familiares. A proposta apresentada pela empresa nas negociações do Acordo Coletivo de Trabalho (ACT) foi rejeitada após sucessivas rodadas de negociação e tentativas de mediação no Tribunal Superior do Trabalho (TST).

No sábado (12), o TST determinou, em decisão liminar, a manutenção de 80% do efetivo em atividade em cada unidade ou estabelecimento da empresa durante a paralisação. A medida abrange trabalhadores das áreas de atendimento, transporte, distribuição e suporte administrativo indispensáveis à continuidade da cadeia postal. A estatal não informou se haverá alteração nos prazos de entrega ou quais regiões serão mais impactadas, mas confirmou que as agências permanecem abertas ao público. A recomendação para quem possui encomendas em trânsito é acompanhar o código de rastreamento para verificar as movimentações do objeto.', 'https://minio.proradiobr.com/imagens-publicas/arquivo-20260915-105423.jpg', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-15 10:54:24.094721+00', 1003, true, 'Greve dos Correios: TST determina manutenção de 80% do efetivo', 'Greve dos Correios não tem previsão de fim. TST determina manutenção de 80% do efetivo. Entregas podem sofrer atrasos em todo o país.'),
  ('f0341896-55ba-4755-93d2-649b4f784560', 'Homem é espancado por grupo após defender companheira em Guanambi', 'homem-e-espancado-por-grupo-apos-defender-companheira-em-guanambi', 'Homem de 41 anos foi espancado por um grupo em Guanambi após tentar defender a companheira de importunação. A vítima se refugiou em uma casa, mas foi agredida novamente até a intervenção de testemunhas.', 'Um homem de 41 anos foi agredido por um grupo de indivíduos após tentar proteger sua companheira de uma situação de importunação, em Guanambi, no sudoeste da Bahia. O incidente ocorreu na região entre os bairros Brasília e Alto Caiçara. Segundo informações do 17º Batalhão da Polícia Militar (17º BPM), a vítima contou que decidiu confrontar os suspeitos ao perceber que eles importunavam sua companheira. Após o questionamento, o grupo teria iniciado as agressões.

Para escapar da violência, o homem correu e se refugiou em uma residência próxima. No entanto, a tentativa de proteção não foi suficiente para encerrar o ataque. Conforme a Polícia Militar, os suspeitos invadiram o quintal do imóvel e continuaram agredindo a vítima. As agressões só cessaram após a intervenção da proprietária da casa, momento em que o grupo fugiu do local.

Policiais militares, acionados pelo Centro Integrado de Comunicações (Cicom), deslocaram-se até o local para dar apoio ao Serviço de Atendimento Móvel de Urgência (Samu), que prestou os primeiros socorros à vítima. Buscas foram realizadas na região, mas nenhum dos envolvidos foi localizado. A Polícia Civil informou que, até o momento, não localizou registro da ocorrência no sistema.', 'https://minio.proradiobr.com/imagens-publicas/arquivo-20260915-105507.jpg', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-15 10:55:07.418412+00', 1006, true, 'Homem é espancado após defender companheira em Guanambi, na Bahia', 'Vítima de 41 anos foi agredida por um grupo em Guanambi após tentar proteger sua companheira. Suspeitos invadiram residência e fugiram do local.'),
  ('1640e68e-b255-4d98-9229-9070f413b1e8', 'Homem é preso em Banzaê acusado de estupro de vulnerável; pai idoso morreu e sobrinha está grávida', 'homem-e-preso-em-banzae-acusado-de-estupro-de-vulneravel-pai-idoso-morreu-e', 'Homem de 44 anos foi preso em Banzaê-BA acusado de estupro de vulnerável contra a sobrinha e o pai idoso, que veio a falecer.', 'Um homem de 44 anos foi preso na última segunda-feira (14), na localidade de Cajazeiras, zona rural de Banzaê-BA, em cumprimento a mandado judicial. De acordo com as informações iniciais, Alexandre Ediva dos Santos é acusado da prática de estupro de vulnerável. O suspeito já havia respondido por abuso sexual contra a própria sobrinha, que na época tinha 12 anos, e cumpriu pena de um ano e meio no Presídio de Paulo Afonso antes de retornar à liberdade.

Após o retorno à comunidade, a vítima, hoje com 16 anos e cuja identidade foi preservada, confirmou novos abusos praticados mediante ameaças, evidenciados pela gravidez. A outra vítima apontada seria o próprio pai do acusado, Edivá Hora dos Santos, 86 anos, cadeirante e vítima de AVC. Segundo relatos, o idoso teria contado à filha sobre o crime e faleceu dois dias depois, supostamente engasgado com alimento, fato que está sob investigação. Alexandre encontra-se preso preventivamente à disposição da Justiça, e as apurações sobre as circunstâncias das mortes e dos abusos seguem em andamento.', 'https://api.proradiobr.com/imagens-publicas/data.jpg.jpg', '1fd8f094-c10e-4a49-a50a-01fdc88cda45', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-15 20:14:23.223097+00', 111, true, 'Homem é preso em Banzaê acusado de estupro de vulnerável', NULL)
ON CONFLICT (id) DO NOTHING;

