INSERT INTO public.noticias (
  id, titulo, slug, resumo, conteudo, imagem_url,
  categoria_id, autor_id, data_publicacao, views, destaque, meta_title, meta_description
) VALUES
  ('e79ffd3b-e545-40f0-be5c-a58b193239de', 'Cantor Rick Sollo é velado em Sorocaba; sepultamento será às 17h', 'cantor-rick-sollo-e-velado-em-sorocaba-sepultamento-sera-as-17h', 'O cantor Rick Sollo está sendo velado em Sorocaba, São Paulo, com sepultamento às 17h em cerimônia restrita. Ele e outras quatro pessoas morreram em queda de helicóptero em Santa Catarina, cujo acidente está sob investigação do CENIPA.', 'O corpo do cantor Rick Sollo (1966-2026) está sendo velado no Jardim Cemitério Pax, bairro Árvore Grande, em Sorocaba, interior de São Paulo. O sepultamento está previsto para as 17h desta quinta-feira (24), com as últimas homenagens restritas a familiares e amigos próximos. A decisão de realizar uma cerimônia privada foi explicada por Geralda Helena, esposa do artista, nas redes sociais. Ela destacou que, enquanto Rick foi uma figura pública e amada por muitos, neste momento íntimo, o corpo é de Geraldo, o marido, pai e avô, pedindo que o artista seja lembrado em seus momentos de alegria no palco.

A morte de Rick Sollo ocorreu em decorrência de um acidente de helicóptero em Urubici, na Serra de Santa Catarina. Além do cantor, outras quatro pessoas estavam na aeronave e também faleceram: o empresário mineiro Bruno Avelar, o videomaker Paulo Soares, o piloto Antônio Roberto Nóbrega de Araújo e o copiloto Leopoldo Barros Teixeira. O helicóptero havia desaparecido na localidade de Santa Bárbara, em Santa Catarina, e seus destroços foram encontrados aproximadamente 20 horas após a perda de sinal. Informações preliminares indicam que a aeronave enfrentou condições meteorológicas adversas após decolar de Porto Belo, no Litoral Norte de Santa Catarina, com destino a São Joaquim, na mesma serra. O Centro de Investigação e Prevenção de Acidentes Aeronáuticos (CENIPA) já anunciou que investigará as causas da queda, com a Força Aérea Brasileira (FAB) assegurando que a apuração será concluída no menor prazo possível.', 'https://api.proradiobr.com/imagens-publicas/cantor-rick-sollo-e-velado-em-sorocaba-sepultamento-sera-as-17h.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-24 15:57:33.06434+00', 1008, true, 'Cantor Rick Sollo é velado em Sorocaba; sepultamento às 17h', 'O corpo do cantor Rick Sollo está sendo velado em Sorocaba, SP, com sepultamento marcado para as 17h. A cerimônia é reservada a familiares e amigos após a morte em acidente de helicóptero em Santa Catarina, que será investigado.'),
  ('66aee19e-e3af-417f-8fcd-0613602e871a', 'Ribeira do Pombal: Motocicleta furtada é recuperada pela PRF, mas suspeito escapa', 'ribeira-do-pombal-motocicleta-furtada-e-recuperada-pela-prf-mas-suspeito-escapa', 'Uma motocicleta furtada no Centro de Ribeira do Pombal foi recuperada pela Polícia Rodoviária Federal (PRF). O suspeito, abordado e liberado inicialmente, está foragido, e as forças de segurança continuam as buscas pelo responsável.', 'Uma motocicleta furtada na tarde desta quinta-feira (24) no Centro de Ribeira do Pombal, em frente a um estabelecimento comercial, foi recuperada pela Polícia Rodoviária Federal (PRF). O momento do furto foi capturado por câmeras de segurança, e o proprietário, após identificar o crime, divulgou as imagens em busca de ajuda para localizar o veículo.

Pouco tempo depois, durante um patrulhamento de rotina, agentes da PRF abordaram um homem que conduzia uma motocicleta sem capacete. O veículo foi retido, mas, sem o conhecimento prévio do furto, o condutor foi liberado. Somente após receberem a informação sobre o ocorrido, a PRF confirmou que a motocicleta retida era, de fato, o veículo levado do Centro da cidade. O suspeito não foi localizado até o momento, e as forças de segurança seguem com as buscas para identificá-lo e prendê-lo.', 'https://imagemlink.cleissoncardoso.com/uploads/c25caafc-d306-4ad2-9971-8857fe72d5f1.png', '7d34292b-4217-4571-ba21-f7aa996aa1d3', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-24 21:00:41.052836+00', 1122, true, 'Motocicleta furtada em Ribeira do Pombal é recuperada pela PRF', 'Uma motocicleta furtada no Centro de Ribeira do Pombal foi recuperada pela PRF. O suspeito foi abordado e liberado antes da identificação do furto, estando agora foragido.'),
  ('28b6b6d2-3cfd-46f7-b6da-b3fb3ce51c15', 'Adolescente de Ribeira do Pombal conquista na Justiça acesso a medicamento inédito contra doença rara', 'adolescente-de-ribeira-do-pombal-conquista-na-justica-acesso-a-medicamento-inedito-contra-doenca-rara', 'Lana, de 17 anos, moradora de Ribeira do Pombal, conquistou na Justiça o acesso ao Skyclarys (omaveloxolona), medicamento de alto custo para Ataxia de Friedreich. A conquista veio após meses de luta da família com Michele e Nadson, pais da adolescente. O caso reflete o desafio de pacientes com doenças raras no acesso a tratamentos inovadores.', 'Lana, de 17 anos, moradora de Ribeira do Pombal, garantiu por via judicial o acesso ao Skyclarys (omaveloxolona), medicamento indicado para Ataxia de Friedreich. A conquista chega após meses de espera e persistência da família, formada por Michele e Nadson, pais da jovem.

A Ataxia de Friedreich é uma doença genética rara e degenerativa que compromete progressivamente a coordenação motora, o equilíbrio e, em estágios avançados, pode afetar o coração. O Skyclarys foi aprovado pela Anvisa em abril de 2025 e é o primeiro tratamento no mundo capaz de alterar o curso natural da doença, segundo a Biogen, fabricante do medicamento. Até então, o tratamento se limitava a cuidados paliativos multidisciplinares — fisioterapia, fonoaudiologia e acompanhamento psicológico.

Por se tratar de terapia de alto custo, o acesso ao medicamento no Brasil ainda depende, em muitos casos, de decisões judiciais, já que o preço final só é definido pela Câmara de Regulação do Mercado de Medicamentos (CMED) após o registro na Anvisa. A história de Lana ilustra esse caminho, comum entre famílias de pacientes com doenças raras.

Com a chegada do Skyclarys, médicos apontam a possibilidade de retardar a progressão dos sintomas motores e preservar por mais tempo a autonomia dos pacientes. Para a família de Lana, a palavra que resume o momento é gratidão — pela vitória alcançada e por todos que apoiaram a caminhada até aqui.', 'https://mkbnqyhvaozqfpmcyoyw.supabase.co/storage/v1/object/public/imagens/noticias/1790288063029_48l80mg.webp', '7d34292b-4217-4571-ba21-f7aa996aa1d3', NULL, '2026-09-24 22:16:28.813+00', 1245, true, 'Adolescente de Ribeira do Pombal ganha acesso ao Skyclarys', 'Lana, 17 anos, obtém via judicial o Skyclarys, primeiro remédio aprovado para Ataxia de Friedreich no Brasil.'),
  ('054aafd7-6bb6-4c28-bfc9-fbc233cb1751', 'Justiça do RJ encerra último processo de assédio contra Marcius Melhem', 'justica-do-rj-encerra-ultimo-processo-de-assedio-contra-marcius-melhem', 'Tribunal do RJ encerra último caso de assédio contra Marcius Melhem mediante acordo de não persecução penal, com doação ao Retiro dos Artistas.', 'O Tribunal de Justiça do Rio de Janeiro encerrou, nesta quinta-feira, 24, o último processo criminal por assédio sexual movido contra o ex-diretor da Globo, Marcius Melhem. A decisão foi tomada após a homologação de um acordo de não persecução penal, proposto pelo Ministério Público e aceito pelo acusado. Este era o único caso pendente de uma série de oito ações judiciais iniciadas em agosto de 2023, nas quais mulheres o acusavam do crime. Melhem já havia sido inocentado nas sete outras ações.

A juíza Juliana Benevides validou a medida despenalizadora, encerrando o processo sem condenação. O Ministério Público havia se manifestado anteriormente contra o prosseguimento da ação por ausência de justa causa. Nos termos do acordo, Melhem comprometeu-se a doar o valor de cinco salários mínimos ao Retiro dos Artistas. O ex-diretor sugeriu aumentar essa quantia, que inicialmente era de três salários mínimos, conforme proposta do órgão ministerial.

Procurado pela imprensa, Melhem não quis conceder entrevistas. Segundo apurações, a decisão de encerrar o acordo foi influenciada por pedidos de suas filhas e pelo desejo de mitigar os impactos da repercussão pública sobre sua carreira e vida pessoal.', 'https://api.proradiobr.com/imagens-publicas/justica-do-rj-encerra-ultimo-processo-de-assedio-contra-marcius-melhem.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-24 23:05:13.923677+00', 1008, true, 'Justiça encerra último processo de assédio contra Marcius Melhem', 'TJ-RJ homologa acordo e encerra último processo de assédio contra Marcius Melhem, que fará doação ao Retiro dos Artistas.'),
  ('c27da0e7-99e7-42a3-bfee-1bd69a5d330c', 'Ribeira do Pombal: Mulher de 76 anos é presa por descumprir prisão domiciliar em caso de homicídio', 'ribeira-do-pombal-mulher-de-76-anos-e-presa-por-descumprir-prisao-domiciliar-em', 'Maria Nilza Gama, de 76 anos, foi presa em Ribeira do Pombal por descumprir a prisão domiciliar. Ela havia sido condenada a 15 anos pelo homicídio do companheiro em 2022. Sua situação será avaliada em audiência de custódia.', 'A Polícia Civil prendeu, na manhã de quinta-feira, 24 de setembro, em Ribeira do Pombal, Maria Nilza Gama, de 76 anos. A idosa é condenada a 15 anos de prisão pelo homicídio de seu companheiro, Carlos de Souza, de 46 anos, ocorrido em novembro de 2022. O julgamento que resultou na condenação ocorreu em julho deste ano, no Tribunal do Júri da cidade.

A prisão foi efetuada por volta das 8h40, na Rua Paraná, no Centro de Ribeira do Pombal. A ação da Polícia Civil cumpriu um mandado expedido pela Vara Criminal local, relacionado ao descumprimento de uma decisão judicial. Apesar da condenação, a Justiça havia concedido a Maria Nilza o direito de cumprir a pena em prisão domiciliar, considerando sua idade avançada. Após a detenção, ela foi conduzida à Delegacia Territorial de Ribeira do Pombal. A situação da idosa será agora analisada pela Justiça em audiência de custódia, que determinará se ela permanecerá em prisão domiciliar ou será encaminhada para uma unidade prisional.', 'https://imagemlink.cleissoncardoso.com/uploads/b98e87de-9439-4585-8690-2e78399bc486.png', '7d34292b-4217-4571-ba21-f7aa996aa1d3', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-25 13:46:12.059456+00', 1028, true, 'Ribeira do Pombal: Idosa presa por descumprir prisão domiciliar', 'Em Ribeira do Pombal, a Polícia Civil prendeu Maria Nilza Gama, 76 anos, condenada por homicídio. A prisão ocorreu após ela descumprir a pena em regime domiciliar.'),
  ('5fabd839-c3ab-4913-a1bf-3a6464d96ff2', 'PF apura suposta entrega de bacias infantis com pedido de voto a Flávio Bolsonaro em Ibitiara', 'pf-apura-suposta-entrega-de-bacias-infantis-com-pedido-de-voto-a-flavio', 'Justiça Eleitoral encaminha à PF denúncia sobre suposta entrega de bacias e pedidos de voto a Flávio Bolsonaro em Ibitiara (BA). Caso pode configurar corrupção eleitoral.', 'A Justiça Eleitoral determinou o envio à Polícia Federal de uma denúncia sobre a suposta distribuição de kits com brinquedos e bacias infantis acompanhada de pedido explícito de votos para o candidato à Presidência da República Flávio Bolsonaro (PL), em Ibitiara, na Chapada Diamantina. O caso será investigado sob a possibilidade de configuração de corrupção eleitoral. A denúncia foi apresentada por meio do aplicativo Pardal e protocolada em 15 de setembro. Segundo o relato, um homem não identificado estaria distribuindo os materiais na Praça da Matriz, no Centro de Ibitiara, e pedindo votos para o candidato. Um vídeo sigiloso foi anexado à denúncia.

A decisão, assinada pelo juiz Flávio Monteiro Ferrari, da 88ª Zona Eleitoral de Seabra, também determinou o envio do caso à Procuradoria-Geral Eleitoral, em razão de a denúncia estar relacionada à eleição presidencial. O Ministério Público Eleitoral apontou que a entrega de vantagens materiais associada a pedido de votos pode, em tese, configurar o crime previsto no artigo 299 do Código Eleitoral. No entanto, o órgão destacou a falta de elementos para identificar o autor e sua ligação com a campanha, justificando a investigação policial prévia. A Justiça Eleitoral de Seabra já havia determinado fiscalização no local para interromper eventuais distribuições irregulares. Até o momento, não há comprovação de vínculo entre o suposto autor e o Partido Liberal.', 'https://api.proradiobr.com/imagens-publicas/pf-apura-suposta-entrega-de-bacias-infantis-com-pedido-de-voto-a-flavio.webp', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-25 20:52:58.134008+00', 1006, true, 'PF investiga pedido de voto a Flávio Bolsonaro com entrega de bacias em Ibitiara', 'Justiça Eleitoral encaminha à PF denúncia sobre suposta distribuição de bacias e pedidos de voto a Flávio Bolsonaro em Ibitiara, na Bahia.'),
  ('86a24411-c199-46b0-9fd0-2fd2f5f29290', 'Lula assina MP que proíbe bets no país; resgate de recursos válido até 5 de outubro', 'lula-assina-mp-que-proibe-bets-no-pais-resgate-de-recursos-valido-ate-5-de', 'Lula assinou MP proibindo as bets no Brasil. O resgate de recursos dos usuários deve ser feito até 5 de outubro, visando reduzir o endividamento das famílias.', 'O presidente Luiz Inácio da Silva assinou na tarde desta sexta-feira (25), em São Paulo, uma medida provisória que proíbe a atividade das casas de apostas de internet, as chamadas bets, em todo o território nacional. A decisão ocorre menos de três anos após a sanção da Lei das Bets, em dezembro de 2023, que havia regularizado o setor. A nova norma visa combater o endividamento das famílias brasileiras, tendo sido considerada uma medida radical por parte de especialistas no tema.

Conforme determinado no texto da medida provisória, o período para o resgate dos recursos por parte dos consumidores tem prazo final até o dia 5 de outubro. O governo federal estabelece essa data-limite para que os usuários realizem a retirada de seus saldos das plataformas antes do encerramento definitivo das operações. A ação representa uma mudança abrupta na política regulatória do setor, encerrando a atividade que vinha em expansão no Brasil nos últimos anos.', 'https://api.proradiobr.com/imagens-publicas/lula-assina-mp-que-proibe-bets-no-pais-resgate-de-recursos-valido-ate-5-de.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-25 21:40:44.108335+00', 1008, true, 'Lula assina MP que proíbe as bets no Brasil', 'Medida provisória assinada por Lula proíbe as casas de apostas. Prazo para resgate de recursos pelos usuários é até 5 de outubro.'),
  ('0d4e14f9-b29c-435f-8e18-65ad858655f1', 'Justiça de São Paulo nega pedido de homem para retirar sobrenome Flor do registro civil', 'justica-de-sao-paulo-nega-pedido-de-homem-para-retirar-sobrenome-flor-do', 'Tribunal de Justiça de São Paulo nega ao homem o direito de retirar o sobrenome paterno Flor, mantendo decisão que considerou as alegações de constrangimento genéricas.', 'A 10ª Câmara de Direito Privado do Tribunal de Justiça de São Paulo (TJSP) manteve a decisão de primeira instância que rejeitou o pedido de um homem para excluir o sobrenome paterno "Flor" de seu registro civil. O autor da ação alegava que convivia com piadas de mau gosto e constrangimentos relacionados ao nome desde a infância, argumentando que a manutenção do sobrenome lhe causava prejuízos. No entanto, o tribunal entendeu que os argumentos apresentados não eram suficientes para justificar a alteração pretendida.

A decisão unânime do TJSP confirmou o entendimento da juíza Priscilla Miwa Kumode, da 2ª Vara Cível do Foro Regional de Nossa Senhora do Ó, que considerou as alegações genéricas. O relator do recurso, desembargador Elcio Trujillo, destacou que a retificação do registro civil é admitida quando os dados registrados não correspondem à realidade, o que não se configurou no caso analisado. Um dos pontos considerados na avaliação foi o fato de a esposa do homem também adotar o sobrenome "Flor". Participaram do julgamento os desembargadores Angela Moreno Pacheco de Rezende Lopes e Jair de Souza.', 'https://api.proradiobr.com/imagens-publicas/justica-de-sao-paulo-nega-pedido-de-homem-para-retirar-sobrenome-flor-do.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-25 22:02:48.776782+00', 1010, true, 'TJSP nega pedido para retirar sobrenome Flor do registro civil', 'Justiça de São Paulo mantém decisão que impede homem de excluir sobrenome paterno Flor do registro civil, rejeitando alegações de constrangimento.'),
  ('ba36f4a3-4ac1-43fb-94f7-8d28ccadc6d0', 'Acidente na BR-110 deixa condutor preso nas ferragens no Mocó, em Ribeira do Pombal', 'acidente-na-br-110-deixa-condutor-preso-nas-ferragens-no-moco-em-ribeira-do-pombal', 'Um acidente entre dois veículos foi registrado na manhã desta sexta-feira (25) na BR-110, próximo ao povoado Mocó, em Ribeira do Pombal. O motorista do Toyota Etios ficou preso nas ferragens e precisou ser retirado pelos Bombeiros. Equipes do SAMU, Corpo de Bombeiros e da PRF atuaram no local.', 'Um grave acidente envolvendo um Hyundai HB20 e um Toyota Etios foi registrado na manhã desta sexta-feira (25), na BR-110, nas imediações do povoado Mocó, em Ribeira do Pombal.

O motorista do Toyota Etios ficou preso nas ferragens e só foi retirado após os Bombeiros abrirem o veículo com equipamentos apropriados. A colisão chamou a atenção de motoristas que passavam pelo trecho no momento da ocorrência.

Equipes do SAMU e do Corpo de Bombeiros atuaram no atendimento às vítimas, com apoio da Polícia Rodoviária Federal (PRF), responsável pelo controle do tráfego e pela investigação das causas do acidente. Até o momento, não há informações oficiais sobre o estado de saúde dos envolvidos.

A reportagem do Dia a Dia Nordeste segue apurando as circunstâncias do acidente e busca atualização junto às autoridades sobre o quadro clínico das vítimas.', 'https://mkbnqyhvaozqfpmcyoyw.supabase.co/storage/v1/object/public/imagens/noticias/1790374449361_wtqfjsw.webp', '7d34292b-4217-4571-ba21-f7aa996aa1d3', NULL, '2026-09-25 22:15:57.391+00', 3595, true, ': Acidente na BR-110 deixa vítima presa em veículo no Mocó', 'Colisão entre Hyundai HB20 e Toyota Etios na BR-110, no povoado Mocó, em Ribeira do Pombal, mobiliza SAMU, Bombeiros e PRF nesta sexta-feira.'),
  ('390a15da-f5b5-431f-88fe-de764249dae9', 'Ribeira do Pombal, terra de modelos internacionais: Bella Gonçalves estreia em Milão pela Diesel', 'ribeira-do-pombal-terra-de-modelos-internacionais-bella-goncalves-estreia-em-milao-pela-diesel', 'Ribeira do Pombal consolida-se como uma das cidades do interior baiano com mais modelos no circuito internacional. Bella Gonçalves, 22 anos, natural de Nova Esperança, estreou na Semana de Moda de Milão pela grife Diesel, seguindo os passos de Josefa Santos. A informação foi divulgada pelo jornal O Globo.', '
Poucas cidades do interior do Brasil podem dizer que revelaram mais de uma modelo para as passarelas internacionais. Ribeira do Pombal é uma delas — e a lista continua crescendo.

Bella Gonçalves, 22 anos, natural do povoado de Nova Esperança, estreou no calendário internacional de moda durante a Semana de Moda de Milão. Ela desfilou pela grife Diesel, na coleção primavera-verão 2027, segundo o jornal O Globo.

Agenciada pela Síntese MGT, Bella seguiu o caminho já trilhado por Josefa Santos, também pombalense, que abriu espaço para talentos da região nas grandes vitrines da moda mundial. A repetição do feito reforça que não se trata de exceção, mas de uma tendência local.

Para quem vive no semiárido baiano, o momento é motivo de orgulho: uma cidade de médio porte, distante dos grandes centros da moda, hoje figura no mapa internacional através de suas próprias filhas. A expectativa é que novos nomes surjam nas próximas temporadas.', 'https://mkbnqyhvaozqfpmcyoyw.supabase.co/storage/v1/object/public/imagens/noticias/1790379714004_5xr60jm.webp', '7d34292b-4217-4571-ba21-f7aa996aa1d3', NULL, '2026-09-25 23:42:01.633+00', 626, true, 'Ribeira do Pombal vira celeiro de modelos internacionais', 'Com Bella Gonçalves em Milão, Ribeira do Pombal soma mais uma modelo no circuito internacional de moda — feito raro para cidades do interior.'),
  ('8144e818-21d6-4251-8438-d267dcb41567', 'Escola Municipal de Ribeira do Pombal conquista 1º lugar em competição de robótica na Bahia', 'escola-municipal-de-ribeira-do-pombal-conquista-1-lugar-em-competicao-de', 'A Escola Municipal Maria Menezes, de Ribeira do Pombal, venceu o Desafio Maker 2026 de robótica em Salvador, superando 19 escolas, a maioria privadas, em competição sobre preservação hídrica.', 'A Escola Municipal Maria Menezes, localizada no bairro Pombalzinho, em Ribeira do Pombal, conquistou o primeiro lugar no Desafio Maker 2026, competição de robótica realizada no Colégio Sacramentinas, em Salvador. O resultado foi obtido entre 20 escolas participantes, sendo a maioria da rede particular de ensino. O evento, promovido pela Quálitas Educação e Tecnologia, teve como tema "Missão Água: Tecnologia para Preservar, Cuidar e Transformar", desafiando os estudantes a criar soluções voltadas à preservação dos recursos hídricos.

A vitória destaca o desempenho da educação pública local e reflete investimentos recentes da Prefeitura de Ribeira do Pombal na unidade, que incluem melhorias na infraestrutura, ampliação das oportunidades de aprendizagem e a implantação do ensino em tempo integral. A conquista é atribuída ao talento dos estudantes, à dedicação dos educadores e ao compromisso da comunidade escolar, servindo como exemplo de como o investimento em educação pode revelar potencialidades e ampliar horizontes para crianças e adolescentes da região.', 'https://api.proradiobr.com/imagens-publicas/escola-municipal-de-ribeira-do-pombal-conquista-1-lugar-em-competicao-de.webp', '7d34292b-4217-4571-ba21-f7aa996aa1d3', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-26 17:37:45.373308+00', 145, true, 'Escola de Ribeira do Pombal vence competição de robótica na Bahia', NULL),
  ('42b957d5-75b4-4bf9-842e-b7a55fce07ed', 'Fiat Strada pega fogo dentro de loja de ferragens em Ribeira do Pombal neste sábado (26)', 'fiat-strada-pega-fogo-dentro-de-loja-de-ferragens-em-ribeira-do-pombal-neste', 'Um Fiat Strada pegou fogo dentro de uma loja de ferragens em Ribeira do Pombal neste sábado (26). O incidente, possivelmente causado por um curto-circuito, mobilizou populares e o Corpo de Bombeiros. Não há registro de feridos, e as causas e danos ainda estão sob apuração.', 'Um veículo Fiat Strada foi consumido por chamas no início da tarde deste sábado, 26 de agosto, enquanto estava estacionado no interior de uma loja de ferragens na cidade de Ribeira do Pombal. Conforme informações preliminares, o incidente pode ter sido provocado por um curto-circuito no automóvel, que rapidamente resultou em um incêndio.

Populares que testemunharam a ocorrência auxiliaram no primeiro atendimento e prontamente acionaram o Corpo de Bombeiros. As equipes de emergência foram mobilizadas e agiram para controlar as chamas e garantir a segurança do local. Até o momento, não há relatos de pessoas feridas. As causas exatas do incêndio e a extensão dos danos materiais sofridos pelo veículo e pelo estabelecimento ainda serão apuradas pelas autoridades competentes.', 'https://imagemlink.cleissoncardoso.com/uploads/38c05027-85e0-4579-a893-64044ba24666.png', '7d34292b-4217-4571-ba21-f7aa996aa1d3', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-26 20:38:51.316336+00', 1023, true, 'Veículo incendeia em loja de ferragens de Ribeira do Pombal', 'Um Fiat Strada pegou fogo dentro de uma loja de ferragens em Ribeira do Pombal neste sábado (26). O incêndio, que pode ter sido causado por curto-circuito, não deixou feridos. Causas e danos serão investigados.'),
  ('34971c3f-5daa-4e52-b72f-0de8f5885a21', 'Homem morre esfaqueado em povoado de Heliópolis, Bahia', 'homem-morre-esfaqueado-em-povoado-de-heliopolis-bahia', 'Um homem identificado como Ramon Oliveira Mota morreu após ser esfaqueado na noite de sábado (26) no povoado Massaranduba, em Heliópolis. O corpo foi levado ao IML de Pombal. As circunstâncias do crime e a autoria ainda são desconhecidas.', 'Ramon Oliveira Mota faleceu na noite deste sábado (26) após ser atingido por golpes de faca no povoado Massaranduba, um distrito de Heliópolis, localizado no nordeste da Bahia. Conforme informações preliminares, Ramon não resistiu à gravidade dos ferimentos e veio a óbito no local. Seu corpo foi imediatamente encaminhado ao Instituto Médico-Legal (IML) de Pombal, onde permanece sob custódia aguardando os procedimentos legais e a realização da perícia necessária.

A expectativa é que o corpo de Ramon Oliveira Mota seja liberado ainda neste domingo (27), permitindo que seus familiares possam realizar o sepultamento. Até o momento, as autoridades responsáveis pela investigação não divulgaram oficialmente as circunstâncias que envolvem o crime, tampouco informações sobre a autoria ou a motivação do ataque. A polícia trabalha para esclarecer os fatos e identificar os envolvidos no ocorrido.', 'https://imagemlink.cleissoncardoso.com/uploads/8df669b7-5e74-4ecf-aa4e-bac87dfe5c21.png', '2dd68615-05d7-48f1-9467-819514c31649', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-27 11:45:58.60148+00', 1070, true, 'Homem é esfaqueado e morre em Massaranduba, Heliópolis', 'Ramon Oliveira Mota morreu após ser atingido por golpes de faca na noite de sábado (26) em Heliópolis, Bahia. O corpo foi encaminhado ao IML. A polícia investiga autoria e motivação.'),
  ('7b4c1d5f-4e0f-48dd-b448-b6906662315e', 'Imagem de Santa Dulce é destruída em invasão a igreja no bairro de Plataforma, em Salvador', 'imagem-de-santa-dulce-e-destruida-em-invasao-a-igreja-no-bairro-de-plataforma', 'Imagem de Santa Dulce foi destruída durante invasão à Igreja Matriz da Paróquia Jesus Cristo Ressuscitado, em Plataforma, Salvador. A paróquia informou que segue com as providências junto à Arquidiocese.', 'Uma imagem da santa Dulce dos Pobres foi danificada em um ato de vandalismo registrado na Igreja Matriz da Paróquia Jesus Cristo Ressuscitado, localizada no bairro de Plataforma, no Subúrbio Ferroviário de Salvador. De acordo com nota oficial divulgada pela paróquia na última quinta-feira, dia 23, a invasão teria ocorrido na tarde da quarta-feira, por volta das 15h.

Conforme as informações publicadas nas redes sociais pela instituição religiosa, o autor do ato retirou a imagem de um altar lateral e a levou até o espaço situado entre a mesa eucarística e o sacrário, onde a quebrou. Não foram divulgados detalhes sobre a tentativa de subtração de outros objetos do templo. A gestão da paróquia afirmou que já está tomando as providências necessárias junto à Arquidiocese de Salvador para esclarecer as circunstâncias do episódio. Além disso, a comunidade foi convidada a se unir em um ato de reparação e oração em apoio à paróquia.', 'https://api.proradiobr.com/imagens-publicas/imagem-de-santa-dulce-e-destruida-em-invasao-a-igreja-no-bairro-de-plataforma.webp', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-27 16:55:18.811322+00', 1011, true, 'Imagem de Santa Dulce é destruída em invasão a igreja em Plataforma', 'Imagem de Santa Dulce foi quebrada durante ato de vandalismo na Igreja Matriz da Paróquia Jesus Cristo Ressuscitado, em Plataforma, Salvador.'),
  ('48c2ecc3-b2a9-4b69-ad78-bdb472efeab3', 'Roberta Roma segue em UTI em Salvador após infarto durante campanha', 'roberta-roma-segue-em-uti-em-salvador-apos-infarto-durante-campanha', 'Deputada federal Roberta Roma segue internada em UTI em Salvador após infarto sofrido durante campanha em Cruz das Almas. Médicos investigam síndrome de Takotsubo.', 'A deputada federal e candidata à reeleição Roberta Roma (PL) permanece internada e estável na UTI Cardíaca do Hospital Cárdio Pulmonar, em Salvador. Ela passou por um cateterismo neste sábado (26), procedimento que não identificou lesões importantes nas artérias coronárias. A equipe médica investiga a possibilidade de síndrome de Takotsubo, conhecida como síndrome do coração partido, além de realizar outros exames para esclarecer o quadro clínico.

Roberta sentiu dor no peito com irradiação para o braço direito durante uma agenda de campanha em Cruz das Almas. Após receber os primeiros cuidados no interior do estado, ela foi transferida para Salvador para dar continuidade à avaliação médica, sendo confirmado o infarto. Segundo as informações divulgadas, a deputada está medicada, monitorizada e bem-humorada. Ela segue sob os cuidados do clínico geral Silvestre Sobrinho e do cardiologista Adriano Martins, chefe da UTI, enquanto a investigação da dor torácica é concluída. A família agradece as mensagens de carinho e informou que divulgará novas informações conforme a evolução da avaliação.', 'https://api.proradiobr.com/imagens-publicas/roberta-roma-segue-em-uti-em-salvador-apos-infarto-durante-campanha.webp', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-27 16:57:19.974894+00', 1010, true, 'Roberta Roma internada em UTI após infarto em Salvador', 'Deputada Roberta Roma segue estável em UTI em Salvador após infarto durante campanha. Médicos investigam síndrome de Takotsubo.'),
  ('2ee379bd-4f57-426a-baaa-fb01621da553', 'Cultureira 2026 reúne gerações e atrai grande público em Ribeira do Pombal', 'cultureira-2026-reune-geracoes-e-atrai-grande-publico-em-ribeira-do-pombal', 'A Cultureira 2026 reuniu várias gerações na Praça da Juventude, em Ribeira do Pombal, celebrando os 93 anos da cidade com música, dança e valorização da arte local.', 'A Cultureira 2026 destacou-se pelo crescimento do público e pela capacidade de reunir diferentes gerações no entorno da Praça da Juventude, em Ribeira do Pombal. O evento, realizado durante as comemorações dos 93 anos de emancipação política do município, registrou alta procura nas imediações, com grande presença de veículos e famílias inteiras prestigiando as apresentações artísticas.

O festival, que teve como conceito uma cultura em movimento, integrou música, dança e comidas típicas, transformando o espaço em um palco da identidade local. A programação de dois dias valorizou artistas e produtores culturais da região, reforçando o caráter democrático do evento ao conectar públicos de todas as idades. A iniciativa consolidou-se no calendário local ao propor uma experiência que favorece a convivência intergeracional e a exposição de expressões culturais que traduzem a história e as tradições de Ribeira do Pombal.', 'https://api.proradiobr.com/imagens-publicas/cultureira-2026-reune-geracoes-e-atrai-grande-publico-em-ribeira-do-pombal.webp', '7d34292b-4217-4571-ba21-f7aa996aa1d3', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-28 12:49:20.110036+00', 121, true, 'Cultureira 2026 reúne gerações em Ribeira do Pombal', NULL),
  ('bc87c026-2ed0-4769-925d-7096889ae34d', 'Pesquisa BTG/Nexus aponta Lula com 5 pontos à frente de Flávio no 1º turno e empate técnico no 2º', 'pesquisa-btgnexus-aponta-lula-com-5-pontos-a-frente-de-flavio-no-1-turno-e', 'Pesquisa BTG/Nexus mostra Lula com 42% e Flávio Bolsonaro com 37% no primeiro turno. No segundo turno, os candidatos empatam com 46% e 44%, respectivamente, dentro da margem de erro.', 'Levantamento realizado pelo instituto Nexus, contratado pelo Banco BTG Pactual, indica que o presidente Luiz Inácio Lula da Silva (PT) lidera as intenções de voto para a Presidência da República no primeiro turno, com 42% das preferências. O senador Flávio Bolsonaro (PL) aparece em segundo lugar, com 37% dos votos. A diferença entre os dois principais candidatos é de cinco pontos percentuais.

Os dados foram coletados por telefone com 2.000 eleitores entre os dias 25 e 27 de setembro. A pesquisa possui margem de erro de dois pontos percentuais, para mais ou para menos, e nível de confiança de 95%. O registro no Tribunal Superior Eleitoral é o BR-07557/2026.

No cenário de segundo turno, o presidente Lula registra 46% das intenções de voto, enquanto Flávio Bolsonaro obtém 44%. Considerando a margem de erro, os dois nomes estão em empate técnico nesta etapa da disputa. Os demais candidatos, incluindo Edmilson Costa, Hertz Dias e Rui Costa Pimenta, não atingiram a marca de 1% nas intenções de voto.', 'https://api.proradiobr.com/imagens-publicas/pesquisa-btgnexus-aponta-lula-com-5-pontos-a-frente-de-flavio-no-1-turno-e.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-28 13:29:40.471385+00', 1008, true, 'Lula tem 5 pontos a frente de Flávio no 1º turno, aponta pesquisa', 'Pesquisa BTG/Nexus indica Lula com 42% e Flávio Bolsonaro com 37% no 1º turno para presidente. No 2º turno, os nomes empatam tecnicamente.'),
  ('f75bdbd3-50d5-49da-919d-79dfb6b8f71a', 'Homem investigado por homicídio qualificado é preso em Banzaê', 'homem-investigado-por-homicidio-qualificado-e-preso-em-banzae', 'Um homem investigado por homicídio qualificado foi preso no último domingo (27) em Banzaê, Bahia, em operação conjunta das polícias Civil e Militar. O suspeito também foi conduzido por exploração de jogos de azar, com apreensão de dinheiro e materiais no local.', 'Um homem investigado por homicídio qualificado, que possuía mandado de prisão em aberto, foi detido na tarde do último domingo (27) no município de Banzaê, nordeste da Bahia. A prisão ocorreu por volta das 13h, durante uma ação conjunta que envolveu equipes da Polícia Civil e da Polícia Militar. A operação contou com a participação do Serviço de Investigação da 1ª Delegacia Territorial e do Grupo de Apoio Técnico e Tático à Investigação (GATTI) da 25ª Coordenadoria Regional de Polícia do Interior (COORPIN), além de policiais do 6º Pelotão de Cícero Dantas/Banzaê, pertencente à 21ª CIPM.

De acordo com a Polícia Civil, o mandado de prisão foi expedido pelo Poder Judiciário de Ribeira do Pombal, referente ao processo nº 8002070-68.2026.8.05.0213. O investigado é apontado como suspeito de envolvimento na morte de João Paulo Oliveira Neto, ocorrida em 4 de maio de 2026, também em Banzaê, onde a vítima teria sido agredida com pauladas e pedradas. Durante a ocorrência, o homem também foi conduzido por suspeita, em tese, da prática de contravenção penal relacionada à exploração de jogos de azar. No local, foram apreendidos R$ 1.620 em espécie, um globo para sorteio, um lote de cartelas, um microfone, 75 bolas para sorteio, um tripé e um aparelho celular. O custodiado foi apresentado à unidade policial para as medidas legais cabíveis e permanece à disposição da Justiça.', 'https://api.proradiobr.com/', '1fd8f094-c10e-4a49-a50a-01fdc88cda45', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-28 15:05:19.545035+00', 1018, true, 'Homem suspeito de homicídio é preso em Banzaê, Bahia', 'Operação conjunta das polícias Civil e Militar resultou na prisão de um homem investigado por homicídio qualificado em Banzaê, Bahia, no último domingo (27). O suspeito também foi conduzido por exploração de jogos de azar.'),
  ('e7e6d00b-52c0-449b-a300-64687c51d2b7', 'Mãe vê filha ser perseguida pelo pai antes da morte dos dois em Bali, na Indonésia', 'mae-ve-filha-ser-perseguida-pelo-pai-antes-da-morte-dos-dois-em-bali-na', 'Mãe acompanhou por câmera a fuga da filha de 4 anos perseguida pelo pai em Bali. O homem matou os dois filhos e cometeu suicídio.', 'Uma mãe acompanhou remotamente, por meio de câmeras de segurança, os últimos momentos de sua filha de 4 anos antes de a menina e o irmão, de 6, serem mortos pelo próprio pai em um bangalô na região de Legian, em Kuta, na ilha de Bali, na Indonésia. O suspeito, Damien John Shaw, de nacionalidade australiana, foi encontrado morto no mesmo local no dia 13 de setembro. As autoridades trabalham com a hipótese de que ele matou as crianças e, em seguida, tirou a própria vida.

Segundo a polícia de Bali, as gravações mostram que o menino teria sido atacado primeiro. A irmã, que possivelmente presenciou o ocorrido, conseguiu sair do quarto e tentou fugir. Durante a perseguição pela residência, a criança chegou a gritar que amava o pai, mas foi alcançada e levada de volta ao cômodo. O homem teria então buscado uma corda em um depósito para cometer o crime. A mãe, que estava fora da região, percebeu algo errado após a ligação com o marido ser interrompida e acessou as câmeras pelo celular, alterando o ângulo para visualizar a cena. Ao não conseguir contato com a família, pediu que vizinhos fossem até o imóvel, onde os três corpos foram encontrados. Exames preliminares indicaram sinais de violência no pescoço das vítimas.', 'https://api.proradiobr.com/imagens-publicas/mae-ve-filha-ser-perseguida-pelo-pai-antes-da-morte-dos-dois-em-bali-na.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-28 19:59:33.794981+00', 1008, true, 'Pai mata dois filhos e se suicida em Bali; mãe via cena por câmera', 'Mãe viu por câmera a filha ser perseguida pelo pai em Bali. Ele matou os dois filhos e tirou a própria vida, segundo a polícia local.'),
  ('08435c87-c1c9-426b-abb0-69dc38083070', 'Projeções indicam renovação de 29% na Assembleia Legislativa da Bahia', 'projecoes-indicam-renovacao-de-29-na-assembleia-legislativa-da-bahia', 'Projeções indicam renovação de 29% na Assembleia da Bahia, com 18 novatos. Federações PT e União Brasil lideram estimativas.', 'Faltando seis dias para as eleições, as projeções para a Assembleia Legislativa da Bahia apontam uma renovação de aproximadamente 29% dos cadeiras, com a vitória de ao menos 18 novos parlamentares entre os 63 eleitos. A federação composta por PT, PCdoB e PV deve manter força, elegendo 17 deputados, enquanto a aliança de União Brasil e PP projeta dez vagas. O PSD deve manter seu contingencial de dez representantes, e partidos como Avante, PL, PDT e Republicanos também têm nomes consolidados nas estimativas.

Siglas tradicionais como PSB e partidos menores correm risco de ficar sem representação na Casa. Entre os nomes cotados para reeleição estão Rosemberg Pinto, Ivana Bastos e Elinaldo Araújo, que pode ser o mais votado de seu grupo. Novatos como Rowenna Brito, Denise Menezes e Thiago Gileno também aparecem com boas chances. A disputa acirrada ocorre também entre PSDB e PSOL, que brigam por uma vaga adicional. As projeções consideram apenas 61 dos 63 assentos, com incertezas em algumas candidaturas.', 'https://api.proradiobr.com/imagens-publicas/projecoes-indicam-renovacao-de-29-na-assembleia-legislativa-da-bahia.webp', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-28 21:49:23.260261+00', 1008, true, 'Projeções: 29% de renovação na Assembleia Legislativa da Bahia', 'Projeções para a Assembleia da Bahia apontam renovação de 29% e vitória de 18 novatos. Veja os nomes cotados para reeleição e as siglas em risco.'),
  ('534da919-fb7c-438f-92b7-9a4aee2de637', 'Governo pede R$ 1 bilhão a 17 empresas de bets por danos ao SUS', 'governo-pede-r-1-bilhao-a-17-empresas-de-bets-por-danos-ao-sus', 'A União processou 17 empresas de apostas em Pernambuco, cobrando R$ 1 bilhão por danos ao SUS. A AGU alega que o crescimento de casos de ludopatia sobrecarrega o sistema de saúde.', 'O governo federal ajuizou uma ação civil pública na Justiça Federal de Pernambuco contra 17 empresas de apostas de quota fixa, solicitando o ressarcimento de R$ 1 bilhão por danos morais e coletivos ao Sistema Único de Saúde. A demanda, protocolada pela Advocacia-Geral da União (AGU), argumenta que as plataformas transferem para o SUS o custo financeiro e social associado ao aumento de casos de ludopatia e comportamento de jogo excessivo entre a população brasileira.

Segundo a AGU, estudos preliminares do Ministério da Saúde indicam um prejuízo mínimo de R$ 2,6 bilhões, com base em dados que apontam um crescimento de aproximadamente 140% nos atendimentos ligados a diagnósticos de jogo patológico entre 2018 e 2025. A ação também requer a restituição em dobro dos valores apostados por pessoas diagnosticadas com transtorno do jogo. O processo foi ajuizado em Pernambuco devido à concentração de vulnerabilidade social na região Nordeste, onde se estima que 28 milhões de brasileiros apostam, sendo 10,9 milhões em situação de risco.', 'https://api.proradiobr.com/imagens-publicas/governo-pede-r-1-bilhao-a-17-empresas-de-bets-por-danos-ao-sus.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-28 22:08:46.090175+00', 1004, true, 'Governo processa empresas de bets por R$ 1 bi em danos ao SUS', 'A União pede R$ 1 bilhão a 17 empresas de apostas por prejuízos ao SUS. A ação cita aumento de casos de ludopatia e busca ressarcimento por danos coletivos.'),
  ('0c3b8fe8-2564-4d11-9003-79348e3d738c', 'TST determina que Caixa mantenha 60% dos funcionários em atividade durante a greve', 'tst-determina-que-caixa-mantenha-60-dos-funcionarios-em-atividade-durante-a', 'O TST determinou que a Caixa mantenha 60% dos funcionários em atividade durante a greve. O julgamento do dissídio coletivo está marcado para terça-feira (29).', 'O Tribunal Superior do Trabalho (TST) determinou que a Caixa Econômica Federal mantenha 60% dos seus funcionários em atividade durante a greve da categoria, iniciada em 10 de setembro. A decisão, do ministro Maurício Godinho Delgado, estabelece que o trabalho seja retomado de forma presencial ou em home office. Sindicatos que descumprirem a norma estão sujeitos a multa diária de R$ 100 mil. O julgamento do dissídio coletivo, que definirá o fim da paralisação, está marcado para terça-feira (29), e as entidades foram notificadas na sexta-feira (25).

Segundo a Caixa, estão fechadas mais de 80% das agências no país, o que prejudica serviços essenciais como o pagamento de benefícios sociais e a gestão do FGTS. O banco pediu à Justiça a declaração da greve como abusiva, mas o TST manteve as regras do acordo coletivo anterior até o julgamento final. Representantes sindicais afirmam que a liminar não obriga o retorno de todas as áreas, apenas daquelas ligadas a demandas sociais, e criticam a tentativa de normalizar a operação antes do julgamento. Enquanto a situação não é resolvida, clientes relatam dificuldades para resolver pendências nas agências.', 'https://api.proradiobr.com/imagens-publicas/tst-determina-que-caixa-mantenha-60-dos-funcionarios-em-atividade-durante-a.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-28 22:17:16.228565+00', 1008, true, 'TST determina 60% da operação da Caixa ativa durante greve', 'TST impôs multa a sindicatos e determinou que 60% dos funcionários da Caixa sigam em atividade durante a greve, com julgamento do dissídio na terça-feira.'),
  ('823c97a0-a0b4-44ff-a788-eadbfe67f8ec', 'Chico Buarque aciona polícia após ameaça de morte feita por médico em site de jornal', 'chico-buarque-aciona-policia-apos-ameaca-de-morte-feita-por-medico-em-site-de', 'Chico Buarque registrou boletim de ocorrência após ameaça de morte feita por médico em site paulista. Autor foi identificado e a Polícia Civil do RJ vai investigar o caso.', 'O cantor e compositor Chico Buarque, 82 anos, acionou a Polícia Civil do Rio de Janeiro nesta segunda-feira (28/9) para registrar uma ameaça de morte. A ofensa, que dizia "adoraria abreviar a vida deste desgraçado", foi encontrada na área de comentários do site de um jornal de grande circulação em São Paulo. Os advogados do artista, Maíra Fernandes e João Vicente Tinoco, protocolaram uma notícia-crime solicitando a abertura de inquérito para apurar a autoria e responsabilizar o suspeito por crimes de informática e ameaça.

O autor da publicação foi identificado como um médico inscrito no Conselho Regional de Medicina de Minas Gerais (CRM-MG). Após a identificação, o veículo de imprensa removeu a mensagem por violação dos termos de uso. Segundo a defesa, a agressão verbal teria relação com as posições políticas do compositor. A Delegacia de Crimes de Informática da Polícia Civil do Rio de Janeiro deve instaurar um inquérito policial nos próximos dias para investigar as circunstâncias do fato e confirmar a responsabilidade do suspeito. O caso segue em investigação para esclarecer todos os detalhes da denúncia.', 'https://api.proradiobr.com/imagens-publicas/chico-buarque-aciona-policia-apos-ameaca-de-morte-feita-por-medico-em-site-de.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-28 22:30:23.137553+00', 1003, true, 'Chico Buarque aciona polícia após ameaça de morte por médico', 'Artista de 82 anos registrou ocorrência após ameaça em site de jornal. Médico foi identificado e caso será investigado pela Polícia Civil do Rio.'),
  ('5ba32392-c950-4faa-a739-e32367390b5a', 'Idoso morre após sofrer descarga elétrica em Ribeira do Pombal', 'idoso-morre-apos-sofrer-descarga-eletrica-em-ribeira-do-pombal', 'Francisco Alves dos Santos, 66 anos, morreu após tocar em fio desencapado no povoado Nova Esperança, zona rural de Ribeira do Pombal. SAMU e Polícia Técnica atenderam a ocorrência.', 'Um homem de 66 anos morreu após sofrer uma descarga elétrica no último sábado (26), por volta das 8h. O incidente ocorreu no povoado Nova Esperança, situado na zona rural de Ribeira do Pombal, na Bahia.

Segundo informações preliminares, a vítima, identificada como Francisco Alves dos Santos, teria tocado acidentalmente em um fio desencapado, o que resultou na fatalidade. Profissionais do Serviço de Atendimento Móvel de Urgência (SAMU) foram acionados e deslocaram-se até o local da ocorrência. No entanto, ao chegarem, a equipe constatou que o óbito já havia sido registrado, não restando possibilidades de intervenção clínica.

Diante dos fatos, o Departamento de Polícia Técnica foi acionado para realizar os procedimentos periciais no local. O corpo da vítima foi removido para a realização de exames complementares e necropsia, seguindo o protocolo padrão para casos de morte de causa externa. As circunstâncias exatas do acidente estão sendo apuradas pelas autoridades competentes.', 'https://api.proradiobr.com/imagens-publicas/idoso-morre-apos-sofrer-descarga-eletrica-em-ribeira-do-pombal.webp', '7d34292b-4217-4571-ba21-f7aa996aa1d3', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-28 23:35:45.093596+00', 110, true, 'Idoso morre vítima de choque elétrico em Ribeira do Pombal', NULL),
  ('e86d9e8a-87b2-48bb-9d8a-7cf812854ea7', 'Homem é preso em Ribeira do Pombal por suspeita de tentar matar ex-companheira com facão', 'homem-e-preso-em-ribeira-do-pombal-por-suspeita-de-tentar-matar-ex-companheira', 'Um homem de 46 anos foi preso em Ribeira do Pombal, na Bahia, sob suspeita de tentativa de feminicídio. Ele é acusado de tentar matar a ex-companheira com um golpe de facão. A vítima foi socorrida pela filha.', 'Um homem de 46 anos foi detido na segunda-feira (28) em Ribeira do Pombal, no nordeste da Bahia, sob suspeita de tentar assassinar sua ex-companheira, de 52 anos. O crime, classificado como tentativa de feminicídio, teria ocorrido com um golpe de facão desferido no braço da vítima. A prisão foi efetuada em cumprimento a um mandado de prisão preventiva.

De acordo com as investigações da Polícia Civil, o incidente aconteceu no dia 16 de setembro, cerca de 15 dias após o término do relacionamento do casal. O suspeito teria ido à residência da mulher e a agredido. A filha do casal interveio na situação, prestando socorro à mãe, que foi encaminhada para atendimento médico. Não foram divulgadas informações sobre o estado de saúde atual da vítima. O agressor foi localizado no centro da cidade pelas equipes da Delegacia Territorial de Ribeira do Pombal, vinculada à 25ª Coordenadoria Regional de Polícia do Interior (Coorpin) de Euclides da Cunha, e permanece à disposição da Justiça.', 'https://api.proradiobr.com/', '7d34292b-4217-4571-ba21-f7aa996aa1d3', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-29 00:29:56.486089+00', 1021, true, 'Homem preso em Ribeira do Pombal por tentar matar ex-companheira', 'A Polícia Civil de Ribeira do Pombal prendeu um homem de 46 anos, suspeito de tentar assassinar sua ex-companheira, de 52, com um facão no braço em setembro. Ele está à disposição da Justiça.'),
  ('465be305-3a89-45dd-9d69-a76e7a35d50f', 'Justiça de Paripiranga condena dupla por ofensas à primeira-dama em página de Instagram', 'justica-de-paripiranga-condena-dupla-por-ofensas-a-primeira-dama-em-pagina-de', 'A Justiça de Paripiranga condenou Antônio Carlos Cardoso Santana e Leonardo Nascimento Cruz a pagar R$ 15 mil por danos morais à primeira-dama Daniella Krissila Santa Rosa Rosário. A decisão é referente a publicações ofensivas no Instagram e determinou a remoção do conteúdo.', 'A Justiça de Paripiranga condenou Antônio Carlos Cardoso Santana e Leonardo Nascimento Cruz, conhecido como Léo da Roça, ao pagamento solidário de R$ 15 mil por danos morais. A ação foi movida pela primeira-dama Daniella Krissila Santa Rosa Rosário, que foi alvo de publicações ofensivas na página PoliNews, no Instagram. Segundo a sentença, o conteúdo associava Daniella à suposta prática de peculato e fazia referências à sua vida familiar. O juiz André Andrade Vieira considerou que as postagens ultrapassaram os limites da liberdade de expressão, atingindo a honra e a imagem da autora.

Além da indenização, a decisão judicial determinou a remoção das publicações no prazo de 24 horas após a intimação. Também ficou proibida a realização de novas postagens caluniosas ou difamatórias, sob pena de multa diária de R$ 500, limitada inicialmente a R$ 10 mil. Em uma segunda ação, movida por Leonardo contra Daniella e Antônio Carlos, os pedidos foram julgados improcedentes pela Justiça. A sentença foi assinada em 26 de setembro de 2026 e ainda está sujeita a recurso.', 'https://api.proradiobr.com/', '677f9a5e-4050-4ad1-94a5-76c2b779098a', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-29 00:33:16.386212+00', 1021, true, 'Justiça de Paripiranga condena dupla por ofensas à primeira-dama no Instagram', 'Em Paripiranga, a Justiça condenou Antônio Carlos Cardoso Santana e Leonardo Nascimento Cruz a indenizar em R$ 15 mil a primeira-dama por publicações ofensivas.'),
  ('84627a72-7912-47be-9a72-ea14157ff8b4', 'Motociclista morre em acidente na BR-110, próximo a Cipó', 'motociclista-morre-em-acidente-na-br-110-proximo-a-cipo', 'Um motociclista de 31 anos, identificado como Allef Carlos Jesus dos Santos, morreu após um acidente na BR-110, próximo a Cipó. O fato ocorreu no último sábado (26) e a Polícia Rodoviária Federal investigará as circunstâncias.', 'Um motociclista de 31 anos faleceu após um acidente ocorrido na noite do último sábado (26), na BR-110, em um trecho localizado próximo ao município de Cipó. O sinistro foi registrado por volta das 22h, no quilômetro 190 da rodovia, e a vítima foi identificada como Allef Carlos Jesus dos Santos.

De acordo com informações fornecidas pela Polícia Rodoviária Federal (PRF), Allef conduzia uma motocicleta Honda Pop 110 S no momento do ocorrido. A PRF foi acionada e compareceu ao local para realizar o registro da ocorrência e adotar as providências cabíveis. O óbito do motociclista foi constatado ainda no local do acidente. Até o presente momento, a dinâmica exata da colisão não foi divulgada pelas autoridades. As circunstâncias que levaram ao acidente deverão ser devidamente investigadas.', 'https://api.proradiobr.com/', '3949c67e-3936-409d-9600-28782301730d', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-29 00:40:18.338944+00', 1025, true, 'Motociclista morre em acidente na BR-110 próximo a Cipó', 'Allef Carlos Jesus dos Santos, de 31 anos, faleceu em acidente na BR-110, próximo a Cipó, no último sábado. A PRF esteve no local e investiga a dinâmica.'),
  ('987342ba-299f-42d8-bcd2-b75e4b047f45', 'Motociclista morre ao colidir com animal na BA-390 em Sítio do Quinto', 'motociclista-morre-ao-colidir-com-animal-na-ba-390-em-sitio-do-quinto', 'Laercio morreu e sua esposa ficou ferida após colisão com um animal na BA-390, em Sítio do Quinto. Um idoso que tentava recolher o bicho também foi atingido.', 'Um homem morreu após se envolver em um acidente de trânsito na rodovia BA-390, no trecho que atravessa o município de Sítio do Quinto. A colisão ocorreu no sentido de Antas, nas proximidades da Chácara Oliveira. A vítima foi identificada como Laercio, conhecido popularmente como Laercio do Pastel.

De acordo com informações preliminares, a motocicleta era ocupada por duas pessoas no momento em que bateu em um animal que havia pulado a cerca de uma roça e adentrado a pista. O impacto foi fatal para Laercio, que não resistiu aos ferimentos e faleceu no local. Sua esposa, que estava na garupa, também foi atingida e sofreu lesões.

Além dos ocupantes do veículo, um homem de 72 anos, que tentava recolher o animal à roça no instante da colisão, também foi atingido. Ele necessitou de remoção para o hospital de Ribeira do Pombal para receber atendimento médico especializado. O Serviço de Atendimento Móvel de Urgência (Samu) foi acionado para socorrer as vítimas feridas. As circunstâncias exatas do acidente ainda serão apuradas pelas autoridades competentes. Até o momento, não foram divulgados detalhes sobre o estado de saúde da esposa de Laercio e do idoso ferido.', 'https://api.proradiobr.com/imagens-publicas/motociclista-morre-ao-colidir-com-animal-na-ba-390-em-sitio-do-quinto.webp', 'd76a6809-0f03-45b2-83a5-70f0f308ca0c', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-29 12:15:22.299866+00', 115, true, 'Motociclista morre em acidente com animal na BA-390 em Sítio do Quinto', NULL),
  ('4c1fa4bc-c801-4df4-b21e-2647ff34f4a0', 'Suspeito de furtos a residências é preso em flagrante em Olindina', 'suspeito-de-furtos-a-residencias-e-preso-em-flagrante-em-olindina', 'Um indivíduo suspeito de furtos a residências e estabelecimentos foi preso em flagrante pela Polícia Militar de Olindina. A prisão ocorreu após relatos de invasão a uma residência, levando à recuperação de uma bolsa e apreensão de uma haste de metal.', 'Um indivíduo suspeito de praticar furtos em residências e estabelecimentos comerciais foi preso em flagrante pela Polícia Militar de Olindina nesta segunda-feira (28). A ação ocorreu por volta das 9h30, após a 6ª Companhia Independente de Polícia Militar (CIPM) ser acionada por populares. As denúncias indicavam que o suspeito estaria pulando muros de quintais e havia invadido uma residência na cidade.

Durante as diligências, a guarnição conseguiu localizar o indivíduo. Segundo o relato policial, o suspeito teria subtraído do imóvel uma bolsa rosa da marca Arezzo, que foi prontamente recuperada. Além disso, foi encontrada em sua posse uma haste de metal, descrita como semelhante a um raio de motocicleta, que possivelmente seria utilizada para alcançar objetos ou auxiliar na abertura de fechaduras mais frágeis. Diante da situação, o homem recebeu voz de prisão e foi conduzido à Delegacia Territorial de Olindina para a formalização do Auto de Prisão em Flagrante (APF) e adoção das medidas legais cabíveis.', 'https://api.proradiobr.com/imagens-publicas/suspeito-de-furtos-a-residencias-e-preso-em-flagrante-em-olindina.webp', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-29 14:47:00.950784+00', 1020, true, 'Suspeito de furtos é preso em flagrante pela PM em Olindina', 'A Polícia Militar de Olindina prendeu um suspeito de furtos a residências após ser acionada por populares. Uma bolsa foi recuperada e uma haste de metal apreendida. O homem foi levado à delegacia.'),
  ('e7a74d59-5a7a-4657-a69d-f53b985092a5', 'Mensagens e fotos indicam Flávio Bolsonaro em festas com garotas de programa no Rio', 'mensagens-e-fotos-indicam-flavio-bolsonaro-em-festas-com-garotas-de-programa-no', 'Mensagens e fotos, obtidas pelo site PlatôBR, sugerem o envolvimento do senador Flávio Bolsonaro em festas privadas com garotas de programa no Rio. O material foi guardado por um ex-sócio, que teria tentado vazar o caso à esposa do parlamentar após uma desavença financeira.', 'Mensagens de WhatsApp e fotos, arquivadas por Alexandre Santini, ex-sócio e antigo amigo de Flávio Bolsonaro (PL-RJ), indicam que o senador participou de festas privadas com garotas de programa. O material, revelado pelo site PlatôBR, sugere que Bolsonaro, posteriormente, tentou evitar que o assunto chegasse à sua família. A reportagem detalha que Santini, que rompeu com o senador há cerca de três anos por uma disputa financeira, teria reunido provas para sustentar suas acusações. Ele teria, inclusive, procurado a dentista Fernanda Bolsonaro, esposa do parlamentar, para informar sobre os encontros. As evidências incluem conversas nas quais Santini combinava festas e pedia sigilo, mencionando o período eleitoral como justificativa para a discrição.

Em uma das trocas de mensagens, Santini negocia uma festa em um hotel de luxo na Barra da Tijuca, no Rio de Janeiro, com uma agenciadora de garotas de programa. Ele se referia a Flávio Bolsonaro como "meu filho" em algumas comunicações. Flávio Bolsonaro, ao tomar conhecimento de que Santini havia contatado sua esposa, teria reagido com uma mensagem pedindo o afastamento do ex-aliado. No texto, atribuído ao senador, ele expressa arrependimento por escolhas passadas e reforça o valor de sua família. Santini, por sua vez, respondeu à mensagem de Flávio com surpresa, questionando se o texto havia sido enviado à pessoa certa. O UOL procurou a campanha de Flávio Bolsonaro para um posicionamento e tentou contato com Alexandre Santini, mas aguarda retorno.', 'https://api.proradiobr.com/imagens-publicas/mensagens-e-fotos-indicam-flavio-bolsonaro-em-festas-com-garotas-de-programa-no.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-29 19:17:28.165674+00', 1006, true, 'Flávio Bolsonaro: Mensagens indicam festas com garotas de programa no Rio', 'Material obtido por ex-sócio de Flávio Bolsonaro aponta participação do senador em festas privadas com garotas de programa e tentativa de conter o vazamento do caso à família.'),
  ('a9ed05f9-dbe8-48d8-8461-a7ed17b51efd', 'Professor da rede municipal é investigado por suposta agressão a criança de 8 anos em Ilhéus', 'professor-da-rede-municipal-e-investigado-por-suposta-agressao-a-crianca-de-8', 'Professor de Ilhéus é investigado por suposta agressão a criança de 8 anos com cipó, segundo denúncia da família.', 'Um professor da rede municipal de ensino de Ilhéus, no sul da Bahia, é investigado pela Polícia Civil após a família de uma criança de 8 anos denunciar uma suposta agressão com cipó. Segundo o relato da mãe, o menino teria sido perseguido e atingido em diferentes partes do corpo na última sexta-feira (25), quando brincava na rua, próximo à residência. A mãe informou à polícia que o homem teria alegado que a criança o ofendeu com termos pejorativos, motivando a conduta agressiva.

A família relatou que a criança ficou com marcas no queixo, peito e costas. A denúncia foi registrada no domingo (27) e o menino passou por exame de corpo de delito no Departamento de Polícia Técnica (DPT). A 1ª Delegacia Territorial (DT) de Ilhéus conduz a apuração do caso, ouvindo testemunhas e expedindo guias para novos exames. O caso também foi encaminhado ao Conselho Tutelar e ao Ministério Público.

Em nota, a Secretaria Municipal de Educação de Ilhéus informou que tomou conhecimento dos fatos no sábado (26). A pasta destacou que a ocorrência teria acontecido fora das dependências da escola e sem relação com atividades pedagógicas. A secretaria acionou o Conselho Tutelar, acompanhou a família no registro da ocorrência e encaminhou o caso à Corregedoria para apuração das medidas administrativas cabíveis, reafirmando o compromisso com a preservação dos direitos da criança.', 'https://api.proradiobr.com/imagens-publicas/professor-da-rede-municipal-e-investigado-por-suposta-agressao-a-crianca-de-8.webp', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-29 19:24:09.350152+00', 1007, true, 'Professor é investigado por suposta agressão a criança de 8 anos em Ilhéus', 'Polícia Civil investiga suposta agressão de professor a criança de 8 anos em Ilhéus. Secretaria de Educação encaminha caso à Corregedoria e Conselho Tutelar.'),
  ('10f66ad6-d6e3-455a-a113-c9cba5320342', 'Concurso DETRAN-SP oferece 145 vagas para Agente de Trânsito com salários de R$ 5,7 mil', 'concurso-detran-sp-oferece-145-vagas-para-agente-de-transito-com-salarios-de-r', 'O DETRAN-SP abriu concurso com 145 vagas imediatas e cadastro de reserva para Agente Estadual de Trânsito. Candidatos com nível superior em qualquer área podem concorrer a salários de R$ 5.702,18. As inscrições vão até 7 de outubro de 2026, com provas em 1º de novembro.', 'O Departamento Estadual de Trânsito de São Paulo (DETRAN-SP) abriu concurso público para o cargo de Agente Estadual de Trânsito, com a oferta de 145 vagas imediatas e formação de cadastro de reserva. As oportunidades são destinadas a candidatos com nível superior completo em qualquer área de formação, além de exigência de CNH categoria B, com remuneração inicial de R$ 5.702,18. O regime de contratação é via CLT, e o salário pode ser acrescido de auxílio-alimentação, adicionais e bonificações.

Os interessados podem realizar suas inscrições exclusivamente pela internet, no site do Instituto Avalia (avalia.org.br), no período de 9 de setembro a 7 de outubro de 2026, até as 23h59. A taxa de inscrição foi definida em R$ 98,00. O processo seletivo incluirá Prova Objetiva e Prova de Redação, ambas programadas para 1º de novembro de 2026, no período da tarde. As avaliações serão aplicadas em 17 cidades-polo no estado de São Paulo, incluindo Araçatuba, Araraquara, Bauru, Campinas, Guarulhos, Itapeva, Osasco, Ourinhos, Piracicaba, Presidente Prudente, Ribeirão Preto, Santos, São José do Rio Preto, São José dos Campos, São Paulo, Sorocaba e Taubaté.', 'https://api.proradiobr.com/imagens-publicas/concurso-detran-sp-oferece-145-vagas-para-agente-de-transito-com-salarios-de-r.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-29 19:24:36.423316+00', 1007, true, 'Concurso DETRAN-SP: 145 Vagas para Agente de Trânsito com Salário de R$ 5,7 Mil', 'O DETRAN-SP abre concurso para Agente Estadual de Trânsito, oferecendo 145 vagas para nível superior. Salários iniciais de R$ 5.702,18. Inscrições até 7/10/2026.'),
  ('ae226342-9f46-4744-869a-acc0f2b993b4', 'Renato Aragão e filha terão audiência de conciliação sobre dívida', 'renato-aragao-e-filha-terao-audiencia-de-conciliacao-sobre-divida', 'Renato Aragão e a filha Juliana Rangel terão audiência de conciliação em 26 de outubro, no Rio de Janeiro, para discutir cobrança de dívida.', 'Uma audiência de conciliação entre o artista Renato Aragão e a filha, Juliana Rangel, foi agendada para o dia 26 de outubro, na cidade do Rio de Janeiro. O encontro judicial visa tratar de uma disputa financeira em que a filha cobra a devolução de valores que afirma ter emprestado ao pai.

A data do processo marca um novo capítulo na relação familiar e financeira entre os envolvidos, que agora se dirimirá em ambiente judicial. A audiência de conciliação é um procedimento comum na Justiça brasileira, utilizado para tentar resolver litígios sem a necessidade de um julgamento completo, buscando um acordo mútuo entre as partes.

Até o momento, não foram divulgados detalhes adicionais sobre o valor exato da dívida cobrada nem sobre a posição oficial de Renato Aragão em relação às alegações de Juliana Rangel. O caso segue sob sigilo, e as partes têm direito de apresentar suas defesas e argumentos perante o juiz responsável pelo caso. A decisão final sobre a existência ou não do débito, bem como sobre qualquer eventual pagamento, dependerá do desfecho das tratativas ou de uma sentença judicial caso a conciliação não seja alcançada.', 'https://api.proradiobr.com/imagens-publicas/renato-aragao-e-filha-terao-audiencia-de-conciliacao-sobre-divida.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-29 19:30:23.083652+00', 1004, true, 'Renato Aragão e filha terão audiência sobre dívida em outubro', 'Renato Aragão e Juliana Rangel terão audiência de conciliação em 26 de outubro no Rio de Janeiro para tratar de cobrança de dívida.'),
  ('a242cb6f-d187-4ee3-8a7d-c41b69c62a3c', 'Euclides da Cunha: Operação da Polícia Civil apura fraude bancária e bloqueia bens', 'euclides-da-cunha-operacao-da-policia-civil-apura-fraude-bancaria-e-bloqueia', 'Operação Falsa Proteção apura fraudes bancárias em Euclides da Cunha e Canudos. Bem de quatro investigados foram bloqueados pela Justiça.', 'A Polícia Civil da Bahia deflagrou, nesta terça-feira (29), a Operação Falsa Proteção, com ações simultâneas em Euclides da Cunha e Canudos. A investigação apura fraudes cometidas contra clientes de uma agência bancária na região. Segundo as apurações, os investigados teriam aberto contas, solicitado cartões de crédito e contratado empréstimos sem o consentimento das vítimas. A polícia também identificou movimentações financeiras suspeitas entre as contas abertas de forma fraudulenta e contas de terceiros.

Em Euclides da Cunha, equipes cumpriram mandado de busca e apreensão na casa de um homem de 37 anos, no centro da cidade. Foram recolhidos três celulares, dois notebooks, R$ 35.450 em espécie e documentos ligados ao inquérito. Duas armas de fogo encontradas no imóvel estavam devidamente documentadas e legalizadas, conforme a Polícia Civil. Já em Canudos, no bairro Califórnia, os policiais foram até a residência de uma mulher de 36 anos e apreenderam dois celulares, um notebook e documentos de interesse da investigação.

A Justiça autorizou o bloqueio de até R$ 138.700 nas contas dos quatro investigados. Também foi determinada a restrição judicial de três veículos, cujos valores somados chegam a aproximadamente R$ 240 mil. A operação foi conduzida pelas Delegacias Territoriais de Canudos e Euclides da Cunha, com apoio da 25ª COORPIN, do GATTI/Conselheiro e da Polícia Militar da Bahia.', 'https://api.proradiobr.com/imagens-publicas/euclides-da-cunha-operacao-da-policia-civil-apura-fraude-bancaria-e-bloqueia.webp', '32987db5-45a5-4de9-8212-7e87dbc8f24e', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-30 17:41:19.213657+00', 105, true, 'Euclides da Cunha: Operação apura fraude bancária e bloqueia bens', NULL),
  ('8e0b951d-5595-4ce8-8664-42e425698d29', 'Justiça condena homem a 12 anos de prisão após agressão que matou idoso em Euclides da Cunha', 'justica-condena-homem-a-12-anos-de-prisao-apos-agressao-que-matou-idoso-em', 'Homem foi condenado a 12 anos de prisão em regime fechado pela morte de um idoso de 62 anos após agressão em Euclides da Cunha.', 'A Justiça condenou Antônio José dos Santos Santana Filho a 12 anos de reclusão em regime inicial fechado pela morte de Rosenildo Rodrigues da Silva, de 62 anos, em Euclides da Cunha. A sentença foi proferida na última quinta-feira (24). De acordo com o processo, o réu desferiu dois socos na vítima no dia 29 de março de 2025, causando um traumatismo cranioencefálico após a queda. Rosenildo foi internado, mas não resistiu aos ferimentos e faleceu no hospital em 9 de abril.

Durante o julgamento, os jurados reconheceram a autoria e a materialidade do crime, porém afastaram a intenção de matar, o que impediu a condenação por homicídio doloso. Na fixação da pena, o magistrado considerou circunstâncias agravantes, como o motivo fútil, a dificuldade de defesa da vítima e a idade superior a 60 anos. O documento judicial também destacou a ausência de prestação de socorro, fato admitido pelo próprio acusado, que não auxiliou a vítima mesmo após vê-la caída e ferida.', 'https://api.proradiobr.com/imagens-publicas/justica-condena-homem-a-12-anos-de-prisao-apos-agressao-que-matou-idoso-em.webp', '32987db5-45a5-4de9-8212-7e87dbc8f24e', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-30 17:44:33.008842+00', 103, true, 'Justiça condena homem a 12 anos de prisão por morte de idoso em Euclides da Cunha', NULL),
  ('30e86e45-09f9-4f97-beb5-1d6af2243dc7', 'Greve dos bancários da Caixa é encerrada e atendimento presencial é retomado', 'greve-dos-bancarios-da-caixa-e-encerrada-e-atendimento-presencial-e-retomado', 'A Caixa Econômica Federal retomou o atendimento presencial após o fim da greve dos bancários. O TST encerrou a negociação coletiva e definiu reajuste salarial de 4,6%, encerrando a paralisação que durou desde setembro.', 'A greve nacional dos bancários da Caixa Econômica Federal chegou ao fim nesta quarta-feira (30), com a retomada do atendimento presencial nas agências em todo o país. A Caixa confirmou a decisão por meio de nota oficial, informando que o processo de negociação coletiva submetido à Justiça do Trabalho foi encerrado após o julgamento realizado pelo Tribunal Superior do Trabalho (TST) na terça-feira (29). Sindicatos e confederações de bancários também confirmaram o retorno imediato das atividades.

A paralisação havia iniciado em 10 de setembro e o principal impasse entre as partes era o convênio médico, com 54 rodadas de negociação e três propostas rejeitadas pela categoria. No julgamento, o TST considerou a paralisação não abusiva, determinou o retorno imediato sob pena de multa e fixou um reajuste salarial de 4,6%. O ministro Maurício Godinho manteve o percentual de desconto no plano de saúde em 3,5% sobre o salário-base, com teto de 7%. Durante a greve, os canais digitais e os caixas eletrônicos permaneceram funcionando normalmente.', 'https://api.proradiobr.com/imagens-publicas/greve-dos-bancarios-da-caixa-e-encerrada-e-atendimento-presencial-e-retomado.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-30 17:44:40.415987+00', 1003, true, 'Caixa retoma atendimento presencial após fim da greve dos bancários', 'Greve dos bancários da Caixa é encerrada após decisão do TST. Atendimento presencial volta a todo o país com reajuste salarial de 4,6% definido.'),
  ('dd55bc59-2385-4f58-92fa-fac66a9f8651', 'AtlasIntel aponta candidatos do PT à frente em capitais do Nordeste', 'atlasintel-aponta-candidatos-do-pt-a-frente-em-capitais-do-nordeste', 'Pesquisas da AtlasIntel mostram candidatos do PT liderando em capitais nordestinas, incluindo Bahia, Ceará e Piauí, enquanto Pernambuco apresenta empate técnico.', 'Pesquisas divulgadas pela AtlasIntel, em parceria com o Grupo A TARDE, indicam que candidatos filiados ao Partido dos Trabalhadores lideram as intenções de voto para os governos estaduais em diversas capitais do Nordeste. Na Bahia, o governador Jerônimo Rodrigues mantém a liderança; no Ceará, Elmano de Freitas consolida a vantagem sobre Ciro Gomes; e no Rio Grande do Norte, Cadu de Lula apresenta expressiva frente sobre os principais opositores.

No Piauí, Rafael Fonteles registra alta aprovação que sugere reeleição no primeiro turno. Em Pernambuco, o cenário é de empate técnico entre a governadora Raquel Lyra e João Campos, segundo os levantamentos. As pesquisas, realizadas entre os dias 23 e 28 de setembro, utilizaram metodologia de Recrutamento Digital Aleatório (Atlas RDR). As margens de erro variam entre dois e três pontos percentuais, com nível de confiança de 95%. Os dados refletem o cenário eleitoral atual nas respectivas regiões e servem como referência para a dinâmica das campanhas em andamento.', 'https://api.proradiobr.com/imagens-publicas/atlasintel-aponta-candidatos-do-pt-a-frente-em-capitais-do-nordeste.webp', '29041cc7-195c-4973-b71d-c3c5e37c70bf', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-30 17:48:44.807892+00', 1009, true, 'AtlasIntel: PT lidera em capitais nordestinas', 'Pesquisas apontam candidatos do PT à frente em Bahia, Ceará, RN e Piauí, com cenários variados e empate técnico em Pernambuco.'),
  ('b4ac47bc-3c29-47a8-acc0-fd348348daf2', 'Suspeito de tentativa de feminicídio é preso em Ribeira do Pombal', 'suspeito-de-tentativa-de-feminicidio-e-preso-em-ribeira-do-pombal', 'Homem de 46 anos foi preso em Ribeira do Pombal suspeito de agredir a ex-companheira com facão. A filha da vítima interveio e socorreu a mulher.', 'Um homem de 46 anos foi preso nesta segunda-feira (28), no centro de Ribeira do Pombal, por ser suspeito de tentar matar a ex-companheira, de 52 anos, com golpes de facão. Segundo as investigações da Polícia Civil, o crime ocorreu quinze dias após o término do relacionamento, quando o investigado se dirigiu à residência da vítima para praticar a agressão.

A intervenção da filha do casal impediu que a situação se agravasse. A jovem socorreu a mãe e a conduziu imediatamente para atendimento médico. Após a formalização da prisão preventiva, o suspeito foi entregue às autoridades competentes e permanece à disposição da Justiça. A operação foi conduzida pela Delegacia Territorial de Ribeira do Pombal, vinculada à 25ª Coordenadoria Regional de Polícia do Interior, com sede em Euclides da Cunha.', 'https://api.proradiobr.com/imagens-publicas/suspeito-de-tentativa-de-feminicidio-e-preso-em-ribeira-do-pombal.webp', '7d34292b-4217-4571-ba21-f7aa996aa1d3', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-30 17:52:56.692056+00', 103, true, 'Suspeito de tentativa de feminicídio é preso em Ribeira do Pombal', NULL),
  ('a97ac775-43fb-41f1-9e5e-ac932fdd303a', 'Antas: Áudio de Marcelo Nilo com ofensas a prefeita de Morro do Chapéu vazou', 'antas-audio-de-marcelo-nilo-com-ofensas-a-prefeita-de-morro-do-chapeu-vazou', 'Um áudio vazado do deputado federal Marcelo Nilo revelou ofensas à prefeita de Morro do Chapéu, Juliana Araújo. A gravação, cuja autenticidade foi confirmada, menciona um desentendimento ocorrido em Jacobina entre os dois políticos que apoiam ACM Neto.', 'Um áudio com conteúdo de xingamentos atribuído ao deputado federal Marcelo Nilo vazou e foi divulgado pelo Portal Moisés. A gravação expõe uma série de ofensas direcionadas a Juliana Araújo, atual prefeita de Morro do Chapéu. A autenticidade do material foi confirmada pelo portal Política ao Vivo, que consultou uma fonte próxima à gestora municipal para verificar a procedência. No áudio, Nilo teria proferido termos pejorativos, como “filha da pu**”, “vagabu***” e “pu***”, ao comentar sobre a prefeita.

Durante a gravação, o deputado federal faz menção a um desentendimento anterior com a prefeita Juliana Araújo, que teria ocorrido em um palanque durante um evento político na cidade de Jacobina. O incidente ocorre em um cenário onde ambos os políticos, Juliana Araújo e Marcelo Nilo, são publicamente apoiadores da candidatura de ACM Neto ao governo da Bahia. A situação revela uma aparente tensão entre as figuras políticas, apesar de estarem no mesmo grupo de apoio para as eleições estaduais.', 'https://api.proradiobr.com/imagens-publicas/antas-audio-de-marcelo-nilo-com-ofensas-a-prefeita-de-morro-do-chapeu-vazou.webp', '91925efe-8c0d-42a7-8e21-1d167b8f670b', '1e79060a-b850-4054-ae69-783db846d5fd', '2026-09-30 21:16:18.162031+00', 1010, true, 'Áudio de Marcelo Nilo vaza com ofensas a prefeita de Morro do Chapéu | Antas', 'Deputado federal Marcelo Nilo é flagrado em áudio com xingamentos contra Juliana Araújo, prefeita de Morro do Chapéu. A gravação, confirmada, detalha atrito em Jacobina. Ambos apoiam ACM Neto. Notícia para a região de Antas.')
